            min_cost = min_cost.min((k - a % k) % k);

            if a % 2 == 0 {
                even_count += 1;
            }
        }

        let answer = if k == 4 {
            min_cost.min((2 - even_count).max(0))
        } else {
            min_cost
        };

        output.push_str(&format!("{answer}\n"));
    }

    let stdout = io::stdout();
