        let first: i64 = iter.next().unwrap().parse().unwrap();
        let mut previous = first;
        let mut current_sum = first;
        let mut answer = first;

        for _ in 1..n {
            let value: i64 = iter.next().unwrap().parse().unwrap();

            if (value & 1) != (previous & 1) {
                current_sum = value.max(current_sum + value);
            } else {
                current_sum = value;
            }

            answer = answer.max(current_sum);
            previous = value;
        }

        writeln!(out, "{answer}").unwrap();
    }
}
