            answer += counts.get(&x).copied().unwrap_or(0);

            if x == 1 {
                answer += counts.get(&2).copied().unwrap_or(0);
            } else if x == 2 {
                answer += counts.get(&1).copied().unwrap_or(0);
            }

            *counts.entry(x).or_insert(0) += 1;
        }

        writeln!(out, "{answer}").unwrap();
    }
