fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let rows: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i64> = values.map(|s| s.parse().unwrap()).collect();
    let cols = numbers.len() / rows;

    let mut matrix = Vec::with_capacity(rows);
    for r in 0..rows {
        let mut row = numbers[r * cols..(r + 1) * cols].to_vec();
        row.sort_unstable();
        matrix.push(row);
    }

    let mut score = 0i64;
    for col in 0..cols {
        let mut column_max = 0i64;
        for row in &matrix {
            column_max = column_max.max(row[col]);
        }
        score += column_max;
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{score}").unwrap();
}
