    let mut max_product = nums[0];
    let mut min_product = nums[0];

    for &x in &nums[1..] {
        let old_max = max_product;
        let old_min = min_product;

        max_product = old_max
            .max(x)
            .max(old_max * x)
            .max(old_min * x);

        min_product = old_min
            .min(x)
            .min(old_max * x)
            .min(old_min * x);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", max_product).unwrap();
