    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i32> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    if values.len() < 3 {
        return;
    }

    let money = *values.last().unwrap();
    let mut cheapest = i32::MAX;
    let mut second_cheapest = i32::MAX;

    for &price in &values[..values.len() - 1] {
        if price < cheapest {
            second_cheapest = cheapest;
            cheapest = price;
        } else if price < second_cheapest {
            second_cheapest = price;
        }
    }

    let cost = cheapest + second_cheapest;
    let answer = if cost <= money { money - cost } else { money };

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
