use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut nums = vec![0i32; n];
    let mut adjacent_count = 0i32;
    let mut answers = Vec::with_capacity(q);

    for _ in 0..q {
        let index: usize = iter.next().unwrap().parse().unwrap();
        let color: i32 = iter.next().unwrap().parse().unwrap();
        let old_color = nums[index];

        if old_color != color {
            if old_color != 0 {
                if index > 0 && nums[index - 1] == old_color {
                    adjacent_count -= 1;
                }
                if index + 1 < n && nums[index + 1] == old_color {
                    adjacent_count -= 1;
                }
            }

            nums[index] = color;

            if index > 0 && nums[index - 1] == color {
                adjacent_count += 1;
            }
            if index + 1 < n && nums[index + 1] == color {
                adjacent_count += 1;
            }
        }

        answers.push(adjacent_count);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{answer}").unwrap();
    }
    writeln!(out).unwrap();
}
