use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] != x {
            self.parent[x] = self.find(self.parent[x]);
        }
        self.parent[x]
    }

    fn union(&mut self, a: usize, b: usize) {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return;
        }
        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<usize> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap())
        .collect();

    let possible = if nums.len() <= 1 {
        true
    } else if nums.iter().any(|&x| x == 1) {
        false
    } else {
        let max_value = *nums.iter().max().unwrap();
        let mut first_index = vec![usize::MAX; max_value + 1];
        let mut dsu = Dsu::new(nums.len());

        for (i, &value) in nums.iter().enumerate() {
            let mut x = value;
            let mut factor = 2usize;

            while factor * factor <= x {
                if x % factor == 0 {
                    if first_index[factor] == usize::MAX {
                        first_index[factor] = i;
                    } else {
                        dsu.union(i, first_index[factor]);
                    }

                    while x % factor == 0 {
                        x /= factor;
                    }
                }
                factor += 1;
            }

            if x > 1 {
                if first_index[x] == usize::MAX {
                    first_index[x] = i;
                } else {
                    dsu.union(i, first_index[x]);
                }
            }
        }

        let root = dsu.find(0);
        (1..nums.len()).all(|i| dsu.find(i) == root)
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", possible).unwrap();
}
