fn parse_integers(s: &str) -> Vec<i64> {
    let mut values = Vec::new();
    let mut current = 0i64;
    let mut in_number = false;
    let mut negative = false;

    for ch in s.chars().chain(std::iter::once(' ')) {
        if ch == '-' && !in_number {
            negative = true;
        } else if ch.is_ascii_digit() {
            current = current * 10 + (ch as i64 - '0' as i64);
            in_number = true;
        } else if in_number {
            values.push(if negative { -current } else { current });
            current = 0;
            in_number = false;
            negative = false;
        } else {
            negative = false;
        }
    }

    values
}

