fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let log_count: usize = it.next().unwrap().parse().unwrap();

    let mut logs = Vec::with_capacity(log_count);
    for _ in 0..log_count {
        let server_id: usize = it.next().unwrap().parse().unwrap();
        let time: i64 = it.next().unwrap().parse().unwrap();
        logs.push((time, server_id));
    }

    let x: i64 = it.next().unwrap().parse().unwrap();

    let queries: Vec<i64> = it.map(|s| s.parse().unwrap()).collect();

    logs.sort_unstable();

    let mut sorted_queries: Vec<(i64, usize)> = queries
        .iter()
        .copied()
        .enumerate()
        .map(|(index, time)| (time, index))
        .collect();
    sorted_queries.sort_unstable();

    let mut frequencies = vec![0usize; n + 1];
    let mut active_servers = 0usize;
    let mut left = 0usize;
    let mut right = 0usize;
    let mut answers = vec![0usize; queries.len()];

    for (query_time, original_index) in sorted_queries {
        while right < logs.len() && logs[right].0 <= query_time {
            let server_id = logs[right].1;
            if frequencies[server_id] == 0 {
                active_servers += 1;
            }
            frequencies[server_id] += 1;
            right += 1;
        }

        let start_time = query_time - x;
        while left < right && logs[left].0 < start_time {
            let server_id = logs[left].1;
            frequencies[server_id] -= 1;
            if frequencies[server_id] == 0 {
                active_servers -= 1;
            }
            left += 1;
        }

        answers[original_index] = n - active_servers;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", answer).unwrap();
    }
    writeln!(out).unwrap();
}
