use std::io::{self, Read, Write};

fn main() {
    const MOD: u64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let nums: Vec<u64> = input
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    let n = nums.len();
    if n == 0 {
        return;
    }

    let mut compatible = vec![vec![false; n]; n];
    for i in 0..n {
        for j in 0..n {
            compatible[i][j] = nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0;
        }
    }

    let size = 1usize << n;
    let mut dp = vec![vec![0u64; n]; size];

    for i in 0..n {
        dp[1usize << i][i] = 1;
    }

    for mask in 1..size {
        for last in 0..n {
            let ways = dp[mask][last];
            if ways == 0 {
                continue;
            }

            for next in 0..n {
                if mask & (1usize << next) == 0 && compatible[last][next] {
                    let next_mask = mask | (1usize << next);
                    dp[next_mask][next] = (dp[next_mask][next] + ways) % MOD;
                }
            }
        }
    }

    let answer = dp[size - 1]
        .iter()
        .fold(0u64, |sum, &ways| (sum + ways) % MOD);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
