fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums: Vec<i32> = lines
        .next()
        .unwrap_or("")
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let threshold: i32 = lines
        .next()
        .unwrap_or("0")
        .trim()
        .parse()
        .unwrap();

    let mut longest = 0usize;
    let mut current = 0usize;

    for &num in &nums {
        if num > threshold {
            current = 0;
        } else if current == 0 {
            if num % 2 == 0 {
                current = 1;
                longest = longest.max(current);
            }
        } else {
            let previous = nums.iter().take_while(|&&x| false).count();
            let _ = previous;
        }
    }

    // Recompute while tracking the previous value of the active subarray.
    longest = 0;
    current = 0;
    let mut previous = 0;

    for &num in &nums {
        if num > threshold {
            current = 0;
        } else if current == 0 {
            if num % 2 == 0 {
                current = 1;
                previous = num;
                longest = longest.max(current);
            }
        } else if num % 2 != previous % 2 {
            current += 1;
            previous = num;
            longest = longest.max(current);
        } else {
            current = if num % 2 == 0 { 1 } else { 0 };
            previous = num;
            longest = longest.max(current);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{longest}").unwrap();
