use std::io::{self, Read, Write};

fn merge(a: &str, b: &str) -> String {
    if a.contains(b) {
        return a.to_string();
    }
    if b.contains(a) {
        return b.to_string();
    }

    let max_overlap = a.len().min(b.len());
    for overlap in (1..=max_overlap).rev() {
        if a.as_bytes()[a.len() - overlap..] == b.as_bytes()[..overlap] {
            let mut result = String::with_capacity(a.len() + b.len() - overlap);
            result.push_str(a);
            result.push_str(&b[overlap..]);
            return result;
        }
    }

    let mut result = String::with_capacity(a.len() + b.len());
    result.push_str(a);
    result.push_str(b);
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let strings: Vec<&str> = input.split_whitespace().take(3).collect();

    let permutations = [
        [0, 1, 2],
        [0, 2, 1],
        [1, 0, 2],
        [1, 2, 0],
        [2, 0, 1],
        [2, 1, 0],
    ];

    let mut answer = String::new();

    for permutation in permutations {
        let first = merge(strings[permutation[0]], strings[permutation[1]]);
        let candidate = merge(&first, strings[permutation[2]]);

        if answer.is_empty()
            || candidate.len() < answer.len()
            || (candidate.len() == answer.len() && candidate < answer)
        {
            answer = candidate;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
