        let y: u32 = iter.next().unwrap().parse().unwrap();
        coordinates.push((x, y));
    }

    let k: u32 = iter.next().unwrap().parse().unwrap();

    let mut seen: HashMap<(u32, u32), i64> = HashMap::new();
    let mut answer: i64 = 0;

