            let target = (x ^ dx, y ^ dy);
            if let Some(&count) = seen.get(&target) {
                answer += count;
            }
        }
        *seen.entry((x, y)).or_insert(0) += 1;
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
