    let mut max_sum = 0_i64;

    for i in 0..n {
        window_sum += nums[i];
        *frequencies.entry(nums[i]).or_insert(0) += 1;

        if i >= k {
            let removed = nums[i - k];
            window_sum -= removed;

            if let Some(count) = frequencies.get_mut(&removed) {
                *count -= 1;
                if *count == 0 {
                    frequencies.remove(&removed);
                }
            }
        }

        if i + 1 >= k && frequencies.len() >= m {
            max_sum = max_sum.max(window_sum);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{max_sum}").unwrap();
