    }

    // dp[i] is the maximum gold using only houses with indices below i.
    let mut dp = vec![0_i64; n + 1];

    for end in 0..n {
        dp[end + 1] = dp[end];

        for &(start, gold) in &offers_by_end[end] {
            dp[end + 1] = dp[end + 1].max(dp[start] + gold);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[n]).unwrap();
