fn is_symmetric(x: i32) -> bool {
    let digits = x.to_string().into_bytes();
    let len = digits.len();

    if len % 2 != 0 {
        return false;
    }

    let half = len / 2;
    let first_sum: u32 = digits[..half]
        .iter()
        .map(|&digit| (digit - b'0') as u32)
        .sum();
    let second_sum: u32 = digits[half..]
        .iter()
        .map(|&digit| (digit - b'0') as u32)
        .sum();

    first_sum == second_sum
}

