use std::io::{self, Read, Write};

const MOD: u64 = 1_000_000_007;

type Matrix = [[u64; 2]; 2];

fn multiply(a: Matrix, b: Matrix) -> Matrix {
    let mut result = [[0u64; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            result[i][j] =
                (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % MOD;
        }
    }
    result
}

fn matrix_power(mut base: Matrix, mut exponent: u64) -> Matrix {
    let mut result = [[1u64, 0u64], [0u64, 1u64]];

    while exponent > 0 {
        if exponent & 1 == 1 {
            result = multiply(result, base);
        }
        base = multiply(base, base);
        exponent >>= 1;
    }

    result
}

fn count_matching_rotations(s: &[u8], t: &[u8]) -> u64 {
    let n = t.len();
    let mut prefix = vec![0usize; n];

    for i in 1..n {
        let mut j = prefix[i - 1];
        while j > 0 && t[i] != t[j] {
            j = prefix[j - 1];
        }
        if t[i] == t[j] {
            j += 1;
        }
        prefix[i] = j;
    }

    let mut matches = 0u64;
    let mut j = 0usize;

    // Scan s + s without its final character, so rotation starts are 0..n-1.
    for i in 0..(2 * n - 1) {
        let ch = s[i % n];

        while j > 0 && ch != t[j] {
            j = prefix[j - 1];
        }
        if ch == t[j] {
            j += 1;
        }

        if j == n {
            matches += 1;
            j = prefix[n - 1];
        }
    }

    matches
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap().as_bytes().to_vec();
    let t = tokens.next().unwrap().as_bytes().to_vec();
    let k: u64 = tokens.next().unwrap().parse().unwrap();

    let n = s.len() as u64;
    let matching_rotations = count_matching_rotations(&s, &t);
    let zero_rotation_matches = if s == t { 1u64 } else { 0u64 };

    // State:
    // a = ways to reach rotation 0
    // b = ways to reach any particular nonzero rotation
    //
    // a' = (n - 1) * b
    // b' = a + (n - 2) * b
    let transition = [
        [0, (n - 1) % MOD],
        [1, (n - 2) % MOD],
    ];

    let powered = matrix_power(transition, k);
    let ways_zero = powered[0][0];
    let ways_nonzero = powered[1][0];

    let answer = (
        zero_rotation_matches * ways_zero
        + (matching_rotations - zero_rotation_matches) % MOD * ways_nonzero
    ) % MOD;

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
