use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let numbers: Vec<u64> = input
        .split_whitespace()
        .map(|s| s.parse::<u64>().unwrap())
        .collect();

    if numbers.len() < 2 {
        return;
    }

    let n = numbers.len() - 1;
    let mut k = numbers[n];

    let mut jump: Vec<usize> = numbers[..n].iter().map(|&x| x as usize).collect();
    let mut sum: Vec<i64> = jump.iter().map(|&x| x as i64).collect();

    let mut current: Vec<usize> = (0..n).collect();
    let mut scores: Vec<i64> = (0..n).map(|i| i as i64).collect();

    while k > 0 {
        if k & 1 == 1 {
            for i in 0..n {
                scores[i] += sum[current[i]];
                current[i] = jump[current[i]];
            }
        }

        k >>= 1;
        if k == 0 {
            break;
        }

        let mut next_jump = vec![0usize; n];
        let mut next_sum = vec![0i64; n];

        for i in 0..n {
            next_jump[i] = jump[jump[i]];
            next_sum[i] = sum[i] + sum[jump[i]];
        }

        jump = next_jump;
        sum = next_sum;
    }

    let answer = scores.into_iter().max().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
