        let mut kernel = 1usize;
        let mut p = 2usize;

        while p * p <= x {
            let mut odd = false;
            while x % p == 0 {
                x /= p;
                odd = !odd;
            }
            if odd {
                kernel *= p;
            }
            p += 1;
        }

        if x > 1 {
            kernel *= x;
        }

        sums[kernel] += value;
    }

    let answer = sums.into_iter().max().unwrap_or(0);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
