use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn parse_numbers(line: &str) -> Vec<usize> {
    line.split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .filter_map(|s| s.parse::<usize>().ok())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input.lines().filter(|line| !line.trim().is_empty()).collect();
    if lines.len() < 3 {
        return;
    }

    let nums = parse_numbers(lines[0]);
    let l = parse_numbers(lines[1])[0];
    let r = parse_numbers(lines[2])[0];

    let mut frequency = vec![0usize; r + 1];
    let mut zero_count = 0usize;

    for value in nums {
        if value == 0 {
            zero_count += 1;
        } else if value <= r {
            frequency[value] += 1;
        }
    }

    let mut dp = vec![0i64; r + 1];
    dp[0] = (zero_count as i64 + 1) % MOD;

    for value in 1..=r {
        let count = frequency[value];
        if count == 0 {
            continue;
        }

        let mut next = vec![0i64; r + 1];

        for remainder in 0..value.min(r + 1) {
            let mut window = 0i64;
            let mut sum = remainder;

            while sum <= r {
                window += dp[sum];
                if window >= MOD {
                    window -= MOD;
                }

                let remove_distance = (count + 1) * value;
                if sum >= remove_distance {
                    window -= dp[sum - remove_distance];
                    if window < 0 {
                        window += MOD;
                    }
                }

                next[sum] = window;
                sum += value;
            }
        }

        dp = next;
    }

    let mut answer = 0i64;
    for sum in l..=r {
        answer += dp[sum];
        if answer >= MOD {
            answer -= MOD;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
