fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let nums: Vec<i64> = nums_line
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    let target: i64 = match lines.next() {
        Some(line) => line.split_whitespace().next().unwrap().parse().unwrap(),
        None => return,
    };

    let n = nums.len();
    let total: i64 = nums.iter().sum();
    let full_cycles = target / total;
    let remainder = target % total;

    let answer = if remainder == 0 {
        full_cycles * n as i64
    } else {
        let mut left = 0usize;
        let mut sum = 0i64;
        let mut shortest = usize::MAX;

        for right in 0..(2 * n) {
            sum += nums[right % n];

            while left <= right && (sum > remainder || right - left + 1 > n) {
                sum -= nums[left % n];
                left += 1;
            }

            if sum == remainder && left < n {
                shortest = shortest.min(right - left + 1);
            }
        }

        if shortest == usize::MAX {
            -1
        } else {
            full_cycles * n as i64 + shortest as i64
        }
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
