fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let s = iter.next().unwrap_or("").as_bytes();
    let k: usize = iter.next().unwrap_or("0").parse().unwrap();

    let mut best: Option<(usize, usize)> = None;

    for start in 0..s.len() {
        let mut ones = 0;

        for end in start..s.len() {
            if s[end] == b'1' {
                ones += 1;
            }

            if ones == k {
                let candidate = &s[start..=end];
                let should_update = match best {
                    None => true,
                    Some((best_start, best_end)) => {
                        let current_best = &s[best_start..best_end];
                        candidate.len() < current_best.len()
                            || (candidate.len() == current_best.len()
                                && candidate < current_best)
                    }
                };

                if should_update {
                    best = Some((start, end + 1));
                }
                break;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if let Some((start, end)) = best {
        out.write_all(&s[start..end]).unwrap();
    }
    writeln!(out).unwrap();
