    io::stdin().read_to_string(&mut input).unwrap();

    let nums = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i64>().ok());

    let mut frequency = HashMap::<i64, usize>::new();
    for value in nums {
        *frequency.entry(value).or_insert(0) += 1;
    }

    if frequency.is_empty() {
        return;
    }

    let frequencies: Vec<usize> = frequency.into_values().collect();
    let min_frequency = *frequencies.iter().min().unwrap();

    for small_size in (1..=min_frequency).rev() {
        let mut total_groups = 0usize;
        let mut valid = true;

        for &count in &frequencies {
            let groups = (count + small_size) / (small_size + 1);

            if groups * small_size > count {
                valid = false;
                break;
            }

            total_groups += groups;
        }

        if valid {
            let stdout = io::stdout();
            let mut out = io::BufWriter::new(stdout.lock());
            writeln!(out, "{total_groups}").unwrap();
            return;
        }
    }
