                answer = answer.min(left_min[j] + nums[j] + right_min[j]);
            }
        }
    }

    let result = if answer == i32::MAX { -1 } else { answer };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{result}").unwrap();
