use std::io::{self, Read, Write};

fn window_cost(nums: &[i64], prefix: &[i64], left: usize, right: usize) -> i64 {
    let mid = (left + right) / 2;
    let median = nums[mid];

    let left_cost = median * (mid - left) as i64 - (prefix[mid] - prefix[left]);
    let right_cost =
        (prefix[right + 1] - prefix[mid + 1]) - median * (right - mid) as i64;

    left_cost + right_cost
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split(|c: char| !(c.is_ascii_digit() || c == '-'))
        .filter(|s| !s.is_empty() && *s != "-")
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    if values.len() < 2 {
        return;
    }

    let k = *values.last().unwrap();
    let mut nums = values[..values.len() - 1].to_vec();
    nums.sort_unstable();

    let n = nums.len();
    let mut prefix = vec![0_i64; n + 1];
    for i in 0..n {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    let mut left = 0usize;
    let mut answer = 1usize;

    for right in 0..n {
        while left < right && window_cost(&nums, &prefix, left, right) > k {
            left += 1;
        }
        answer = answer.max(right - left + 1);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
