use std::io::{self, Read, Write};

fn make_palindrome(prefix: i64, odd_length: bool) -> i64 {
    let mut result = prefix;
    let mut remaining = if odd_length { prefix / 10 } else { prefix };

    while remaining > 0 {
        result = result * 10 + remaining % 10;
        remaining /= 10;
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut nums: Vec<i64> = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i64>().ok())
        .collect();

    if nums.is_empty() {
        return;
    }

    nums.sort_unstable();
    let median = nums[nums.len() / 2];

    let mut palindromes = Vec::new();

    for length in 1..=9 {
        let half_length = (length + 1) / 2;
        let start = if half_length == 1 {
            1_i64
        } else {
            10_i64.pow((half_length - 1) as u32)
        };
        let end = 10_i64.pow(half_length as u32);

        for prefix in start..end {
            let palindrome = make_palindrome(prefix, length % 2 == 1);
            if palindrome < 1_000_000_000 {
                palindromes.push(palindrome);
            }
        }
    }

    let index = palindromes.partition_point(|&p| p < median);
    let mut answer = i64::MAX;

    if index < palindromes.len() {
        let target = palindromes[index];
        let cost: i64 = nums.iter().map(|&value| (value - target).abs()).sum();
        answer = answer.min(cost);
    }

    if index > 0 {
        let target = palindromes[index - 1];
        let cost: i64 = nums.iter().map(|&value| (value - target).abs()).sum();
        answer = answer.min(cost);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
