    if tokens.len() < 5 {
        return;
    }

    let source = tokens[0].as_bytes();
    let target = tokens[1].as_bytes();
    let m = (tokens.len() - 2) / 3;

    const INF: i64 = i64::MAX / 4;
    let mut dist = [[INF; 26]; 26];

    for (i, row) in dist.iter_mut().enumerate() {
        row[i] = 0;
    }

    for i in 0..m {
        let from = tokens[2 + i].as_bytes()[0] as usize - b'a' as usize;
        let to = tokens[2 + m + i].as_bytes()[0] as usize - b'a' as usize;
        let cost: i64 = tokens[2 + 2 * m + i].parse().unwrap();
        dist[from][to] = dist[from][to].min(cost);
    }

    for k in 0..26 {
        for i in 0..26 {
            if dist[i][k] == INF {
                continue;
            }
            for j in 0..26 {
                if dist[k][j] == INF {
                    continue;
                }
                dist[i][j] = dist[i][j].min(dist[i][k] + dist[k][j]);
            }
        }
    }

    let mut answer = 0_i64;

    for (&from, &to) in source.iter().zip(target.iter()) {
        let from = (from - b'a') as usize;
        let to = (to - b'a') as usize;

        if dist[from][to] == INF {
            answer = -1;
            break;
        }

        answer += dist[from][to];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
