        }

        let cycle = half_cycle << 1;
        let full_cycles = total_numbers / cycle;
        let remainder = total_numbers % cycle;

        sum += full_cycles * half_cycle;
        if remainder > half_cycle {
            sum += remainder - half_cycle;
        }

        position += x;
    }

    sum
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let k: u128 = values.next().unwrap().parse().unwrap();
    let x: usize = values.next().unwrap().parse().unwrap();

    let mut low = 0u128;
    let mut high = 1u128;

    while total_price(high, x) <= k {
        high *= 2;
    }

    while low + 1 < high {
        let mid = low + (high - low) / 2;
        if total_price(mid, x) <= k {
            low = mid;
        } else {
            high = mid;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
