use std::io::{self, Read, Write};

fn pow_u64(mut base: u64, mut exp: usize) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp % 2 == 1 {
            result *= base;
        }
        base *= base;
        exp /= 2;
    }
    result
}

fn count_at_most(bound: u64, limit: u8, suffix: &[u8]) -> u64 {
    if bound == 0 || suffix.iter().any(|&d| d > limit) {
        return 0;
    }

    let digits: Vec<u8> = bound
        .to_string()
        .bytes()
        .map(|b| b - b'0')
        .collect();

    let n = digits.len();
    let m = suffix.len();

    if n < m {
        return 0;
    }

    let base = limit as u64 + 1;
    let mut total = 0u64;

    // Count valid numbers with fewer digits than bound.
    for len in m..n {
        let prefix_len = len - m;
        if prefix_len == 0 {
            total += 1;
        } else {
            total += limit as u64 * pow_u64(base, prefix_len - 1);
        }
    }

    // Count valid numbers with the same number of digits as bound.
    let prefix_len = n - m;

    for i in 0..n {
        let bound_digit = digits[i];

        if i < prefix_len {
            let low = if i == 0 { 1 } else { 0 };
            let high = limit;

            let less_choices = if bound_digit <= low {
                0
            } else {
                (bound_digit.min(high + 1) - low) as u64
            };

            let remaining_prefix_digits = prefix_len - i - 1;
            total += less_choices * pow_u64(base, remaining_prefix_digits);

            if bound_digit < low || bound_digit > high {
                return total;
            }
        } else {
            let required = suffix[i - prefix_len];

            if required < bound_digit {
                total += 1;
                return total;
            } else if required > bound_digit {
                return total;
            }
        }
    }

    total + 1
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let start: u64 = iter.next().unwrap().parse().unwrap();
    let finish: u64 = iter.next().unwrap().parse().unwrap();
    let limit: u8 = iter.next().unwrap().parse().unwrap();
    let suffix: Vec<u8> = iter
        .next()
        .unwrap()
        .bytes()
        .map(|b| b - b'0')
        .collect();

    let answer =
        count_at_most(finish, limit, &suffix) - count_at_most(start - 1, limit, &suffix);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
