use std::io::{self, Read, Write};

fn find_occurrences(s: &[u8], pattern: &[u8]) -> Vec<usize> {
    if pattern.len() > s.len() {
        return Vec::new();
    }

    (0..=s.len() - pattern.len())
        .filter(|&i| &s[i..i + pattern.len()] == pattern)
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap_or("").as_bytes();
    let a = tokens.next().unwrap_or("").as_bytes();
    let b = tokens.next().unwrap_or("").as_bytes();
    let k: usize = tokens.next().unwrap_or("0").parse().unwrap();

    let a_positions = find_occurrences(s, a);
    let b_positions = find_occurrences(s, b);

    let mut answer = Vec::new();
    let mut j = 0;

    for i in a_positions {
        let lower = i.saturating_sub(k);
        let upper = i.saturating_add(k);

        while j < b_positions.len() && b_positions[j] < lower {
            j += 1;
        }

        if j < b_positions.len() && b_positions[j] <= upper {
            answer.push(i);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (index, value) in answer.iter().enumerate() {
        if index > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{value}").unwrap();
    }
    writeln!(out).unwrap();
}
