fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums_line = match lines.next() {
        Some(line) => line,
        None => return,
    };
    let k_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let nums: Vec<i64> = nums_line
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let k: i64 = k_line.split_whitespace().next().unwrap().parse().unwrap();

    let mut min_prefix: HashMap<i64, i64> = HashMap::new();
    let mut prefix = 0_i64;
    let mut answer: Option<i64> = None;

    for x in nums {
        let next_prefix = prefix + x;

        for target in [x - k, x + k] {
            if let Some(&start_prefix) = min_prefix.get(&target) {
                let sum = next_prefix - start_prefix;
                answer = Some(answer.map_or(sum, |best| best.max(sum)));
            }
        }

        min_prefix
            .entry(x)
            .and_modify(|p| *p = (*p).min(prefix))
            .or_insert(prefix);

        prefix = next_prefix;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer.unwrap_or(0)).unwrap();
}
