use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let nums: Vec<i64> = match lines.next() {
        Some(line) => line
            .split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect(),
        None => return,
    };

    let m: usize = lines.next().unwrap().trim().parse().unwrap();
    let mut queries = Vec::with_capacity(m);

    for _ in 0..m {
        if let Some(line) = lines.next() {
            let mut values = line.split_whitespace();
            let index: usize = values.next().unwrap().parse().unwrap();
            let k: usize = values.next().unwrap().parse().unwrap();
            queries.push((index, k));
        }
    }

    let n = nums.len();
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_unstable_by_key(|&i| (nums[i], i));

    let mut marked = vec![false; n];
    let mut sum: i64 = nums.iter().sum();
    let mut pointer = 0usize;
    let mut answers = Vec::with_capacity(m);

    for (index, k) in queries {
        if !marked[index] {
            marked[index] = true;
            sum -= nums[index];
        }

        let mut remaining = k;
        while remaining > 0 {
            while pointer < n && marked[order[pointer]] {
                pointer += 1;
            }

            if pointer == n {
                break;
            }

            let idx = order[pointer];
            marked[idx] = true;
            sum -= nums[idx];
            pointer += 1;
            remaining -= 1;
        }

        answers.push(sum);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{answer}").unwrap();
    }
    writeln!(out).unwrap();
}
