use std::io::{self, Read, Write};

fn extract_numbers(s: &str) -> Vec<usize> {
    s.split(|c: char| !c.is_ascii_digit())
        .filter(|part| !part.is_empty())
        .filter_map(|part| part.parse::<usize>().ok())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input.lines().filter(|line| !line.trim().is_empty()).collect();
    if lines.len() < 3 {
        return;
    }

    let k = extract_numbers(lines[lines.len() - 2])[0];
    let max_changes = extract_numbers(lines[lines.len() - 1])[0];

    let mut nums = Vec::new();
    for line in &lines[..lines.len() - 2] {
        nums.extend(extract_numbers(line));
    }

    let mut positions = Vec::new();
    let mut longest_run = 0usize;
    let mut current_run = 0usize;

    for (i, &value) in nums.iter().enumerate() {
        if value == 1 {
            positions.push(i as i64);
            current_run += 1;
            longest_run = longest_run.max(current_run);
        } else {
            current_run = 0;
        }
    }

    let nearby = longest_run.min(3).min(k);

    let answer: i64;
    if nearby + max_changes >= k {
        let existing_cost = if nearby > 0 { nearby - 1 } else { 0 };
        answer = (existing_cost + 2 * (k - nearby)) as i64;
    } else {
        let required_existing = k - max_changes;

        let mut prefix = vec![0i64; positions.len() + 1];
        for i in 0..positions.len() {
            prefix[i + 1] = prefix[i] + positions[i];
        }

        let mut minimum_distance = i64::MAX;

        for left in 0..=positions.len() - required_existing {
            let right = left + required_existing;
            let middle = left + required_existing / 2;
            let median = positions[middle];

            let left_cost =
                median * (middle - left) as i64 - (prefix[middle] - prefix[left]);
            let right_cost =
                (prefix[right] - prefix[middle + 1])
                    - median * (right - middle - 1) as i64;

            minimum_distance = minimum_distance.min(left_cost + right_cost);
        }

        answer = minimum_distance + 2 * max_changes as i64;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
