use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Extremes {
    max1: i64,
    max2: i64,
    max_idx: usize,
    min1: i64,
    min2: i64,
    min_idx: usize,
}

impl Extremes {
    fn new() -> Self {
        Self {
            max1: i64::MIN,
            max2: i64::MIN,
            max_idx: 0,
            min1: i64::MAX,
            min2: i64::MAX,
            min_idx: 0,
        }
    }

    fn add(&mut self, value: i64, index: usize) {
        if value > self.max1 {
            self.max2 = self.max1;
            self.max1 = value;
            self.max_idx = index;
        } else if value > self.max2 {
            self.max2 = value;
        }

        if value < self.min1 {
            self.min2 = self.min1;
            self.min1 = value;
            self.min_idx = index;
        } else if value < self.min2 {
            self.min2 = value;
        }
    }

    fn range_without(&self, index: usize) -> i64 {
        let maximum = if index == self.max_idx {
            self.max2
        } else {
            self.max1
        };
        let minimum = if index == self.min_idx {
            self.min2
        } else {
            self.min1
        };
        maximum - minimum
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut transformed = Vec::with_capacity(n);
    let mut sum_extremes = Extremes::new();
    let mut diff_extremes = Extremes::new();

    for i in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();

        let sum = x + y;
        let diff = x - y;

        transformed.push((sum, diff));
        sum_extremes.add(sum, i);
        diff_extremes.add(diff, i);
    }

    let mut answer = i64::MAX;

    for i in 0..n {
        let sum_range = sum_extremes.range_without(i);
        let diff_range = diff_extremes.range_without(i);
        answer = answer.min(sum_range.max(diff_range));
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
