use std::io::{self, Read, Write};

fn update_extremes(
    value: i64,
    min1: &mut i64,
    min2: &mut i64,
    max1: &mut i64,
    max2: &mut i64,
) {
    if value <= *min1 {
        *min2 = *min1;
        *min1 = value;
    } else if value < *min2 {
        *min2 = value;
    }

    if value >= *max1 {
        *max2 = *max1;
        *max1 = value;
    } else if value > *max2 {
        *max2 = value;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut transformed = Vec::with_capacity(n);

    let mut sum_min1 = i64::MAX;
    let mut sum_min2 = i64::MAX;
    let mut sum_max1 = i64::MIN;
    let mut sum_max2 = i64::MIN;

    let mut diff_min1 = i64::MAX;
    let mut diff_min2 = i64::MAX;
    let mut diff_max1 = i64::MIN;
    let mut diff_max2 = i64::MIN;

    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();

        let sum = x + y;
        let diff = x - y;
        transformed.push((sum, diff));

        update_extremes(
            sum,
            &mut sum_min1,
            &mut sum_min2,
            &mut sum_max1,
            &mut sum_max2,
        );
        update_extremes(
            diff,
            &mut diff_min1,
            &mut diff_min2,
            &mut diff_max1,
            &mut diff_max2,
        );
    }

    let mut answer = i64::MAX;

    for (sum, diff) in transformed {
        let remaining_sum_min = if sum == sum_min1 { sum_min2 } else { sum_min1 };
        let remaining_sum_max = if sum == sum_max1 { sum_max2 } else { sum_max1 };
        let remaining_diff_min = if diff == diff_min1 { diff_min2 } else { diff_min1 };
        let remaining_diff_max = if diff == diff_max1 { diff_max2 } else { diff_max1 };

        let maximum_distance = (remaining_sum_max - remaining_sum_min)
            .max(remaining_diff_max - remaining_diff_min);

        answer = answer.min(maximum_distance);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
