    let nums = &values[..values.len() - 1];

    let mut dp = vec![0_i64; k + 1];
    dp[0] = 1;

    for &x in nums {
        let mut next = vec![0_i64; k + 1];
        for sum in 0..=k {
            next[sum] = (2 * dp[sum]) % MOD;
            if sum >= x {
                next[sum] = (next[sum] + dp[sum - x]) % MOD;
            }
        }
        dp = next;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[k]).unwrap();
