    let s = input.split_whitespace().next().unwrap_or("");

    let mut result = s.as_bytes().to_vec();
    let mut counts = [0usize; 26];
    let mut question_count = 0;

    for &ch in &result {
        if ch == b'?' {
            question_count += 1;
        } else {
            counts[(ch - b'a') as usize] += 1;
        }
    }

    let mut replacements = Vec::with_capacity(question_count);

    for _ in 0..question_count {
        let mut best = 0;
        for letter in 1..26 {
            if counts[letter] < counts[best] {
                best = letter;
            }
        }
        counts[best] += 1;
        replacements.push(b'a' + best as u8);
    }

    replacements.sort_unstable();

    let mut next = 0;
    for ch in &mut result {
        if *ch == b'?' {
            *ch = replacements[next];
            next += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    out.write_all(&result).unwrap();
    out.write_all(b"\n").unwrap();
