fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens: Vec<&str> = input.split_whitespace().collect();

    if tokens.is_empty() {
        return;
    }

    if let Ok(n) = tokens[0].parse::<usize>() {
        if tokens.len() >= n + 1 {
            tokens = tokens[1..=n].to_vec();
        }
    }

    let arr: Vec<&[u8]> = tokens.iter().map(|s| s.as_bytes()).collect();
    let mut answers = Vec::with_capacity(arr.len());

    for i in 0..arr.len() {
        let s = arr[i];
        let mut answer: Option<Vec<u8>> = None;

        for len in 1..=s.len() {
            let mut best: Option<&[u8]> = None;

            for start in 0..=s.len() - len {
                let candidate = &s[start..start + len];
                let mut unique = true;

                for (j, other) in arr.iter().enumerate() {
                    if i != j
                        && other.len() >= len
                        && other.windows(len).any(|window| window == candidate)
                    {
                        unique = false;
                        break;
                    }
                }

                if unique && best.is_none_or(|current| candidate < current) {
                    best = Some(candidate);
                }
            }

            if let Some(best) = best {
                answer = Some(best.to_vec());
                break;
            }
        }

        answers.push(
            answer
                .map(|bytes| String::from_utf8(bytes).unwrap())
                .unwrap_or_default(),
        );
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answers.join(" ")).unwrap();
}
