use std::collections::{BTreeMap, HashMap};
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let n = values.len() / 2;
    let nums = &values[..n];
    let updates = &values[n..];

    let mut id_counts: HashMap<i64, i64> = HashMap::new();
    let mut frequency_counts: BTreeMap<i64, usize> = BTreeMap::new();
    let mut answers = Vec::with_capacity(n);

    for i in 0..n {
        let id = nums[i];
        let old_count = *id_counts.get(&id).unwrap_or(&0);

        if old_count > 0 {
            if let Some(multiplicity) = frequency_counts.get_mut(&old_count) {
                *multiplicity -= 1;
                if *multiplicity == 0 {
                    frequency_counts.remove(&old_count);
                }
            }
        }

        let new_count = old_count + updates[i];

        if new_count == 0 {
            id_counts.remove(&id);
        } else {
            id_counts.insert(id, new_count);
            *frequency_counts.entry(new_count).or_insert(0) += 1;
        }

        answers.push(
            frequency_counts
                .iter()
                .next_back()
                .map_or(0, |(&frequency, _)| frequency),
        );
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", answer).unwrap();
    }
    writeln!(out).unwrap();
}
