use std::io::{self, Read, Write};

fn parse_array(line: &str) -> Vec<u32> {
    line.split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<u32>().unwrap())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let arrays: Vec<Vec<u32>> = input
        .lines()
        .map(parse_array)
        .filter(|v| !v.is_empty())
        .collect();

    if arrays.len() < 2 {
        return;
    }

    let nums = &arrays[0];
    let and_values = &arrays[1];
    let n = nums.len();
    let m = and_values.len();
    const INF: i64 = i64::MAX / 4;

    if m > n {
        println!("-1");
        return;
    }

    // prev[k] is the minimum cost to divide nums[0..k] into the
    // number of groups already processed.
    let mut prev = vec![INF; n + 1];
    prev[0] = 0;

    for &target in and_values {
        let mut curr = vec![INF; n + 1];

        // Each state stores:
        // (AND of nums[start..=right], minimum prev[start])
        let mut states: Vec<(u32, i64)> = Vec::new();

        for right in 0..n {
            let value = nums[right];
            let mut next_states: Vec<(u32, i64)> = Vec::new();

            for &(and_value, cost) in &states {
                let new_and = and_value & value;
                if let Some(state) = next_states.iter_mut().find(|s| s.0 == new_and) {
                    state.1 = state.1.min(cost);
                } else {
                    next_states.push((new_and, cost));
                }
            }

            if prev[right] < INF {
                if let Some(state) = next_states.iter_mut().find(|s| s.0 == value) {
                    state.1 = state.1.min(prev[right]);
                } else {
                    next_states.push((value, prev[right]));
                }
            }

            states = next_states;

            if let Some(&(_, base_cost)) = states.iter().find(|s| s.0 == target) {
                curr[right + 1] = base_cost + value as i64;
            }
        }

        prev = curr;
    }

    let answer = if prev[n] >= INF { -1 } else { prev[n] };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
