use std::io::{self, Read, Write};

struct Node {
    children: [u32; 26],
    best: u32,
}

impl Node {
    fn new() -> Self {
        Self {
            children: [0; 26],
            best: u32::MAX,
        }
    }
}

fn update_best(nodes: &mut [Node], node: usize, candidate: usize, lengths: &[usize]) {
    let current = nodes[node].best;
    if current == u32::MAX
        || lengths[candidate] < lengths[current as usize]
        || (lengths[candidate] == lengths[current as usize] && candidate < current as usize)
    {
        nodes[node].best = candidate as u32;
    }
}

fn parse_words(line: &str) -> Vec<&str> {
    line.split(|c: char| !c.is_ascii_lowercase())
        .filter(|s| !s.is_empty())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input.lines().filter(|line| !line.trim().is_empty()).collect();
    if lines.len() < 2 {
        return;
    }

    let container = parse_words(lines[0]);
    let queries = parse_words(lines[1]);
    let lengths: Vec<usize> = container.iter().map(|word| word.len()).collect();

    let total_length: usize = lengths.iter().sum();
    let mut trie = Vec::with_capacity(total_length + 1);
    trie.push(Node::new());

    for (index, word) in container.iter().enumerate() {
        let mut node = 0usize;
        update_best(&mut trie, node, index, &lengths);

        for &byte in word.as_bytes().iter().rev() {
            let letter = (byte - b'a') as usize;
            let next = trie[node].children[letter];

            if next == 0 {
                let new_index = trie.len();
                trie.push(Node::new());
                trie[node].children[letter] = new_index as u32;
                node = new_index;
            } else {
                node = next as usize;
            }

            update_best(&mut trie, node, index, &lengths);
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());

    for (query_index, query) in queries.iter().enumerate() {
        let mut node = 0usize;
        let mut answer = trie[0].best;

        for &byte in query.as_bytes().iter().rev() {
            let letter = (byte - b'a') as usize;
            let next = trie[node].children[letter];

            if next == 0 {
                break;
            }

            node = next as usize;
            answer = trie[node].best;
        }

        if query_index > 0 {
            write!(output, " ").unwrap();
        }
        write!(output, "{}", answer).unwrap();
    }

    writeln!(output).unwrap();
}
