fn main() {
    const MOD: i128 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<i128> = input
        .split_whitespace()
        .map(|s| s.parse::<i128>().unwrap())
        .collect();

    if values.len() < 3 {
        return;
    }

    let cost1 = values[values.len() - 2];
    let cost2 = values[values.len() - 1];
    let nums = &values[..values.len() - 2];

    let n = nums.len() as i128;
    let sum: i128 = nums.iter().sum();
    let min_value = *nums.iter().min().unwrap();
    let max_value = *nums.iter().max().unwrap();

    if nums.len() == 1 {
        println!("0");
        return;
    }

    if cost2 >= 2 * cost1 || nums.len() == 2 {
        let increments = n * max_value - sum;
        println!("{}", (increments * cost1) % MOD);
        return;
    }

    let mut answer = i128::MAX;

    for target in max_value..=2 * max_value {
        let total = n * target - sum;
        let largest_deficit = target - min_value;

        let pair_operations = (total / 2).min(total - largest_deficit);
        let single_operations = total - 2 * pair_operations;

        let cost = pair_operations * cost2 + single_operations * cost1;
        answer = answer.min(cost);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer % MOD).unwrap();
}
