use std::io::{self, Read, Write};

fn bit_statistics(n: u64) -> (u128, u128) {
    let numbers = n as u128 + 1;
    let mut count = 0u128;
    let mut exponent_sum = 0u128;

    for bit in 0..64u32 {
        let half = 1u128 << bit;
        let cycle = half << 1;
        let full_cycles = numbers / cycle;
        let remainder = numbers % cycle;

        let ones = full_cycles * half + remainder.saturating_sub(half).min(half);
        count += ones;
        exponent_sum += ones * bit as u128;
    }

    (count, exponent_sum)
}

// Sum of the exponents of the first `length` elements of big_nums.
fn prefix_exponent_sum(length: u64) -> u128 {
    if length == 0 {
        return 0;
    }

    // Find the greatest n such that the powerful arrays for 1..=n
    // contain at most `length` elements.
    let mut low = 0u64;
    let mut high = length + 1;

    while low + 1 < high {
        let mid = low + (high - low) / 2;
        let (count, _) = bit_statistics(mid);

        if count <= length as u128 {
            low = mid;
        } else {
            high = mid;
        }
    }

    let (used, mut sum) = bit_statistics(low);
    let mut remaining = length as u128 - used;
    let next_number = low + 1;

    // The powers in each powerful array are sorted by increasing exponent.
    for bit in 0..64u32 {
        if remaining == 0 {
            break;
        }
        if ((next_number >> bit) & 1) != 0 {
            sum += bit as u128;
            remaining -= 1;
        }
    }

    sum
}

fn mod_pow_two(mut exponent: u128, modulus: u64) -> u64 {
    if modulus == 1 {
        return 0;
    }

    let m = modulus as u128;
    let mut base = 2u128 % m;
    let mut result = 1u128 % m;

    while exponent > 0 {
        if exponent & 1 == 1 {
            result = result * base % m;
        }
        base = base * base % m;
        exponent >>= 1;
    }

    result as u64
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let query_count: usize = iter.next().unwrap().parse().unwrap();
    let mut answers = Vec::with_capacity(query_count);

    for _ in 0..query_count {
        let from: u64 = iter.next().unwrap().parse().unwrap();
        let to: u64 = iter.next().unwrap().parse().unwrap();
        let modulus: u64 = iter.next().unwrap().parse().unwrap();

        let right_sum = prefix_exponent_sum(to + 1);
        let left_sum = prefix_exponent_sum(from);
        let exponent = right_sum - left_sum;

        answers.push(mod_pow_two(exponent, modulus));
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
