        let mut low = 0usize;
        let mut high = i;
        while low < high {
            let mid = low + (high - low) / 2;
            if values[mid] < target {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        let cast = damage[i] + dp[low];
        dp[i + 1] = dp[i].max(cast);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[m]).unwrap();
