        return;
    }

    let k = values[values.len() - 1] as usize;
    let nums = &values[..values.len() - 1];
    let n = nums.len();

    let mut dp = vec![vec![0usize; k + 1]; n];
    let mut answer = 1usize;

    for i in 0..n {
        dp[i][0] = 1;

        for previous in 0..i {
            if nums[previous] == nums[i] {
                for changes in 0..=k {
                    dp[i][changes] = dp[i][changes].max(dp[previous][changes] + 1);
                }
            } else {
                for changes in 1..=k {
                    dp[i][changes] =
                        dp[i][changes].max(dp[previous][changes - 1] + 1);
                }
            }
        }

        for changes in 0..=k {
            answer = answer.max(dp[i][changes]);
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
