use std::io::{self, Read, Write};

fn parse_integers(s: &str) -> Vec<i64> {
    let bytes = s.as_bytes();
    let mut numbers = Vec::new();
    let mut i = 0;

    while i < bytes.len() {
        let mut sign = 1i64;

        if bytes[i] == b'-' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_digit() {
            sign = -1;
            i += 1;
        } else if !bytes[i].is_ascii_digit() {
            i += 1;
            continue;
        }

        let mut value = 0i64;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            value = value * 10 + (bytes[i] - b'0') as i64;
            i += 1;
        }
        numbers.push(sign * value);
    }

    numbers
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut nums = parse_integers(&input);

    // Also support the common format where the first line contains n.
    if let Some(newline) = input.find('\n') {
        let first_line_numbers = parse_integers(&input[..newline]);
        if first_line_numbers.len() == 1 {
            let n = first_line_numbers[0];
            if n >= 1 && n as usize == nums.len().saturating_sub(1) {
                nums.remove(0);
            }
        }
    }

    if nums.is_empty() {
        return;
    }

    // plus: best total where the current element has a positive sign.
    // minus: best total where the current element has a negative sign.
    let mut plus = nums[0];
    let mut minus = i64::MIN / 4;

    for &x in &nums[1..] {
        let new_plus = plus.max(minus) + x;
        let new_minus = plus - x;
        plus = new_plus;
        minus = new_minus;
    }

    let answer = plus.max(minus);
    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{}", answer).unwrap();
}
