fn height(mut red: i32, mut blue: i32, start_red: bool) -> i32 {
    let mut row = 1;
    loop {
        let use_red = if row % 2 == 1 {
            start_red
        } else {
            !start_red
        };

        let available = if use_red { &mut red } else { &mut blue };
        if *available < row {
            return row - 1;
        }

        *available -= row;
        row += 1;
    }
}

