use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] != x {
            self.parent[x] = self.find(self.parent[x]);
        }
        self.parent[x]
    }

    fn union(&mut self, a: usize, b: usize) {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return;
        }
        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
    }
}

fn sq(v: i128) -> i128 {
    v * v
}

fn touches_vertical_segment(
    cx: i128,
    cy: i128,
    radius: i128,
    edge_x: i128,
    height: i128,
) -> bool {
    let dx = cx - edge_x;
    let dy = if cy > height { cy - height } else { 0 };
    sq(dx) + sq(dy) <= sq(radius)
}

fn touches_horizontal_segment(
    cx: i128,
    cy: i128,
    radius: i128,
    edge_y: i128,
    width: i128,
) -> bool {
    let dx = if cx > width { cx - width } else { 0 };
    let dy = cy - edge_y;
    sq(dx) + sq(dy) <= sq(radius)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let width: i128 = it.next().unwrap().parse().unwrap();
    let height: i128 = it.next().unwrap().parse().unwrap();
    let n: usize = it.next().unwrap().parse().unwrap();

    let mut circles = Vec::with_capacity(n);
    for _ in 0..n {
        let x: i128 = it.next().unwrap().parse().unwrap();
        let y: i128 = it.next().unwrap().parse().unwrap();
        let r: i128 = it.next().unwrap().parse().unwrap();
        circles.push((x, y, r));
    }

    let top_left_boundary = n;
    let bottom_right_boundary = n + 1;
    let mut dsu = Dsu::new(n + 2);

    for (i, &(x, y, r)) in circles.iter().enumerate() {
        let touches_left = touches_vertical_segment(x, y, r, 0, height);
        let touches_right = touches_vertical_segment(x, y, r, width, height);
        let touches_bottom = touches_horizontal_segment(x, y, r, 0, width);
        let touches_top = touches_horizontal_segment(x, y, r, height, width);

        if touches_left || touches_top {
            dsu.union(i, top_left_boundary);
        }
        if touches_bottom || touches_right {
            dsu.union(i, bottom_right_boundary);
        }
    }

    for i in 0..n {
        let (x1, y1, r1) = circles[i];
        for j in (i + 1)..n {
            let (x2, y2, r2) = circles[j];
            let radius_sum = r1 + r2;

            if sq(x1 - x2) + sq(y1 - y2) > sq(radius_sum) {
                continue;
            }

            let connection_x = x1 * r2 + x2 * r1;
            let connection_y = y1 * r2 + y2 * r1;

            if connection_x < width * radius_sum
                && connection_y < height * radius_sum
            {
                dsu.union(i, j);
            }
        }
    }

    let reachable = dsu.find(top_left_boundary) != dsu.find(bottom_right_boundary);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if reachable { "true" } else { "false" }).unwrap();
}
