fn dist_to_vertical_segment_sq(
    x: i128,
    y: i128,
    segment_x: i128,
    max_y: i128,
) -> i128 {
    let dx = x - segment_x;
    let dy = if y < 0 {
        y
    } else if y > max_y {
        y - max_y
    } else {
        0
    };
    dx * dx + dy * dy
}

fn dist_to_horizontal_segment_sq(
    x: i128,
    y: i128,
    segment_y: i128,
    max_x: i128,
) -> i128 {
    let dy = y - segment_y;
    let dx = if x < 0 {
        x
    } else if x > max_x {
        x - max_x
    } else {
        0
    };
    dx * dx + dy * dy
}

