fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let start_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let mut starts: Vec<i64> = start_line
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    let d: i64 = lines
        .flat_map(|line| line.split_whitespace())
        .next()
        .unwrap()
        .parse()
        .unwrap();

    starts.sort_unstable();

    let feasible = |gap: i64| -> bool {
        let mut chosen = starts[0];
        for &left in starts.iter().skip(1) {
            chosen = left.max(chosen + gap);
            if chosen > left + d {
                return false;
            }
        }
        true
    };

    let n = starts.len() as i64;
    let mut low = 0_i64;
    let mut high = (starts[starts.len() - 1] + d - starts[0]) / (n - 1) + 1;

    while low + 1 < high {
        let mid = low + (high - low) / 2;
        if feasible(mid) {
            low = mid;
        } else {
            high = mid;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
}
