fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let m: usize = iter.next().unwrap().parse().unwrap();
    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut horizontal = Vec::with_capacity(m.saturating_sub(1));
    for _ in 0..m.saturating_sub(1) {
        horizontal.push(iter.next().unwrap().parse::<i64>().unwrap());
    }

    let mut vertical = Vec::with_capacity(n.saturating_sub(1));
    for _ in 0..n.saturating_sub(1) {
        vertical.push(iter.next().unwrap().parse::<i64>().unwrap());
    }

    horizontal.sort_unstable_by(|a, b| b.cmp(a));
    vertical.sort_unstable_by(|a, b| b.cmp(a));

    let (mut i, mut j) = (0, 0);
    let (mut horizontal_pieces, mut vertical_pieces) = (1_i64, 1_i64);
    let mut total = 0_i64;

    while i < horizontal.len() && j < vertical.len() {
        if horizontal[i] >= vertical[j] {
            total += horizontal[i] * vertical_pieces;
            horizontal_pieces += 1;
            i += 1;
        } else {
            total += vertical[j] * horizontal_pieces;
            vertical_pieces += 1;
            j += 1;
        }
    }

    while i < horizontal.len() {
        total += horizontal[i] * vertical_pieces;
        i += 1;
    }

    while j < vertical.len() {
        total += vertical[j] * horizontal_pieces;
        j += 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{total}").unwrap();
