fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<i64>().unwrap());

    let height = values.next().unwrap();
    let worker_times: Vec<i64> = values.collect();

    let min_worker_time = *worker_times.iter().min().unwrap();
    let mut low = 0_i64;
    let mut high = (min_worker_time as i128 * height as i128 * (height as i128 + 1) / 2) as i64;

    while low < high {
        let time = low + (high - low) / 2;
        let mut total_reduced = 0_i64;

        for &worker_time in &worker_times {
            let mut left = 0_i64;
            let mut right = height;

            while left < right {
                let mid = left + (right - left + 1) / 2;
                let required = worker_time as i128 * mid as i128 * (mid as i128 + 1) / 2;

                if required <= time as i128 {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }

            total_reduced += left;
            if total_reduced >= height {
                break;
            }
        }

        if total_reduced >= height {
            high = time;
        } else {
            low = time + 1;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{low}").unwrap();
