        diff[0] -= 1;
        diff[one_change_limit + 1] += 1;

        diff[difference] -= 1;
        diff[difference + 1] += 1;
    }

    let mut current = baseline;
    let mut answer = baseline;

    for x in 0..=k {
        current += diff[x];
        answer = answer.min(current);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
