fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let l: u64 = iter.next().unwrap().parse().unwrap();
    let r: u64 = iter.next().unwrap().parse().unwrap();

    let limit = (r as f64).sqrt() as usize;
    let mut is_prime = vec![true; limit + 1];
    if !is_prime.is_empty() {
        is_prime[0] = false;
    }
    if limit >= 1 {
        is_prime[1] = false;
    }

    let mut p = 2;
    while p * p <= limit {
        if is_prime[p] {
            for multiple in (p * p..=limit).step_by(p) {
                is_prime[multiple] = false;
            }
        }
        p += 1;
    }

    let special_count = (2..=limit)
        .filter(|&x| is_prime[x] && (x as u64) * (x as u64) >= l)
        .count() as u64;

    let answer = r - l + 1 - special_count;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
