```rust
use std::collections::BTreeSet;
use std::io::{self, Read, Write};
use std::ops::Bound::{Excluded, Unbounded};

struct Fenwick {
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(size: usize) -> Self {
        Self {
            tree: vec![0; size + 1],
        }
    }

    fn add(&mut self, mut index: usize, delta: i64) {
        while index < self.tree.len() {
            self.tree[index] += delta;
            index += index & index.wrapping_neg();
        }
    }

    fn sum(&self, mut index: usize) -> i64 {
        let mut result = 0;
        while index > 0 {
            result += self.tree[index];
            index &= index - 1;
        }
        result
    }
}

fn gap_length(a: usize, b: usize, n: usize) -> usize {
    (b + n - a - 1) % n
}

fn add_gap(
    length: usize,
    delta: i64,
    count_tree: &mut Fenwick,
    sum_tree: &mut Fenwick,
) {
    count_tree.add(length + 1, delta);
    sum_tree.add(length + 1, delta * length as i64);
}

fn set_bad_edge(
    edge: usize,
    should_be_bad: bool,
    n: usize,
    bad: &mut BTreeSet<usize>,
    count_tree: &mut Fenwick,
    sum_tree: &mut Fenwick,
) {
    let currently_bad = bad.contains(&edge);
    if currently_bad == should_be_bad {
        return;
    }

    if should_be_bad {
        if bad.is_empty() {
            bad.insert(edge);
            add_gap(n - 1, 1, count_tree, sum_tree);
            return;
        }

        let prev = bad
            .range(..edge)
            .next_back()
            .copied()
            .unwrap_or_else(|| *bad.iter().next_back().unwrap());
        let next = bad
            .range((Excluded(edge), Unbounded))
            .next()
            .copied()
            .unwrap_or_else(|| *bad.iter().next().unwrap());

        add_gap(gap_length(prev, next, n), -1, count_tree, sum_tree);
        add_gap(gap_length(prev, edge, n), 1, count_tree, sum_tree);
        add_gap(gap_length(edge, next, n), 1, count_tree, sum_tree);
        bad.insert(edge);
    } else {
        if bad.len() == 1 {
            add_gap(n - 1, -1, count_tree, sum_tree);
            bad.remove(&edge);
            return;
        }

        let prev = bad
            .range(..edge)
            .next_back()
            .copied()
            .unwrap_or_else(|| *bad.iter().next_back().unwrap());
        let next = bad
            .range((Excluded(edge), Unbounded))
            .next()
            .copied()
            .unwrap_or_else(|| *bad.iter().next().unwrap());

        add_gap(gap_length(prev, edge, n), -1, count_tree, sum_tree);
        add_gap(gap_length(edge, next, n), -1, count_tree, sum_tree);
        add_gap(gap_length(prev, next, n), 1, count_tree, sum_tree);
        bad.remove(&edge);
    }
}

fn parse_numbers(line: &str) -> Vec<usize> {
    let mut numbers = Vec::new();
    let mut current: Option<usize> = None;

    for byte in line.bytes() {
        if byte.is_ascii_digit() {
            current = Some(current.unwrap_or(0) * 10 + (byte - b'0') as usize);
        } else if let Some(value) = current.take() {
            numbers.push(value);
        }
    }
    if let Some(value) = current {
        numbers.push(value);
    }

    numbers
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let first_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let mut colors = parse_numbers(first_line);
    let n = colors.len();

    let remaining = lines.collect::<Vec<_>>().join("\n");
    let data = parse_numbers(&remaining);
    if data.is_empty() {
        return;
    }

    let query_count = data[0];
    let mut position = 1;

    let mut bad = BTreeSet::new();
    for i in 0..n {
        if colors[i] == colors[(i + 1) % n] {
            bad.insert(i);
        }
    }

    let mut count_tree = Fenwick::new(n + 1);
    let mut sum_tree = Fenwick::new(n + 1);

    if !bad.is_empty() {
        let edges: Vec<usize> = bad.iter().copied().collect();
        for i in 0..edges.len() {
            let next = edges[(i + 1) % edges.len()];
            add_gap(
                gap_length(edges[i], next, n),
                1,
                &mut count_tree,
                &mut sum_tree,
            );
        }
    }

    let mut answers = Vec::new();

    for _ in 0..query_count {
        let query_type = data[position];
        position += 1;

        if query_type == 1 {
            let size = data[position];
            position += 1;

            if bad.is_empty() {
                answers.push(n as i64);
            } else {
                let threshold = size - 1;
                let total_count = count_tree.sum(n + 1);
                let total_length = sum_tree.sum(n + 1);
                let smaller_count = count_tree.sum(threshold);
                let smaller_length = sum_tree.sum(threshold);

                let valid_count = total_count - smaller_count;
                let valid_length = total_length - smaller_length;
                let answer = valid_length - (size as i64 - 2) * valid_count;
                answers.push(answer);
            }
        } else {
            let index = data[position];
            let color = data[position + 1];
            position += 2;

            colors[index] = color;

            let left_edge = (index + n - 1) % n;
            let right_edge = index;

            let left_bad = colors[left_edge] == colors[(left_edge + 1) % n];
            let right_bad = colors[right_edge] == colors[(right_edge + 1) % n];

            set_bad_edge(
                left_edge,
                left_bad,
                n,
                &mut bad,
                &mut count_tree,
                &mut sum_tree,
            );
            set_bad_edge(
                right_edge,
                right_bad,
                n,
                &mut bad,
                &mut count_tree,
                &mut sum_tree,
            );
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());

    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(output, " ").unwrap();
        }
        write!(output, "{answer}").unwrap();
    }
    if !answers.is_empty() {
        writeln!(output).unwrap();
    }
}
