        return;
    }

    let power = values[0];
    let n = (values.len() - 1) / 2;
    let damage = &values[1..1 + n];
    let health = &values[1 + n..1 + 2 * n];

    let mut enemies: Vec<(i64, i64)> = (0..n)
        .map(|i| ((health[i] + power - 1) / power, damage[i]))
        .collect();

    enemies.sort_unstable_by(|&(time_a, damage_a), &(time_b, damage_b)| {
        let left = time_a * damage_b;
        let right = time_b * damage_a;
        match left.cmp(&right) {
            Ordering::Equal => damage_b.cmp(&damage_a),
            order => order,
        }
    });

    let mut elapsed = 0_i64;
    let mut total_damage = 0_i64;

    for (time, damage) in enemies {
        elapsed += time;
        total_damage += elapsed * damage;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
