use std::io::{self, Read, Write};

fn can_transform(value: u64, target: u64) -> bool {
    if value == target {
        return true;
    }

    let mut digits = value.to_string().into_bytes();

    for i in 0..digits.len() {
        for j in (i + 1)..digits.len() {
            digits.swap(i, j);

            let mut transformed = 0u64;
            for &digit in &digits {
                transformed = transformed * 10 + u64::from(digit - b'0');
            }

            digits.swap(i, j);

            if transformed == target {
                return true;
            }
        }
    }

    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<u64> = input
        .split_whitespace()
