        .collect();

    let mut answer = 0u64;

    for i in 0..nums.len() {
        for j in (i + 1)..nums.len() {
            if can_transform(nums[i], nums[j]) || can_transform(nums[j], nums[i]) {
                answer += 1;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
