    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let nums_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let nums: Vec<u32> = nums_line
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let q: usize = lines.next().unwrap().trim().parse().unwrap();
    let mut queries = Vec::with_capacity(q);

    for _ in 0..q {
        let mut parts = lines.next().unwrap().split_whitespace();
        let left: usize = parts.next().unwrap().parse().unwrap();
        let right: usize = parts.next().unwrap().parse().unwrap();
        queries.push((left, right));
    }

    let n = nums.len();
    let mut score = vec![0u32; n * n];
    let mut best = vec![0u32; n * n];

    for i in 0..n {
        score[i * n + i] = nums[i];
        best[i * n + i] = nums[i];
    }

    for len in 2..=n {
        for left in 0..=n - len {
            let right = left + len - 1;
            let idx = left * n + right;

            score[idx] = score[left * n + right - 1] ^ score[(left + 1) * n + right];
            best[idx] = score[idx]
                .max(best[left * n + right - 1])
                .max(best[(left + 1) * n + right]);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, &(left, right)) in queries.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", best[left * n + right]).unwrap();
    }
    writeln!(out).unwrap();
