use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace().filter_map(|s| s.parse::<usize>().ok());

    let n = it.next().unwrap();
    let k = it.next().unwrap();

    let half = (n + 1) / 2;

    let mut pow10 = vec![0usize; n];
    pow10[0] = 1 % k;
    for i in 1..n {
        pow10[i] = (pow10[i - 1] * 10) % k;
    }

    let mut weight = vec![0usize; half];
    for i in 0..half {
        let mirror = n - 1 - i;
        weight[i] = if i == mirror {
            pow10[i]
        } else {
            (pow10[i] + pow10[mirror]) % k
        };
    }

    // suffix_dp[i] is a bitmask of all residues obtainable using
    // positions i..half.
    let mut suffix_dp = vec![0u16; half + 1];
    suffix_dp[half] = 1; // Residue 0.

    for i in (0..half).rev() {
        let mut mask = 0u16;
        for suffix_residue in 0..k {
            if suffix_dp[i + 1] & (1u16 << suffix_residue) == 0 {
                continue;
            }
            for digit in 0..=9usize {
                let residue = (suffix_residue + digit * weight[i]) % k;
                mask |= 1u16 << residue;
            }
        }
        suffix_dp[i] = mask;
    }

    let mut answer = vec![b'0'; n];
    let mut prefix_residue = 0usize;

    for i in 0..half {
        let minimum_digit = if i == 0 { 1usize } else { 0usize };
        let mut selected = None;

        for digit in (minimum_digit..=9usize).rev() {
            let new_residue = (prefix_residue + digit * weight[i]) % k;
            let needed = (k - new_residue) % k;

            if suffix_dp[i + 1] & (1u16 << needed) != 0 {
                selected = Some((digit, new_residue));
                break;
            }
        }

        let (digit, new_residue) = selected.unwrap();
        prefix_residue = new_residue;

        answer[i] = b'0' + digit as u8;
        answer[n - 1 - i] = b'0' + digit as u8;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    out.write_all(&answer).unwrap();
    out.write_all(b"\n").unwrap();
}
