use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct State {
    score: i64,
    ids: [usize; 4],
}

#[derive(Clone, Copy)]
struct Interval {
    left: i64,
    right: i64,
    weight: i64,
    index: usize,
}

fn lex_less_fixed(a: &[usize; 4], b: &[usize; 4], len: usize) -> bool {
    for i in 0..len {
        if a[i] != b[i] {
            return a[i] < b[i];
        }
    }
    false
}

fn lex_less_variable(
    a: &[usize; 4],
    a_len: usize,
    b: &[usize; 4],
    b_len: usize,
) -> bool {
    let common = a_len.min(b_len);
    for i in 0..common {
        if a[i] != b[i] {
            return a[i] < b[i];
        }
    }
    a_len < b_len
}

fn insert_sorted(mut ids: [usize; 4], len: usize, value: usize) -> [usize; 4] {
    let mut pos = 0;
    while pos < len && ids[pos] < value {
        pos += 1;
    }
    for i in (pos..len).rev() {
        ids[i + 1] = ids[i];
    }
    ids[pos] = value;
    ids
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut intervals = Vec::with_capacity(n);

    for index in 0..n {
        let left: i64 = it.next().unwrap().parse().unwrap();
        let right: i64 = it.next().unwrap().parse().unwrap();
        let weight: i64 = it.next().unwrap().parse().unwrap();
        intervals.push(Interval {
            left,
            right,
            weight,
            index,
        });
    }

    intervals.sort_unstable_by(|a, b| {
        a.right
            .cmp(&b.right)
            .then_with(|| a.left.cmp(&b.left))
            .then_with(|| a.index.cmp(&b.index))
    });

    let invalid = State {
        score: -1,
        ids: [0; 4],
    };
    let mut dp = vec![invalid; (n + 1) * 5];

    for i in 0..=n {
        dp[i * 5] = State {
            score: 0,
            ids: [0; 4],
        };
    }

    for i in 1..=n {
        let current = intervals[i - 1];

        let mut low = 0usize;
        let mut high = i - 1;
        while low < high {
            let mid = low + (high - low) / 2;
            if intervals[mid].right < current.left {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        let predecessor_count = low;

        for count in 1..=4 {
            let mut best = dp[(i - 1) * 5 + count];
            let previous = dp[predecessor_count * 5 + count - 1];

            if previous.score >= 0 {
                let candidate = State {
                    score: previous.score + current.weight,
                    ids: insert_sorted(previous.ids, count - 1, current.index),
                };

                if best.score < candidate.score
                    || (best.score == candidate.score
                        && lex_less_fixed(&candidate.ids, &best.ids, count))
                {
                    best = candidate;
                }
            }

            dp[i * 5 + count] = best;
        }
    }

    let mut answer = dp[n * 5];
    let mut answer_len = 0usize;

    for count in 1..=4 {
        let candidate = dp[n * 5 + count];
        if candidate.score < 0 {
            continue;
        }

        if candidate.score > answer.score
            || (candidate.score == answer.score
                && lex_less_variable(&candidate.ids, count, &answer.ids, answer_len))
        {
            answer = candidate;
            answer_len = count;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 0..answer_len {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", answer.ids[i]).unwrap();
    }
    writeln!(out).unwrap();
}
