fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut nums = input
        .split_whitespace()
        .map(|s| s.parse::<u32>().unwrap());

    let mut a = nums.next().unwrap();
    let mut b = nums.next().unwrap();
    let mut c = nums.next().unwrap();

    let mut key = 0;
    let mut place = 1;

    for _ in 0..4 {
        let digit = (a % 10).min(b % 10).min(c % 10);
        key += digit * place;
        place *= 10;
        a /= 10;
        b /= 10;
