use std::io::{self, Read, Write};

fn extract_numbers(s: &str) -> Vec<usize> {
    let mut numbers = Vec::new();
    let mut current = 0usize;
    let mut reading = false;

    for b in s.bytes() {
        if b.is_ascii_digit() {
            current = current * 10 + (b - b'0') as usize;
            reading = true;
        } else if reading {
            numbers.push(current);
            current = 0;
            reading = false;
        }
    }

    if reading {
        numbers.push(current);
    }

    numbers
}

fn update(dp: &mut [[bool; 128]], value: usize, k: usize) {
    for count in (1..=k).rev() {
        let previous = dp[count - 1];
        for mask in 0..128 {
            if previous[mask] {
                dp[count][mask | value] = true;
            }
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let groups: Vec<Vec<usize>> = input
        .lines()
        .map(extract_numbers)
        .filter(|v| !v.is_empty())
        .collect();

    if groups.is_empty() {
        return;
    }

    let (nums, k) = if groups.len() == 1 {
        let mut values = groups[0].clone();
        let k = values.pop().unwrap();
        (values, k)
    } else if groups.len() >= 3
        && groups[0].len() == 1
        && groups[0][0] == groups[1].len()
    {
        (groups[1].clone(), *groups.last().unwrap().last().unwrap())
    } else {
        (
            groups[0].clone(),
            *groups.last().unwrap().last().unwrap(),
        )
    };

    let n = nums.len();

    let mut prefix = vec![[false; 128]; n + 1];
    let mut dp = vec![[false; 128]; k + 1];
    dp[0][0] = true;

    for i in 0..n {
        update(&mut dp, nums[i], k);
        prefix[i + 1] = dp[k];
    }

    let mut suffix = vec![[false; 128]; n + 1];
    let mut dp = vec![[false; 128]; k + 1];
    dp[0][0] = true;

    for i in (0..n).rev() {
        update(&mut dp, nums[i], k);
        suffix[i] = dp[k];
    }

    let mut answer = 0usize;

    for split in k..=n - k {
        for left_or in 0..128 {
            if !prefix[split][left_or] {
                continue;
            }
            for right_or in 0..128 {
                if suffix[split][right_or] {
                    answer = answer.max(left_or ^ right_or);
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
