use std::io::{self, Read, Write};

fn z_function(s: &[u8]) -> Vec<usize> {
    let n = s.len();
    let mut z = vec![0; n];
    let (mut left, mut right) = (0usize, 0usize);

    for i in 1..n {
        if i < right {
            z[i] = (right - i).min(z[i - left]);
        }
        while i + z[i] < n && s[z[i]] == s[i + z[i]] {
            z[i] += 1;
        }
        if i + z[i] > right {
            left = i;
            right = i + z[i];
        }
    }
    z
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap_or("").as_bytes().to_vec();
    let pattern = tokens.next().unwrap_or("").as_bytes().to_vec();

    let n = s.len();
    let m = pattern.len();

    let answer = if m == 0 {
        0
    } else if m > n {
        -1
    } else {
        let mut forward = Vec::with_capacity(m + 1 + n);
        forward.extend_from_slice(&pattern);
        forward.push(b'#');
        forward.extend_from_slice(&s);
        let forward_z = z_function(&forward);

        let reversed_pattern: Vec<u8> = pattern.iter().rev().copied().collect();
        let reversed_s: Vec<u8> = s.iter().rev().copied().collect();

        let mut backward = Vec::with_capacity(m + 1 + n);
        backward.extend_from_slice(&reversed_pattern);
        backward.push(b'#');
        backward.extend_from_slice(&reversed_s);
        let backward_z = z_function(&backward);

        let mut result = -1;

        for start in 0..=n - m {
            let prefix_match = forward_z[m + 1 + start].min(m);
            if prefix_match == m {
                result = start as i32;
                break;
            }

            let reversed_start = n - (start + m);
            let suffix_match = backward_z[m + 1 + reversed_start].min(m);

            if prefix_match + suffix_match >= m - 1 {
                result = start as i32;
                break;
            }
        }

        result
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
