use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn creature(c: u8) -> usize {
    match c {
        b'F' => 0,
        b'W' => 1,
        b'E' => 2,
        _ => unreachable!(),
    }
}

fn score(bob: usize, alice: usize) -> i32 {
    match (bob + 3 - alice) % 3 {
        1 => 1,
        2 => -1,
        _ => 0,
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.split_whitespace().next().unwrap().as_bytes();
    let n = s.len();

    let width = 2 * n + 1;
    let offset = n as i32;
    let mut dp = vec![0_i64; 3 * width];
    let mut next = vec![0_i64; 3 * width];

    let first_alice = creature(s[0]);
    for bob in 0..3 {
        let diff = score(bob, first_alice);
        let index = (offset + diff) as usize;
        dp[bob * width + index] = 1;
    }

    for round in 1..n {
        next.fill(0);
        let alice = creature(s[round]);
        let processed = round as i32;

        for old_diff in -processed..=processed {
            let old_index = (offset + old_diff) as usize;

            for bob in 0..3 {
                let mut ways = 0_i64;
                for previous in 0..3 {
                    if previous != bob {
                        ways += dp[previous * width + old_index];
                        if ways >= MOD {
                            ways -= MOD;
                        }
                    }
                }

                let new_diff = old_diff + score(bob, alice);
                let new_index = (offset + new_diff) as usize;
                next[bob * width + new_index] = ways;
            }
        }

        std::mem::swap(&mut dp, &mut next);
    }

    let mut answer = 0_i64;
    for diff in 1..=n {
        let index = n + diff;
        for last in 0..3 {
            answer += dp[last * width + index];
            if answer >= MOD {
                answer -= MOD;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
