        let mut l = 1u64;
        let mut count = 0usize;

        for (i, &x) in nums.iter().enumerate() {
            if i == skip {
                continue;
            }
            g = gcd(g, x);
            l = l / gcd(l, x) * x;
            count += 1;
        }

        if count > 0 {
            answer = answer.max(g * l);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
