    let n = s.len();
    let parent: Vec<isize> = tokens
        .into_iter()
        .map(|x| x.parse::<isize>().unwrap())
        .collect();

    let mut children = vec![Vec::<usize>::new(); n];
    for i in 1..n {
        children[parent[i] as usize].push(i);
    }

    let mut start = vec![0usize; n];
    let mut end = vec![0usize; n];
    let mut postorder = Vec::with_capacity(n);
    let mut stack = Vec::with_capacity(2 * n);
    stack.push((0usize, false));

    while let Some((node, exiting)) = stack.pop() {
        if exiting {
            postorder.push(s[node]);
            end[node] = postorder.len();
        } else {
            start[node] = postorder.len();
            stack.push((node, true));
            for &child in children[node].iter().rev() {
                stack.push((child, false));
            }
        }
    }

    let mut odd = vec![0usize; n];
    let (mut left, mut right) = (0isize, -1isize);

    for i in 0..n {
        let i = i as isize;
        let mut radius = if i > right {
            1
        } else {
            odd[(left + right - i) as usize].min((right - i + 1) as usize)
        };

        while i - radius as isize >= 0
            && i + radius as isize < n as isize
            && postorder[(i - radius as isize) as usize]
                == postorder[(i + radius as isize) as usize]
        {
            radius += 1;
        }

        odd[i as usize] = radius;
        if i + radius as isize - 1 > right {
            left = i - radius as isize + 1;
            right = i + radius as isize - 1;
        }
    }

    let mut even = vec![0usize; n];
    left = 0;
    right = -1;

    for i in 0..n {
        let i = i as isize;
        let mut radius = if i > right {
            0
        } else {
            even[(left + right - i + 1) as usize].min((right - i + 1) as usize)
        };

        while i - radius as isize - 1 >= 0
            && i + radius as isize < n as isize
            && postorder[(i - radius as isize - 1) as usize]
                == postorder[(i + radius as isize) as usize]
        {
            radius += 1;
        }

        even[i as usize] = radius;
        if i + radius as isize - 1 > right {
            left = i - radius as isize;
            right = i + radius as isize - 1;
        }
    }

    let mut output = io::BufWriter::new(io::stdout().lock());

    for node in 0..n {
        if node > 0 {
            write!(output, " ").unwrap();
        }

        let l = start[node];
        let r = end[node];
        let len = r - l;

        let is_palindrome = if len % 2 == 1 {
            let center = (l + r - 1) / 2;
            odd[center] >= len / 2 + 1
        } else {
            let center = (l + r) / 2;
            even[center] >= len / 2
        };

        write!(
            output,
            "{}",
            if is_palindrome { "true" } else { "false" }
        )
        .unwrap();
    }

    writeln!(output).unwrap();
}
