use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens: Vec<&str> = input.split_whitespace().collect();

    if tokens.is_empty() {
        return;
    }

    let s = tokens.pop().unwrap().as_bytes().to_vec();
    let n = s.len();

    let parent: Vec<isize> = tokens
        .into_iter()
        .map(|token| token.parse::<isize>().unwrap())
        .collect();

    let mut children = vec![Vec::<usize>::new(); n];
    for node in 1..n {
        children[parent[node] as usize].push(node);
    }

    // Build the postorder DFS string and record each node's position.
    let mut postorder = Vec::with_capacity(n);
    let mut position = vec![0usize; n];
    let mut stack = Vec::with_capacity(2 * n);
    stack.push((0usize, false));

    while let Some((node, exiting)) = stack.pop() {
        if exiting {
            position[node] = postorder.len();
            postorder.push(node);
        } else {
            stack.push((node, true));
            for &child in children[node].iter().rev() {
                stack.push((child, false));
            }
        }
    }

    // Calculate subtree sizes in postorder.
    let mut subtree_size = vec![1usize; n];
    for &node in &postorder {
        let mut size = 1usize;
        for &child in &children[node] {
            size += subtree_size[child];
        }
        subtree_size[node] = size;
    }

    let text: Vec<u8> = postorder.iter().map(|&node| s[node]).collect();

    // Manacher: d1[i] is the radius of the longest odd palindrome at i.
    let mut d1 = vec![0usize; n];
    let mut left: isize = 0;
    let mut right: isize = -1;

    for i in 0..n {
        let ii = i as isize;
        let mut radius = if ii > right {
            1usize
        } else {
            let mirror = (left + right - ii) as usize;
            d1[mirror].min((right - ii + 1) as usize)
        };

        while i >= radius
            && i + radius < n
            && text[i - radius] == text[i + radius]
        {
            radius += 1;
        }

        d1[i] = radius;
        let new_right = ii + radius as isize - 1;
        if new_right > right {
            left = ii - radius as isize + 1;
            right = new_right;
        }
    }

    // Manacher: d2[i] is the radius of the longest even palindrome
    // centered between i - 1 and i.
    let mut d2 = vec![0usize; n];
    left = 0;
    right = -1;

    for i in 0..n {
        let ii = i as isize;
        let mut radius = if ii > right {
            0usize
        } else {
            let mirror = (left + right - ii + 1) as usize;
            d2[mirror].min((right - ii + 1) as usize)
        };

        while i > radius
            && i + radius < n
            && text[i - radius - 1] == text[i + radius]
        {
            radius += 1;
        }

        d2[i] = radius;
        let new_right = ii + radius as isize - 1;
        if new_right > right {
            left = ii - radius as isize;
            right = new_right;
        }
    }

    let mut answer = vec![false; n];

    for node in 0..n {
        let end = position[node];
        let len = subtree_size[node];
        let start = end + 1 - len;

        answer[node] = if len % 2 == 1 {
            let center = (start + end) / 2;
            d1[center] >= len / 2 + 1
        } else {
            let center = (start + end + 1) / 2;
            d2[center] >= len / 2
        };
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", value).unwrap();
    }
    writeln!(out).unwrap();
}
