fn main() {
    const MOD: i64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let x: usize = iter.next().unwrap().parse().unwrap();
    let y: i64 = iter.next().unwrap().parse().unwrap();

    let limit = n.min(x);
    let mut stirling = vec![0_i64; limit + 1];
    stirling[0] = 1;

    for i in 1..=n {
        let upper = i.min(limit);
        for k in (1..=upper).rev() {
            stirling[k] = (stirling[k - 1] + stirling[k] * k as i64) % MOD;
        }
        stirling[0] = 0;
    }

    let mut answer = 0_i64;
    let mut stage_permutations = 1_i64;
    let mut score_choices = 1_i64;

    for k in 1..=limit {
        stage_permutations =
            stage_permutations * (x - k + 1) as i64 % MOD;
        score_choices = score_choices * y % MOD;

        let ways = stirling[k] * stage_permutations % MOD * score_choices % MOD;
        answer = (answer + ways) % MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
