    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.split_whitespace().next().unwrap_or("");

    let mut freq = [0i32; 26];
    for b in s.bytes() {
        if b.is_ascii_lowercase() {
            freq[(b - b'a') as usize] += 1;
        }
    }

    let max_freq = *freq.iter().max().unwrap();
    let mut answer = s.len() as i32;

    for target in 1..=max_freq {
        let mut dp = [0i32; 2];

        for state in 0..2 {
            let wanted = if state == 0 { 0 } else { target };
            dp[state] = (freq[0] - wanted).abs();
        }

        for i in 1..26 {
            let mut next = [i32::MAX; 2];

            for current_state in 0..2 {
                let current_wanted = if current_state == 0 { 0 } else { target };
                let current_cost = (freq[i] - current_wanted).abs();

                for previous_state in 0..2 {
                    let previous_wanted =
                        if previous_state == 0 { 0 } else { target };

                    let surplus = (freq[i - 1] - previous_wanted).max(0);
                    let deficit = (current_wanted - freq[i]).max(0);
                    let saved = surplus.min(deficit);

                    next[current_state] = next[current_state]
                        .min(dp[previous_state] + current_cost - saved);
                }
            }

            dp = next;
        }

        answer = answer.min(dp[0].min(dp[1]));
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
