    let max_value = nums.iter().copied().max().unwrap_or(0);
    let mut counts = vec![0i64; max_value + 2];
    let mut sums = vec![0i64; max_value + 2];
    let mut answer = 0i64;

    for x in nums {
        let left = if x > 0 { x - 1 } else { max_value + 1 };
        let right = x + 1;
        let x_mod = x as i64 % MOD;

        let left_count = if x > 0 { counts[left] } else { 0 };
        let left_sum = if x > 0 { sums[left] } else { 0 };
        let right_count = counts[right];
        let right_sum = sums[right];

        let new_count = (1 + left_count + right_count) % MOD;
        let new_sum = (x_mod
            + left_sum
            + x_mod * left_count
            + right_sum
            + x_mod * right_count)
            % MOD;

        counts[x] = (counts[x] + new_count) % MOD;
        sums[x] = (sums[x] + new_sum) % MOD;
        answer = (answer + new_sum) % MOD;
