            }

            if best != NEG {
                let gain = if row == col { 0 } else { fruits[row][col] };
                cur[row] = best + gain;
            }
        }

        prev = cur;
    }

    let lower = prev[n - 1];
    let answer = diagonal + upper + lower;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
