        let broken = mask.count_ones() as u64;
        let factor = 1 + broken * k;

        for i in 0..n {
            if mask & (1 << i) == 0 {
                let time = (strength[i] + factor - 1) / factor;
                let next_mask = mask | (1 << i);
                dp[next_mask] = dp[next_mask].min(dp[mask] + time);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[size - 1]).unwrap();
