use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let edge_count: usize = it.next().unwrap().parse().unwrap();
    let n = edge_count + 1;
    let mut graph = vec![Vec::<(usize, i64)>::new(); n];

    for _ in 0..edge_count {
        let u: usize = it.next().unwrap().parse().unwrap();
        let v: usize = it.next().unwrap().parse().unwrap();
        let w: i64 = it.next().unwrap().parse().unwrap();
        graph[u].push((v, w));
        graph[v].push((u, w));
    }

    let k: usize = it.next().unwrap().parse().unwrap();

    let mut parent = vec![usize::MAX; n];
    let mut order = Vec::with_capacity(n);
    let mut stack = vec![0usize];
    parent[0] = 0;

    while let Some(u) = stack.pop() {
        order.push(u);
        for &(v, _) in &graph[u] {
            if parent[v] == usize::MAX {
                parent[v] = u;
                stack.push(v);
            }
        }
    }

    // dp_free[u]: best sum when the edge from u to its parent is not selected.
    // dp_used[u]: best sum when the edge from u to its parent is selected.
    let mut dp_free = vec![0i64; n];
    let mut dp_used = vec![0i64; n];

    for &u in order.iter().rev() {
        let mut base = 0i64;
        let mut gains = Vec::new();

        for &(v, w) in &graph[u] {
            if parent[v] == u {
                base += dp_free[v];
                gains.push(w + dp_used[v] - dp_free[v]);
            }
        }

        gains.sort_unstable_by(|a, b| b.cmp(a));

        dp_free[u] = base
            + gains
                .iter()
                .take(k)
                .filter(|&&gain| gain > 0)
                .sum::<i64>();

        dp_used[u] = base
            + gains
                .iter()
                .take(k - 1)
                .filter(|&&gain| gain > 0)
                .sum::<i64>();
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp_free[0]).unwrap();
}
