    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<usize>().unwrap());

    let n = values.next().unwrap();
    let m = values.next().unwrap();
    let k = values.next().unwrap();

    let transitions = n - 1;

    let mut factorial = vec![1_i64; transitions + 1];
    for i in 1..=transitions {
        factorial[i] = factorial[i - 1] * i as i64 % MOD;
    }

    let combination = factorial[transitions]
        * mod_pow(factorial[k], (MOD - 2) as usize)
        % MOD
        * mod_pow(factorial[transitions - k], (MOD - 2) as usize)
        % MOD;

    let differing = transitions - k;
    let answer = (m as i64 % MOD)
        * combination
        % MOD
        * mod_pow(m as i64 - 1, differing)
        % MOD;

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{}", answer).unwrap();
}
