use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<i32> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap())
        .collect();

    let n = nums.len();
    if n < 3 {
        println!("0");
        return;
    }

    // z[i] is the length of the longest common prefix of
    // nums[0..] and nums[i..].
    let mut z = vec![0usize; n];
    z[0] = n;
    let (mut left, mut right) = (0usize, 0usize);

    for i in 1..n {
        if i < right {
            z[i] = (right - i).min(z[i - left]);
        }
        while i + z[i] < n && nums[z[i]] == nums[i + z[i]] {
            z[i] += 1;
        }
        if i + z[i] > right {
            left = i;
            right = i + z[i];
        }
    }

    let mut answer = 0i64;

    // next[j] stores LCP(i + 1, j) for the previously processed row.
    let mut next = vec![0usize; n + 1];
    let mut current = vec![0usize; n + 1];

    for i in (1..=n - 2).rev() {
        current.fill(0);

        for j in (i + 1..n).rev() {
            if nums[i] == nums[j] {
                current[j] = 1 + next[j + 1];
            }

            let len1 = i;
            let len2 = j - i;
            let len3 = n - j;

            let first_is_prefix = len1 <= len2 && z[i] >= len1;
            let second_is_prefix = len2 <= len3 && current[j] >= len2;

            if first_is_prefix || second_is_prefix {
                answer += 1;
            }
        }

        std::mem::swap(&mut current, &mut next);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
