use std::collections::HashMap;
use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Node {
    sum: i64,
    pref: i64,
    suff: i64,
    best: i64,
    empty: bool,
}

impl Node {
    fn empty() -> Self {
        Self {
            sum: 0,
            pref: 0,
            suff: 0,
            best: 0,
            empty: true,
        }
    }

    fn leaf(value: i64) -> Self {
        Self {
            sum: value,
            pref: value,
            suff: value,
            best: value,
            empty: false,
        }
    }
}

fn merge(left: Node, right: Node) -> Node {
    if left.empty {
        return right;
    }
    if right.empty {
        return left;
    }

    Node {
        sum: left.sum + right.sum,
        pref: left.pref.max(left.sum + right.pref),
        suff: right.suff.max(right.sum + left.suff),
        best: left.best.max(right.best).max(left.suff + right.pref),
        empty: false,
    }
}

struct SegmentTree {
    size: usize,
    tree: Vec<Node>,
}

impl SegmentTree {
    fn new(values: &[i64]) -> Self {
        let mut size = 1;
        while size < values.len() {
            size *= 2;
        }

        let mut tree = vec![Node::empty(); size * 2];
        for (i, &value) in values.iter().enumerate() {
            tree[size + i] = Node::leaf(value);
        }

        for i in (1..size).rev() {
            tree[i] = merge(tree[i * 2], tree[i * 2 + 1]);
        }

        Self { size, tree }
    }

    fn update(&mut self, index: usize, node: Node) {
        let mut pos = self.size + index;
        self.tree[pos] = node;

        while pos > 1 {
            pos /= 2;
            self.tree[pos] = merge(self.tree[pos * 2], self.tree[pos * 2 + 1]);
        }
    }

    fn best(&self) -> i64 {
        self.tree[1].best
    }
}

fn parse_numbers(input: &str) -> Vec<i64> {
    let bytes = input.as_bytes();
    let mut numbers = Vec::new();
    let mut i = 0;

    while i < bytes.len() {
        let mut sign = 1i64;

        if bytes[i] == b'-' {
            if i + 1 >= bytes.len() || !bytes[i + 1].is_ascii_digit() {
                i += 1;
                continue;
            }
            sign = -1;
            i += 1;
        } else if !bytes[i].is_ascii_digit() {
            i += 1;
            continue;
        }

        let mut value = 0i64;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            value = value * 10 + (bytes[i] - b'0') as i64;
            i += 1;
        }
        numbers.push(sign * value);
    }

    numbers
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let nums = parse_numbers(&input);

    if nums.is_empty() {
        return;
    }

    let mut positions: HashMap<i64, Vec<usize>> = HashMap::new();
    for (index, &value) in nums.iter().enumerate() {
        positions.entry(value).or_default().push(index);
    }

    let mut tree = SegmentTree::new(&nums);
    let mut answer = tree.best();

    for (&value, indices) in &positions {
        if value >= 0 || indices.len() == nums.len() {
            continue;
        }

        for &index in indices {
            tree.update(index, Node::empty());
        }

        answer = answer.max(tree.best());

        for &index in indices {
            tree.update(index, Node::leaf(value));
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
