use std::io::{self, Read, Write};

fn can_achieve(s: &[u8], max_run: usize, num_ops: usize) -> bool {
    if max_run == 1 {
        let mut changes_starting_zero = 0;
        let mut changes_starting_one = 0;

        for (i, &ch) in s.iter().enumerate() {
            let expected_zero = if i % 2 == 0 { b'0' } else { b'1' };
            let expected_one = if i % 2 == 0 { b'1' } else { b'0' };

            if ch != expected_zero {
                changes_starting_zero += 1;
            }
            if ch != expected_one {
                changes_starting_one += 1;
            }
        }

        return changes_starting_zero.min(changes_starting_one) <= num_ops;
    }

    let mut operations = 0;
    let mut run_length = 1;

    for i in 1..s.len() {
        if s[i] == s[i - 1] {
            run_length += 1;
        } else {
            operations += run_length / (max_run + 1);
            run_length = 1;
        }
    }
    operations += run_length / (max_run + 1);

    operations <= num_ops
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap().as_bytes().to_vec();
    let num_ops: usize = tokens.next().unwrap().parse().unwrap();

    let mut low = 1;
    let mut high = s.len();

    while low < high {
        let mid = low + (high - low) / 2;
        if can_achieve(&s, mid, num_ops) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", low).unwrap();
}
