    const BASE: usize = 1001;
    let mut ratio_count = vec![0_i64; BASE * BASE];
    let mut answer = 0_i64;

    for r in 4..=n - 3 {
        let q = r - 2;

        for p in 0..=q - 2 {
            let g = gcd(nums[p], nums[q]);
            let numerator = nums[p] / g;
            let denominator = nums[q] / g;
            ratio_count[numerator * BASE + denominator] += 1;
        }

        for s in r + 2..n {
            let g = gcd(nums[s], nums[r]);
            let numerator = nums[s] / g;
            let denominator = nums[r] / g;
            answer += ratio_count[numerator * BASE + denominator];
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
