use std::io::{self, Read, Write};

fn comb(count: i64, take: usize) -> i128 {
    match take {
        0 => 1,
        1 => count as i128,
        2 => {
            if count < 2 {
                0
            } else {
                (count as i128) * ((count - 1) as i128) / 2
            }
        }
        _ => 0,
    }
}

fn main() {
    const MOD: i128 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let bytes = input.as_bytes();
    let mut nums = Vec::<i64>::new();
    let mut i = 0;

    while i < bytes.len() {
        let mut sign = 1i64;
        if bytes[i] == b'-' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_digit() {
            sign = -1;
            i += 1;
        } else if !bytes[i].is_ascii_digit() {
            i += 1;
            continue;
        }

        let mut value = 0i64;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            value = value * 10 + (bytes[i] - b'0') as i64;
            i += 1;
        }
        nums.push(sign * value);
    }

    let n = nums.len();
    if n < 5 {
        println!("0");
        return;
    }

    let mut values = nums.clone();
    values.sort_unstable();
    values.dedup();

    let ids: Vec<usize> = nums
        .iter()
        .map(|x| values.binary_search(x).unwrap())
        .collect();

    let distinct = values.len();
    let mut left = vec![0i64; distinct];
    let mut right = vec![0i64; distinct];

    for &id in &ids {
        right[id] += 1;
    }

    let mut answer = 0i128;

    for middle in 0..n {
        let x = ids[middle];
        right[x] -= 1;

        if middle >= 2 && n - middle - 1 >= 2 {
            let left_size = middle as i64;
            let right_size = (n - middle - 1) as i64;

            let left_x = left[x];
            let right_x = right[x];
            let left_non_x = left_size - left_x;
            let right_non_x = right_size - right_x;

            // Cases where the middle value appears at least three times.
            let mut at_least_three = 0i128;
            for take_left_x in 0..=2usize {
                for take_right_x in 0..=2usize {
                    if take_left_x + take_right_x < 2 {
                        continue;
                    }

                    at_least_three += comb(left_x, take_left_x)
                        * comb(left_non_x, 2 - take_left_x)
                        * comb(right_x, take_right_x)
                        * comb(right_non_x, 2 - take_right_x);
                }
            }

            // Distinct-value pairs among non-x values on each side.
            let mut left_distinct_pairs = comb(left_non_x, 2);
            let mut right_distinct_pairs = comb(right_non_x, 2);

            let mut left_to_right_conflicts = 0i128;
            let mut right_to_left_conflicts = 0i128;

            for value in 0..distinct {
                if value == x {
                    continue;
                }

                let lv = left[value];
                let rv = right[value];

                left_distinct_pairs -= comb(lv, 2);
                right_distinct_pairs -= comb(rv, 2);

                left_to_right_conflicts +=
                    (lv as i128) * (rv as i128) * ((right_non_x - rv) as i128);
                right_to_left_conflicts +=
                    (rv as i128) * (lv as i128) * ((left_non_x - lv) as i128);
            }

            // The middle value appears exactly twice. The other three selected
            // values must all be pairwise distinct.
            let extra_x_on_left = (left_x as i128)
                * ((left_non_x as i128) * right_distinct_pairs
                    - left_to_right_conflicts);

            let extra_x_on_right = (right_x as i128)
                * ((right_non_x as i128) * left_distinct_pairs
                    - right_to_left_conflicts);

            answer = (answer + at_least_three + extra_x_on_left + extra_x_on_right) % MOD;
        }

        left[x] += 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
