use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.trim().as_bytes();

    let mut inv = [0i64; 27];
    for i in 1..=26 {
        inv[i] = mod_pow(i as i64, MOD - 2);
    }

    // a[t]: assignments whose processed prefix has no repeated uppercase letter,
    // with exactly t uppercase letters originating from '?'.
    let mut a = [0i64; 27];
    a[0] = 1;

    // b: a repeated uppercase exists, but no lowercase has appeared after it.
    // c: a repeated uppercase followed by a lowercase exists; only lowercase
    //    characters may follow.
    let mut b = 0i64;
    let mut c = 0i64;

    let mut seen_fixed = [false; 26];
    let mut fixed_count = 0usize;

    for &ch in s {
        if ch == b'?' {
            let mut next_a = [0i64; 27];
            let mut repeated = 0i64;
            let available = 26usize - fixed_count;

            for t in 0..=26 {
                if a[t] == 0 {
                    continue;
                }

                // Replace this '?' with a lowercase letter.
                next_a[t] = (next_a[t] + a[t] * 26) % MOD;

                // Replace it with an uppercase letter not seen before.
                if t < available {
                    let choices = (available - t) as i64;
                    next_a[t + 1] = (next_a[t + 1] + a[t] * choices) % MOD;
                }

                // Replace it with an uppercase letter seen before.
                let repeated_choices = (fixed_count + t) as i64;
                repeated = (repeated + a[t] * repeated_choices) % MOD;
            }

            let next_b = (b * 26 + repeated) % MOD;
            let next_c = (c * 26 + b * 26) % MOD;

            a = next_a;
            b = next_b;
            c = next_c;
        } else if ch.is_ascii_lowercase() {
            c = (c + b) % MOD;
            b = 0;
        } else {
            let idx = (ch - b'A') as usize;
            let mut repeated = 0i64;

            if seen_fixed[idx] {
                for t in 0..=26 {
                    repeated += a[t];
                    if repeated >= MOD {
                        repeated -= MOD;
                    }
                    a[t] = 0;
                }
            } else {
                let available = 26usize - fixed_count;
                for t in 0..=26 {
                    if a[t] == 0 || t == 0 {
                        continue;
                    }

                    // Among assignments using t distinct wildcard uppercase
                    // letters chosen from `available` letters, the fraction
                    // containing this fixed letter is t / available.
                    let rep = a[t] * (t as i64) % MOD * inv[available] % MOD;
                    repeated += rep;
                    if repeated >= MOD {
                        repeated -= MOD;
                    }
                    a[t] -= rep;
                    if a[t] < 0 {
                        a[t] += MOD;
                    }
                }

                seen_fixed[idx] = true;
                fixed_count += 1;
            }

            b = (b + repeated) % MOD;
            c = 0;
        }
    }

    let mut answer = (b + c) % MOD;
    for value in a {
        answer += value;
        if answer >= MOD {
            answer -= MOD;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
