    for c in s.bytes() {
        let type_off = if c == b'a' { x } else { y };
        let type_on = if c == b'a' { y } else { x };

        let next_off = off.min(on + z) + type_off;
        let next_on = on.min(off + z) + type_on;

        off = next_off;
        on = next_on;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", off.min(on)).unwrap();
}
