use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::new(); n];

    for _ in 0..n - 1 {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[u].push(v);
        graph[v].push(u);
    }

    let original_degree: Vec<usize> = graph.iter().map(Vec::len).collect();
    let mut degree = original_degree.clone();
    let mut alive = vec![true; n];
    let mut queue = VecDeque::new();

    for v in 0..n {
        if degree[v] == 1 {
            queue.push_back(v);
        }
    }

    let mut levels = Vec::new();

    while let Some(leaf) = queue.pop_front() {
        if !alive[leaf] || degree[leaf] != 1 {
            continue;
        }

        let center = graph[leaf]
            .iter()
            .copied()
            .find(|&next| alive[next])
            .unwrap();

        levels.push(original_degree[center]);

        let mut removed = Vec::with_capacity(graph[center].len() + 1);
        removed.push(center);
        for &next in &graph[center] {
            if alive[next] {
                removed.push(next);
            }
        }

        for &v in &removed {
            alive[v] = false;
        }

        for &v in &removed {
            for &next in &graph[v] {
                if alive[next] {
                    degree[next] -= 1;
                    if degree[next] == 1 {
                        queue.push_back(next);
                    }
                }
            }
        }
    }

    levels.sort_unstable();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for (i, level) in levels.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{level}").unwrap();
    }
    writeln!(out).unwrap();
}
