use std::collections::HashSet;
use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] != x {
            self.parent[x] = self.find(self.parent[x]);
        }
        self.parent[x]
    }

    fn unite(&mut self, a: usize, b: usize) {
        let mut a = self.find(a);
        let mut b = self.find(b);
        if a == b {
            return;
        }
        if self.size[a] < self.size[b] {
            std::mem::swap(&mut a, &mut b);
        }
        self.parent[b] = a;
        self.size[a] += self.size[b];
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace().map(|s| s.parse::<usize>().unwrap());

    let n = it.next().unwrap();
    let m = it.next().unwrap();

    let mut dsu = Dsu::new(n);
    for _ in 0..m {
        let u = it.next().unwrap() - 1;
        let v = it.next().unwrap() - 1;
        dsu.unite(u, v);
    }

    let k = it.next().unwrap();
    let mut forbidden = HashSet::with_capacity(k * 2);

    for _ in 0..k {
        let x = it.next().unwrap() - 1;
        let y = it.next().unwrap() - 1;
        let rx = dsu.find(x);
        let ry = dsu.find(y);
        let pair = if rx < ry { (rx, ry) } else { (ry, rx) };
        forbidden.insert(pair);
    }

    let q = it.next().unwrap();
    let mut output = String::with_capacity(q * 4);

    for _ in 0..q {
        let p = it.next().unwrap() - 1;
        let qv = it.next().unwrap() - 1;
        let rp = dsu.find(p);
        let rq = dsu.find(qv);

        if rp == rq {
            output.push_str("Yes\n");
        } else {
            let pair = if rp < rq { (rp, rq) } else { (rq, rp) };
            if forbidden.contains(&pair) {
                output.push_str("No\n");
            } else {
                output.push_str("Yes\n");
            }
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
