use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::new(); n];
    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut best = vec![-1_i32; n];
    let mut heap = BinaryHeap::new();

    for _ in 0..k {
        let p: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let h: i32 = iter.next().unwrap().parse().unwrap();
        if h > best[p] {
            best[p] = h;
            heap.push((h, p));
        }
    }

    while let Some((stamina, vertex)) = heap.pop() {
        if stamina != best[vertex] {
            continue;
        }
        if stamina == 0 {
            continue;
        }

        let next_stamina = stamina - 1;
        for &next in &graph[vertex] {
            if next_stamina > best[next] {
                best[next] = next_stamina;
                heap.push((next_stamina, next));
            }
        }
    }

    let guarded: Vec<usize> = (0..n)
        .filter(|&v| best[v] >= 0)
        .map(|v| v + 1)
        .collect();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "{}", guarded.len()).unwrap();
    for (i, vertex) in guarded.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", vertex).unwrap();
    }
    writeln!(out).unwrap();
}
