    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let strings: Vec<&[u8]> = (0..n)
        .map(|_| iter.next().unwrap().as_bytes())
        .collect();

    let mut found = false;

    'outer: for i in 0..n {
        for j in 0..n {
            if i == j {
                continue;
            }

            let total_len = strings[i].len() + strings[j].len();
            let byte_at = |k: usize| {
                if k < strings[i].len() {
                    strings[i][k]
                } else {
                    strings[j][k - strings[i].len()]
                }
            };

            if (0..total_len / 2).all(|k| byte_at(k) == byte_at(total_len - 1 - k)) {
                found = true;
                break 'outer;
            }
