fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let grid: Vec<Vec<u8>> = (0..h)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let pattern = b"snuke";

    if grid[0][0] != pattern[0] {
        println!("No");
        return;
    }

    let mut visited = vec![false; h * w];
    let mut queue = VecDeque::new();
    visited[0] = true;
    queue.push_back((0usize, 0usize));

    let directions = [(1isize, 0isize), (-1, 0), (0, 1), (0, -1)];

    while let Some((row, col)) = queue.pop_front() {
        if row == h - 1 && col == w - 1 {
            let stdout = io::stdout();
            let mut out = io::BufWriter::new(stdout.lock());
            writeln!(out, "Yes").unwrap();
            return;
        }

        let current_index = pattern.iter().position(|&c| c == grid[row][col]).unwrap();
        let next_char = pattern[(current_index + 1) % pattern.len()];

        for &(dr, dc) in &directions {
            let nr = row as isize + dr;
            let nc = col as isize + dc;

            if nr < 0 || nr >= h as isize || nc < 0 || nc >= w as isize {
                continue;
            }

            let nr = nr as usize;
            let nc = nc as usize;
            let index = nr * w + nc;

            if !visited[index] && grid[nr][nc] == next_char {
                visited[index] = true;
                queue.push_back((nr, nc));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "No").unwrap();
}
