use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let grid: Vec<Vec<u8>> = (0..n)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut touched = vec![vec![false; m]; n];
    let mut visited_stop = vec![vec![false; m]; n];
    let mut queue = VecDeque::new();

    touched[1][1] = true;
    visited_stop[1][1] = true;
    queue.push_back((1usize, 1usize));

    let directions = [(-1isize, 0isize), (1, 0), (0, -1), (0, 1)];

    while let Some((row, col)) = queue.pop_front() {
        for &(dr, dc) in &directions {
            let mut r = row as isize;
            let mut c = col as isize;

            loop {
                let nr = r + dr;
                let nc = c + dc;

                if grid[nr as usize][nc as usize] == b'#' {
                    break;
                }

                r = nr;
                c = nc;
                touched[r as usize][c as usize] = true;
            }

            let stop_row = r as usize;
            let stop_col = c as usize;
            if !visited_stop[stop_row][stop_col] {
                visited_stop[stop_row][stop_col] = true;
                queue.push_back((stop_row, stop_col));
            }
        }
    }

    let answer = touched
        .iter()
        .map(|row| row.iter().filter(|&&cell| cell).count())
        .sum::<usize>();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
