fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut holed = vec![false; h * w];
    for _ in 0..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let b: usize = iter.next().unwrap().parse().unwrap();
        holed[(a - 1) * w + (b - 1)] = true;
    }

    let mut previous = vec![0u16; w + 1];
    let mut current = vec![0u16; w + 1];
    let mut answer = 0u64;

    for i in 0..h {
        current[0] = 0;

        for j in 1..=w {
            if holed[i * w + (j - 1)] {
                current[j] = 0;
            } else {
                current[j] = 1 + previous[j]
                    .min(current[j - 1])
                    .min(previous[j - 1]);
                answer += current[j] as u64;
            }
        }

        std::mem::swap(&mut previous, &mut current);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
