use std::io::{self, Read, Write};

const S: usize = 100;

#[inline]
fn index(x: usize, y: usize, z: usize) -> usize {
    (x * S + y) * S + z
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut owner = vec![0u32; S * S * S];

    for i in 0..n {
        let x1: usize = it.next().unwrap().parse().unwrap();
        let y1: usize = it.next().unwrap().parse().unwrap();
        let z1: usize = it.next().unwrap().parse().unwrap();
        let x2: usize = it.next().unwrap().parse().unwrap();
        let y2: usize = it.next().unwrap().parse().unwrap();
        let z2: usize = it.next().unwrap().parse().unwrap();

        let id = (i + 1) as u32;
        for x in x1..x2 {
            for y in y1..y2 {
                for z in z1..z2 {
                    owner[index(x, y, z)] = id;
                }
            }
        }
    }

    let mut answer = vec![0usize; n];

    // Faces perpendicular to the x-axis.
    for x in 1..S {
        for y in 0..S {
            for z in 0..S {
                let a = owner[index(x - 1, y, z)];
                let b = owner[index(x, y, z)];
                if a == 0 || b == 0 || a == b {
                    continue;
                }

                let same_y = y > 0
                    && owner[index(x - 1, y - 1, z)] == a
                    && owner[index(x, y - 1, z)] == b;
                let same_z = z > 0
                    && owner[index(x - 1, y, z - 1)] == a
                    && owner[index(x, y, z - 1)] == b;

                if !same_y && !same_z {
                    answer[a as usize - 1] += 1;
                    answer[b as usize - 1] += 1;
                }
            }
        }
    }

    // Faces perpendicular to the y-axis.
    for y in 1..S {
        for x in 0..S {
            for z in 0..S {
                let a = owner[index(x, y - 1, z)];
                let b = owner[index(x, y, z)];
                if a == 0 || b == 0 || a == b {
                    continue;
                }

                let same_x = x > 0
                    && owner[index(x - 1, y - 1, z)] == a
                    && owner[index(x - 1, y, z)] == b;
                let same_z = z > 0
                    && owner[index(x, y - 1, z - 1)] == a
                    && owner[index(x, y, z - 1)] == b;

                if !same_x && !same_z {
                    answer[a as usize - 1] += 1;
                    answer[b as usize - 1] += 1;
                }
            }
        }
    }

    // Faces perpendicular to the z-axis.
    for z in 1..S {
        for x in 0..S {
            for y in 0..S {
                let a = owner[index(x, y, z - 1)];
                let b = owner[index(x, y, z)];
                if a == 0 || b == 0 || a == b {
                    continue;
                }

                let same_x = x > 0
                    && owner[index(x - 1, y, z - 1)] == a
                    && owner[index(x - 1, y, z)] == b;
                let same_y = y > 0
                    && owner[index(x, y - 1, z - 1)] == a
                    && owner[index(x, y - 1, z)] == b;

                if !same_x && !same_y {
                    answer[a as usize - 1] += 1;
                    answer[b as usize - 1] += 1;
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for value in answer {
