use std::io::{self, Read, Write};

fn value(
    regular_count: usize,
    slots: usize,
    pull_values: &[i64],
    regular_values: &[i64],
) -> i64 {
    let pull_count = pull_values.len().min(slots - regular_count);
    regular_values[regular_count] + pull_values[pull_count]
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut pull_tabs = Vec::<i64>::new();
    let mut regulars = Vec::<i64>::new();
    let mut openers = Vec::<i64>::new();

    for _ in 0..n {
        let t: usize = iter.next().unwrap().parse().unwrap();
        let x: i64 = iter.next().unwrap().parse().unwrap();

        match t {
            0 => pull_tabs.push(x),
            1 => regulars.push(x),
            2 => openers.push(x),
            _ => unreachable!(),
        }
    }

    pull_tabs.sort_unstable_by(|a, b| b.cmp(a));
    regulars.sort_unstable_by(|a, b| b.cmp(a));
    openers.sort_unstable_by(|a, b| b.cmp(a));

    let mut pull_prefix = vec![0i64; pull_tabs.len() + 1];
    for i in 0..pull_tabs.len() {
        pull_prefix[i + 1] = pull_prefix[i] + pull_tabs[i];
    }

    let mut regular_prefix = vec![0i64; regulars.len() + 1];
    for i in 0..regulars.len() {
        regular_prefix[i + 1] = regular_prefix[i] + regulars[i];
    }

    let mut answer = 0i64;
    let mut capacity = 0i64;
    let max_openers = m.min(openers.len());

    for opener_count in 0..=max_openers {
        let slots = m - opener_count;
        let max_regulars = slots
            .min(regulars.len())
            .min(capacity.min(regulars.len() as i64) as usize);

        let mut left = 0usize;
        let mut right = max_regulars;

        while left < right {
            let mid = (left + right) / 2;
            let current = value(mid, slots, &pull_prefix, &regular_prefix);
            let next = value(mid + 1, slots, &pull_prefix, &regular_prefix);

            if current <= next {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        answer = answer.max(value(left, slots, &pull_prefix, &regular_prefix));

        if opener_count < max_openers {
            capacity += openers[opener_count];
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
