use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn find(parent: &mut [usize], x: usize) -> usize {
    let mut root = x;
    while parent[root] != root {
        root = parent[root];
    }

    let mut cur = x;
    while parent[cur] != cur {
        let next = parent[cur];
        parent[cur] = root;
        cur = next;
    }
    root
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut inv = vec![0_i64; n + 1];
    inv[1] = 1;
    for i in 2..=n {
        let i64_value = i as i64;
        inv[i] = MOD
            - (MOD / i64_value) * inv[(MOD % i64_value) as usize] % MOD;
    }

    let total_nodes = 2 * n - 1;
    let mut left = vec![usize::MAX; total_nodes];
    let mut right = vec![usize::MAX; total_nodes];
    let mut left_value = vec![0_i64; total_nodes];
    let mut right_value = vec![0_i64; total_nodes];

    let mut parent: Vec<usize> = (0..n).collect();
    let mut size = vec![1_usize; n];
    let mut tree_root: Vec<usize> = (0..n).collect();

    for match_index in 0..(n - 1) {
        let p: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let q: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

        let rp = find(&mut parent, p);
        let rq = find(&mut parent, q);

        let size_p = size[rp];
        let size_q = size[rq];
        let merged_size = size_p + size_q;
        let node = n + match_index;

        left[node] = tree_root[rp];
        right[node] = tree_root[rq];
        left_value[node] = (size_p as i64) * inv[merged_size] % MOD;
        right_value[node] = (size_q as i64) * inv[merged_size] % MOD;

        parent[rq] = rp;
        size[rp] = merged_size;
        tree_root[rp] = node;
    }

    let component_root = find(&mut parent, 0);
    let root = tree_root[component_root];

    let mut answer = vec![0_i64; n];
    let mut stack = Vec::with_capacity(total_nodes);
    stack.push((root, 0_i64));

    while let Some((node, accumulated)) = stack.pop() {
        if node < n {
            answer[node] = accumulated;
        } else {
            stack.push((
                left[node],
                (accumulated + left_value[node]) % MOD,
            ));
            stack.push((
                right[node],
                (accumulated + right_value[node]) % MOD,
            ));
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for (i, value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", value).unwrap();
    }
    writeln!(out).unwrap();
}
