use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let mut grid = Vec::with_capacity(h);
    let mut row_counts = vec![[0usize; 26]; h];
    let mut col_counts = vec![[0usize; 26]; w];

    for i in 0..h {
        let row: Vec<u8> = iter.next().unwrap().bytes().map(|b| b - b'a').collect();
        for j in 0..w {
            let color = row[j] as usize;
            row_counts[i][color] += 1;
            col_counts[j][color] += 1;
        }
        grid.push(row);
    }

    let mut row_alive = vec![true; h];
    let mut col_alive = vec![true; w];
    let mut row_len = vec![w; h];
    let mut col_len = vec![h; w];

    let mut alive_rows = h;
    let mut alive_cols = w;

    let mut candidate_rows: Vec<usize> = (0..h).collect();
    let mut candidate_cols: Vec<usize> = (0..w).collect();
    let mut row_queued = vec![true; h];
    let mut col_queued = vec![true; w];

    loop {
        let current_rows = std::mem::take(&mut candidate_rows);
        let current_cols = std::mem::take(&mut candidate_cols);

        let mut delete_rows = Vec::new();
        let mut delete_cols = Vec::new();

        for r in current_rows {
            row_queued[r] = false;
            if row_alive[r]
                && row_len[r] >= 2
                && row_counts[r].iter().any(|&count| count == row_len[r])
            {
                delete_rows.push(r);
            }
        }

        for c in current_cols {
            col_queued[c] = false;
            if col_alive[c]
                && col_len[c] >= 2
                && col_counts[c].iter().any(|&count| count == col_len[c])
            {
                delete_cols.push(c);
            }
        }

        if delete_rows.is_empty() && delete_cols.is_empty() {
            break;
        }

        for &r in &delete_rows {
            row_alive[r] = false;
            alive_rows -= 1;
        }
        for &c in &delete_cols {
            col_alive[c] = false;
            alive_cols -= 1;
        }

        for &r in &delete_rows {
            for c in 0..w {
                if col_alive[c] {
                    let color = grid[r][c] as usize;
                    col_counts[c][color] -= 1;
                    col_len[c] -= 1;

                    if !col_queued[c] {
                        col_queued[c] = true;
                        candidate_cols.push(c);
                    }
                }
            }
        }

        for &c in &delete_cols {
            for r in 0..h {
                if row_alive[r] {
                    let color = grid[r][c] as usize;
                    row_counts[r][color] -= 1;
                    row_len[r] -= 1;

                    if !row_queued[r] {
                        row_queued[r] = true;
                        candidate_rows.push(r);
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", alive_rows * alive_cols).unwrap();
}
