    let mut prerequisites = vec![Vec::<usize>::new(); n];

    for books in &mut prerequisites {
        let c: usize = iter.next().unwrap().parse().unwrap();
        books.reserve(c);
        for _ in 0..c {
            let book: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            books.push(book);
        }
    }

    let mut state = vec![0u8; n];
    let mut stack = vec![(0usize, 0usize)];
    let mut order = Vec::new();
    state[0] = 1;

    while let Some(&(book, next_index)) = stack.last() {
        if next_index < prerequisites[book].len() {
            let dependency = prerequisites[book][next_index];
            stack.last_mut().unwrap().1 += 1;

            if state[dependency] == 0 {
                state[dependency] = 1;
                stack.push((dependency, 0));
            }
        } else {
            stack.pop();
            state[book] = 2;
            if book != 0 {
                order.push(book + 1);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, book) in order.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{book}").unwrap();
    }
    writeln!(out).unwrap();
