        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut low = *lengths.iter().max().unwrap();
    let mut high = lengths.iter().sum::<i64>() + (n as i64 - 1);

    while low < high {
        let mid = low + (high - low) / 2;

        let mut lines = 1usize;
        let mut current_width = 0i64;

        for &length in &lengths {
            if current_width == 0 {
                current_width = length;
            } else if current_width + 1 + length <= mid {
                current_width += 1 + length;
            } else {
                lines += 1;
                current_width = length;
            }
        }

        if lines <= m {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
