use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let x: i64 = iter.next().unwrap().parse().unwrap();
    let y: i64 = iter.next().unwrap().parse().unwrap();

    const PERIOD: usize = 840;

    let mut wait = [[0usize; PERIOD]; 9];
    for p in 1..=8 {
        for r in 0..PERIOD {
            wait[p][r] = (p - r % p) % p;
        }
    }

    let mut arrival: Vec<i64> = (0..PERIOD).map(|r| r as i64).collect();
    let mut residues: Vec<u16> = (0..PERIOD).map(|r| r as u16).collect();

    for _ in 0..n - 1 {
        let p: usize = iter.next().unwrap().parse().unwrap();
        let t: i64 = iter.next().unwrap().parse().unwrap();
        let t_mod = (t % PERIOD as i64) as usize;

        for r in 0..PERIOD {
            let current_residue = residues[r] as usize;
            let waiting_time = wait[p][current_residue];

            arrival[r] += waiting_time as i64 + t;

            let mut shift = t_mod + waiting_time;
            if shift >= PERIOD {
                shift -= PERIOD;
            }

            let mut next_residue = current_residue + shift;
            if next_residue >= PERIOD {
                next_residue -= PERIOD;
            }
            residues[r] = next_residue as u16;
        }
    }

    let q: usize = iter.next().unwrap().parse().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let departure: i64 = iter.next().unwrap().parse().unwrap();
        let bus_stop_time = departure + x;
        let residue = (bus_stop_time % PERIOD as i64) as usize;
        let cycles = bus_stop_time / PERIOD as i64;
        let answer = cycles * PERIOD as i64 + arrival[residue] + y;
        writeln!(out, "{answer}").unwrap();
    }
}
