fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let m: usize = iter.next().unwrap().parse().unwrap();
    let reels: Vec<Vec<u8>> = (0..3)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut answer = usize::MAX;

    for digit in b'0'..=b'9' {
        for first in 0..3 {
            for second in 0..3 {
                if second == first {
                    continue;
                }
                for third in 0..3 {
                    if third == first || third == second {
                        continue;
                    }

                    let order = [first, second, third];
                    let mut next_time = 0usize;
                    let mut possible = true;
                    let mut finish_time = 0usize;

                    for &reel in &order {
                        let mut time = next_time;
                        while time < 3 * m && reels[reel][time % m] != digit {
                            time += 1;
                        }

                        if time == 3 * m {
                            possible = false;
                            break;
                        }

                        finish_time = time;
                        next_time = time + 1;
                    }

                    if possible {
                        answer = answer.min(finish_time);
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if answer == usize::MAX {
        writeln!(out, "-1").unwrap();
    } else {
        writeln!(out, "{answer}").unwrap();
    }
}
