fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut available: BTreeSet<usize> = (0..n).collect();
    let mut returning: BinaryHeap<Reverse<(u64, usize)>> = BinaryHeap::new();
    let mut totals = vec![0u64; n];

    for _ in 0..m {
        let t: u64 = iter.next().unwrap().parse().unwrap();
        let w: u64 = iter.next().unwrap().parse().unwrap();
        let s: u64 = iter.next().unwrap().parse().unwrap();

        while let Some(&Reverse((return_time, person))) = returning.peek() {
            if return_time > t {
                break;
            }
            returning.pop();
            available.insert(person);
        }

        if let Some(&person) = available.iter().next() {
            available.remove(&person);
            totals[person] += w;
            returning.push(Reverse((t + s, person)));
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for total in totals {
        writeln!(out, "{total}").unwrap();
    }
}
