use std::io::{self, Read, Write};

fn count_descendants(n: u64, root: u64, depth: u64) -> u128 {
    if depth >= 64 {
        return 0;
    }

    let shift = depth as u32;
    let left = (root as u128) << shift;
    let n = n as u128;

    if left > n {
        return 0;
    }

    let right = ((((root as u128) + 1) << shift) - 1).min(n);
    right - left + 1
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let t: usize = iter.next().unwrap().parse().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..t {
        let n: u64 = iter.next().unwrap().parse().unwrap();
        let x: u64 = iter.next().unwrap().parse().unwrap();
        let k: u64 = iter.next().unwrap().parse().unwrap();

        let mut answer = count_descendants(n, x, k);
        let mut child = x;
        let mut distance_up = 1u64;

        while child > 1 && distance_up <= k {
            let parent = child / 2;

            if distance_up == k {
                answer += 1;
            } else {
                let sibling = child ^ 1;
                let remaining_depth = k - distance_up - 1;
                answer += count_descendants(n, sibling, remaining_depth);
            }

            child = parent;
            distance_up += 1;
        }

        writeln!(out, "{answer}").unwrap();
    }
}
