use std::collections::HashSet;
use std::io::{self, Read, Write};

fn generate_placements(mut cells: Vec<(i32, i32)>) -> Vec<u16> {
    let mut placements = HashSet::new();

    for _ in 0..4 {
        let min_r = cells.iter().map(|&(r, _)| r).min().unwrap();
        let min_c = cells.iter().map(|&(_, c)| c).min().unwrap();

        for cell in &mut cells {
            cell.0 -= min_r;
            cell.1 -= min_c;
        }

        let height = cells.iter().map(|&(r, _)| r).max().unwrap() + 1;
        let width = cells.iter().map(|&(_, c)| c).max().unwrap() + 1;

        if height <= 4 && width <= 4 {
            for dr in 0..=4 - height {
                for dc in 0..=4 - width {
                    let mut mask = 0u16;
                    for &(r, c) in &cells {
                        let nr = r + dr;
                        let nc = c + dc;
                        mask |= 1u16 << (nr * 4 + nc);
                    }
                    placements.insert(mask);
                }
            }
        }

        // Rotate 90 degrees clockwise. Normalization is done next iteration.
        cells = cells.into_iter().map(|(r, c)| (c, -r)).collect();
    }

    placements.into_iter().collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let rows: Vec<&str> = input.split_whitespace().collect();

