use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let p: usize = iter.next().unwrap().parse().unwrap();

    let base = p + 1;
    let states = base.pow(k as u32);
    let inf = i64::MAX / 4;

    let mut dp = vec![inf; states];
    dp[0] = 0;

    for _ in 0..n {
        let cost: i64 = iter.next().unwrap().parse().unwrap();
        let mut increase = vec![0usize; k];
        for x in &mut increase {
            *x = iter.next().unwrap().parse().unwrap();
        }

        let mut next = dp.clone();

        for state in 0..states {
            if dp[state] == inf {
                continue;
            }

            let mut value = state;
            let mut next_state = 0usize;
            let mut multiplier = 1usize;

            for j in 0..k {
                let current = value % base;
                value /= base;
                let updated = (current + increase[j]).min(p);
                next_state += updated * multiplier;
                multiplier *= base;
            }

            next[next_state] = next[next_state].min(dp[state] + cost);
        }

        dp = next;
    }

    let answer = dp[states - 1];
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if answer == inf {
        writeln!(out, "-1").unwrap();
    } else {
        writeln!(out, "{answer}").unwrap();
    }
}
