        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let solved: Vec<Vec<u8>> = (0..n)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut totals = vec![0i32; n];
    for i in 0..n {
        totals[i] = (i + 1) as i32;
        for j in 0..m {
            if solved[i][j] == b'o' {
                totals[i] += scores[j];
            }
        }
    }

    let mut output = io::BufWriter::new(io::stdout().lock());

    for i in 0..n {
        let max_other = (0..n)
            .filter(|&j| j != i)
            .map(|j| totals[j])
            .max()
            .unwrap();

        let mut current = totals[i];
        let mut answer = 0;

        if current <= max_other {
            let mut unsolved: Vec<i32> = (0..m)
                .filter(|&j| solved[i][j] == b'x')
                .map(|j| scores[j])
                .collect();

            unsolved.sort_unstable_by(|a, b| b.cmp(a));

            for score in unsolved {
                current += score;
                answer += 1;
                if current > max_other {
                    break;
                }
            }
        }

        writeln!(output, "{answer}").unwrap();
    }
