use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1_i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let x: usize = iter.next().unwrap().parse().unwrap();
    let times: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let inv_n = mod_pow(n as i64, MOD - 2);

    // dp[t]: probability that a song starts exactly at time t.
    let mut dp = vec![0_i64; x + 1];
    dp[0] = 1;

    for t in 1..=x {
        let mut sum = 0_i64;
        for &duration in &times {
            if duration <= t {
                sum += dp[t - duration];
                if sum >= MOD {
                    sum -= MOD;
                }
            }
        }
        dp[t] = sum * inv_n % MOD;
    }

    let first_duration = times[0];
    let start = (x + 1).saturating_sub(first_duration);

    let mut answer = 0_i64;
    for &probability in &dp[start..=x] {
        answer += probability;
        if answer >= MOD {
            answer -= MOD;
        }
    }
    answer = answer * inv_n % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
