use std::io::{self, Read, Write};

fn could_match(a: &[u8], b: &[u8]) -> bool {
    let len_a = a.len();
    let len_b = b.len();

    if len_a.abs_diff(len_b) > 1 {
        return false;
    }

    if len_a == len_b {
        let mut differences = 0;
        for i in 0..len_a {
            if a[i] != b[i] {
                differences += 1;
                if differences > 1 {
                    return false;
                }
            }
        }
        return true;
    }

    let (shorter, longer) = if len_a < len_b { (a, b) } else { (b, a) };
    let (mut i, mut j) = (0, 0);
    let mut skipped = false;

    while i < shorter.len() && j < longer.len() {
        if shorter[i] == longer[j] {
            i += 1;
            j += 1;
        } else if skipped {
            return false;
        } else {
            skipped = true;
            j += 1;
        }
    }

    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let target = iter.next().unwrap().as_bytes();

    let mut indices = Vec::new();

    for index in 1..=n {
        let candidate = iter.next().unwrap().as_bytes();
        if could_match(candidate, target) {
            indices.push(index);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "{}", indices.len()).unwrap();
    for (i, index) in indices.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{index}").unwrap();
    }
    writeln!(out).unwrap();
}
