#[derive(Clone, Copy)]
struct Edge {
    to: usize,
    beauty: f64,
    cost: f64,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::<Edge>::new(); n];
    let mut upper = 0.0_f64;

    for _ in 0..m {
        let u: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let beauty: f64 = it.next().unwrap().parse().unwrap();
        let cost: f64 = it.next().unwrap().parse().unwrap();

        upper = upper.max(beauty / cost);
        graph[u].push(Edge {
            to: v,
            beauty,
            cost,
        });
    }

    let feasible = |ratio: f64| -> bool {
        let mut dp = vec![f64::NEG_INFINITY; n];
        dp[0] = 0.0;

        for u in 0..n {
            if !dp[u].is_finite() {
                continue;
            }
            let current = dp[u];
            for edge in &graph[u] {
                let candidate = current + edge.beauty - ratio * edge.cost;
                if candidate > dp[edge.to] {
                    dp[edge.to] = candidate;
                }
            }
        }

        dp[n - 1] >= 0.0
    };

    let mut low = 0.0_f64;
    let mut high = upper;

    for _ in 0..100 {
        let mid = (low + high) / 2.0;
        if feasible(mid) {
            low = mid;
        } else {
            high = mid;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.15}", low).unwrap();
}
