use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let mut grid = Vec::with_capacity(h * w);
    for _ in 0..h {
        grid.extend_from_slice(iter.next().unwrap().as_bytes());
    }

    let mut components = 0usize;
    let mut stack = Vec::new();

    for start in 0..h * w {
        if grid[start] != b'#' {
            continue;
        }

        components += 1;
        grid[start] = b'.';
        stack.push(start);

        while let Some(pos) = stack.pop() {
            let row = pos / w;
            let col = pos % w;

            let row_start = row.saturating_sub(1);
            let row_end = (row + 1).min(h - 1);
            let col_start = col.saturating_sub(1);
            let col_end = (col + 1).min(w - 1);

            for next_row in row_start..=row_end {
                for next_col in col_start..=col_end {
                    let next = next_row * w + next_col;
                    if grid[next] == b'#' {
                        grid[next] = b'.';
                        stack.push(next);
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{components}").unwrap();
}
