fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut d = Vec::with_capacity(n);
    let mut total_length = 0_i64;
    for _ in 0..n {
        let value: i64 = it.next().unwrap().parse().unwrap();
        d.push(value);
        total_length += value;
    }

    let l1: i64 = it.next().unwrap().parse().unwrap();
    let c1: i64 = it.next().unwrap().parse().unwrap();
    let k1: usize = it.next().unwrap().parse().unwrap();

    let l2: i64 = it.next().unwrap().parse().unwrap();
    let c2: i64 = it.next().unwrap().parse().unwrap();
    let k2: usize = it.next().unwrap().parse().unwrap();

    let mut out = io::BufWriter::new(io::stdout().lock());

    let total_capacity = l1 * k1 as i64 + l2 * k2 as i64;
    if total_length > total_capacity {
        writeln!(out, "-1").unwrap();
        return;
    }

    const INF: usize = usize::MAX / 4;
    let mut dp = vec![INF; k1 + 1];
    dp[0] = 0;
    let mut max_used = 0usize;

    for demand in d {
        let max_for_section =
            k1.min(((demand + l1 - 1) / l1) as usize);

        let mut options: Vec<(usize, usize)> = Vec::new();
        let mut last_b = INF;

        for a in 0..=max_for_section {
            let remaining = demand - l1 * a as i64;
            let b = if remaining <= 0 {
                0
            } else {
                ((remaining + l2 - 1) / l2) as usize
            };

            if b <= k2 && b < last_b {
                options.push((a, b));
                last_b = b;
            }
        }

        if options.is_empty() {
            writeln!(out, "-1").unwrap();
            return;
        }

        let section_max_a = options.iter().map(|&(a, _)| a).max().unwrap();
        let new_max = k1.min(max_used + section_max_a);
        let mut next = vec![INF; k1 + 1];

        for used_a in 0..=max_used {
            if dp[used_a] == INF {
                continue;
            }

            for &(a, b) in &options {
                let new_a = used_a + a;
                if new_a > k1 {
                    break;
                }

                let new_b = dp[used_a] + b;
                if new_b <= k2 && new_b < next[new_a] {
                    next[new_a] = new_b;
                }
            }
        }

        dp = next;
        max_used = new_max;
    }

    let mut answer = i64::MAX;
    for used_a in 0..=k1 {
        if dp[used_a] <= k2 {
            let cost = used_a as i64 * c1 + dp[used_a] as i64 * c2;
            answer = answer.min(cost);
        }
    }

    if answer == i64::MAX {
        writeln!(out, "-1").unwrap();
    } else {
        writeln!(out, "{answer}").unwrap();
    }
}
