use std::io::{self, Read, Write};

fn generate_patterns(n: usize, first: u8) -> Vec<Vec<i8>> {
    let mut patterns = Vec::new();

    for a in 0..n {
        for b in 0..n {
            if b == a {
                continue;
            }
            for c in 0..n {
                if c == a || c == b {
                    continue;
                }

                let mut pattern = vec![-1; n];
                pattern[a] = 0;
                pattern[b] = 1;
                pattern[c] = 2;

                let left = a.min(b).min(c);
                if pattern[left] as u8 == first - b'A' {
                    patterns.push(pattern);
                }
            }
        }
    }

    patterns
}

fn dfs(
    row: usize,
    n: usize,
    patterns: &[Vec<Vec<i8>>],
    top: &[u8],
    column_masks: &mut [u8],
    answer: &mut [usize],
) -> bool {
    if row == n {
        return column_masks.iter().all(|&mask| mask == 0b111);
    }

    for (index, pattern) in patterns[row].iter().enumerate() {
        let old_masks = column_masks.to_vec();
        let mut valid = true;

        for col in 0..n {
            let ch = pattern[col];
            if ch < 0 {
                continue;
            }

            let bit = 1u8 << (ch as u8);

            if column_masks[col] & bit != 0 {
                valid = false;
                break;
            }

            if column_masks[col] == 0 && ch as u8 != top[col] - b'A' {
                valid = false;
                break;
            }

            column_masks[col] |= bit;
        }

        if valid {
            let remaining_rows = n - row - 1;
            for &mask in column_masks.iter() {
                let missing = 3usize - mask.count_ones() as usize;
                if missing > remaining_rows {
                    valid = false;
                    break;
                }
            }
        }

        if valid {
            answer[row] = index;
            if dfs(row + 1, n, patterns, top, column_masks, answer) {
                return true;
            }
        }

        column_masks.copy_from_slice(&old_masks);
    }

    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let r = iter.next().unwrap().as_bytes().to_vec();
    let c = iter.next().unwrap().as_bytes().to_vec();

    let patterns: Vec<Vec<Vec<i8>>> = (0..n)
        .map(|i| generate_patterns(n, r[i]))
        .collect();

    let mut column_masks = vec![0u8; n];
    let mut answer = vec![0usize; n];

    let possible = dfs(
        0,
        n,
        &patterns,
        &c,
        &mut column_masks,
        &mut answer,
    );

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if !possible {
        writeln!(out, "No").unwrap();
        return;
    }

    writeln!(out, "Yes").unwrap();
    for row in 0..n {
        let pattern = &patterns[row][answer[row]];
        let line: String = pattern
            .iter()
            .map(|&ch| {
                if ch < 0 {
                    '.'
                } else {
                    (b'A' + ch as u8) as char
                }
            })
            .collect();
        writeln!(out, "{}", line).unwrap();
    }
}
