use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    rank: Vec<usize>,
    parity: Vec<u8>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            rank: vec![0; n],
            parity: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> (usize, u8) {
        if self.parent[x] == x {
            return (x, 0);
        }
        let p = self.parent[x];
        let (root, p_parity) = self.find(p);
        self.parity[x] ^= p_parity;
        self.parent[x] = root;
        (root, self.parity[x])
    }

    fn unite_different(&mut self, x: usize, y: usize) -> bool {
        let (mut rx, mut px) = self.find(x);
        let (mut ry, mut py) = self.find(y);

        if rx == ry {
            return (px ^ py) == 1;
        }

        if self.rank[rx] < self.rank[ry] {
            std::mem::swap(&mut rx, &mut ry);
            std::mem::swap(&mut px, &mut py);
        }

        self.parent[ry] = rx;
        self.parity[ry] = px ^ py ^ 1;

        if self.rank[rx] == self.rank[ry] {
            self.rank[rx] += 1;
        }

        true
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(m);
    for _ in 0..m {
        a.push(iter.next().unwrap().parse::<usize>().unwrap() - 1);
    }

    let mut dsu = Dsu::new(n);
    let mut possible = true;

    for &x in &a {
        let y = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        if possible && !dsu.unite_different(x, y) {
            possible = false;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
