fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let d: i64 = input.trim().parse().unwrap();

    let mut root = (d as f64).sqrt() as i64;
    while root * root < d {
        root += 1;
    }
    while root > 0 && (root - 1) * (root - 1) >= d {
        root -= 1;
    }

    let mut answer = d;
    let mut y = root;

    for x in 0..=root {
        while y > 0 && x * x + y * y > d {
            answer = answer.min(x * x + y * y - d);
            y -= 1;
        }

        let sum = x * x + y * y;
        answer = answer.min((sum - d).abs());

        if answer == 0 {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
