fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    let mut count = vec![0usize; n + 1];

    for _ in 0..n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        a.push(value);
        if value <= n {
            count[value] += 1;
        }
    }

    let mut missing = BTreeSet::new();
    for value in 0..=n {
        if count[value] == 0 {
            missing.insert(value);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let index: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let new_value: usize = iter.next().unwrap().parse().unwrap();
        let old_value = a[index];

        if old_value <= n {
            count[old_value] -= 1;
            if count[old_value] == 0 {
                missing.insert(old_value);
            }
        }

        if new_value <= n {
            if count[new_value] == 0 {
                missing.remove(&new_value);
            }
            count[new_value] += 1;
        }

        a[index] = new_value;
        writeln!(out, "{}", missing.first().unwrap()).unwrap();
    }
}
