fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let _n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..k)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut prefix = vec![0_i64; k + 1];
    let mut i = 2;
    while i <= k {
        prefix[i] = prefix[i - 2] + a[i - 1] - a[i - 2];
        i += 2;
    }

    let answer = if k % 2 == 0 {
        prefix[k]
    } else {
        let mut suffix = vec![0_i64; k + 1];
        let mut i = k;
        while i >= 2 {
            i -= 2;
            suffix[i] = suffix[i + 2] + a[i + 1] - a[i];
        }

        let mut result = i64::MAX;
        for removed in (0..k).step_by(2) {
            result = result.min(prefix[removed] + suffix[removed + 1]);
        }
        result
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
