    let n: usize = input.trim().parse().unwrap();

    let mut grid = vec![vec![0usize; n]; n];
    let center = n / 2;
    let mut number = 1usize;

    let (mut top, mut bottom) = (0usize, n - 1);
    let (mut left, mut right) = (0usize, n - 1);

    while top <= bottom && left <= right {
        for col in left..=right {
            if top != center || col != center {
                grid[top][col] = number;
                number += 1;
            }
        }
        top += 1;

        if top <= bottom {
            for row in top..=bottom {
                if row != center || right != center {
                    grid[row][right] = number;
                    number += 1;
                }
            }
        }
        if right == 0 {
            break;
        }
        right -= 1;

        if top <= bottom && left <= right {
            for col in (left..=right).rev() {
                if bottom != center || col != center {
                    grid[bottom][col] = number;
                    number += 1;
                }
            }
            if bottom == 0 {
                break;
            }
            bottom -= 1;
        }

        if left <= right && top <= bottom {
            for row in (top..=bottom).rev() {
                if row != center || left != center {
                    grid[row][left] = number;
                    number += 1;
                }
            }
            left += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 0..n {
        for j in 0..n {
            if j > 0 {
                write!(out, " ").unwrap();
            }
            if i == center && j == center {
                write!(out, "T").unwrap();
            } else {
