    let grid: Vec<Vec<u8>> = (0..h)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut answer = usize::MAX;

    if k <= w {
        for row in &grid {
            let mut x_count = 0usize;
            let mut dot_count = 0usize;

            for &cell in &row[..k] {
                if cell == b'x' {
                    x_count += 1;
                } else if cell == b'.' {
                    dot_count += 1;
                }
            }

            if x_count == 0 {
                answer = answer.min(dot_count);
            }

            for right in k..w {
                let left_cell = row[right - k];
                if left_cell == b'x' {
                    x_count -= 1;
                } else if left_cell == b'.' {
                    dot_count -= 1;
                }

                let right_cell = row[right];
                if right_cell == b'x' {
                    x_count += 1;
                } else if right_cell == b'.' {
                    dot_count += 1;
                }

                if x_count == 0 {
                    answer = answer.min(dot_count);
                }
            }
        }
    }

    if k <= h {
        for col in 0..w {
            let mut x_count = 0usize;
            let mut dot_count = 0usize;

            for row in 0..k {
                let cell = grid[row][col];
                if cell == b'x' {
                    x_count += 1;
                } else if cell == b'.' {
                    dot_count += 1;
                }
            }

            if x_count == 0 {
                answer = answer.min(dot_count);
            }

            for bottom in k..h {
                let top_cell = grid[bottom - k][col];
                if top_cell == b'x' {
                    x_count -= 1;
                } else if top_cell == b'.' {
                    dot_count -= 1;
