fn main() {
    let stdin = io::stdin();
    let mut input = BufReader::new(stdin.lock());

    let mut line = String::new();
    input.read_line(&mut line).unwrap();
    let n: usize = line.trim().parse().unwrap();

    let mut m = 0usize;
    while (1usize << m) < n {
        m += 1;
    }

    let stdout = io::stdout();
    let mut output = BufWriter::new(stdout.lock());

    writeln!(output, "{}", m).unwrap();

    for bit in 0..m {
        let bottles: Vec<usize> = (1..=n)
            .filter(|&bottle| ((bottle - 1) >> bit) & 1 == 1)
            .collect();

        write!(output, "{}", bottles.len()).unwrap();
        for bottle in bottles {
            write!(output, " {}", bottle).unwrap();
        }
        writeln!(output).unwrap();
    }
    output.flush().unwrap();

    line.clear();
    input.read_line(&mut line).unwrap();
    let s = line.trim().as_bytes();

    let mut spoiled = 0usize;
    for (bit, &result) in s.iter().enumerate() {
        if result == b'1' {
            spoiled |= 1usize << bit;
        }
    }

    writeln!(output, "{}", spoiled + 1).unwrap();
    output.flush().unwrap();
