            .filter(|&bottle| ((bottle - 1) >> bit) & 1 == 1)
            .collect();

        write!(output, "{}", bottles.len()).unwrap();
        for bottle in bottles {
            write!(output, " {bottle}").unwrap();
        }
        writeln!(output).unwrap();
    }
    output.flush().unwrap();

    line.clear();
    input.read_line(&mut line).unwrap();
    let s = line.trim().as_bytes();

    let mut spoiled = 0usize;
    for (bit, &result) in s.iter().enumerate() {
        if result == b'1' {
            spoiled |= 1usize << bit;
        }
    }

    writeln!(output, "{}", spoiled + 1).unwrap();
    output.flush().unwrap();
}
