use std::collections::HashMap;
use std::io::{self, Read, Write};

fn cost(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
    if n <= 1 {
        return 0;
    }
    if let Some(&value) = memo.get(&n) {
        return value;
    }

    let value = n as u128
        + cost(n / 2, memo)
        + cost((n + 1) / 2, memo);

    memo.insert(n, value);
    value
}

