use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::<(usize, u64)>::new(); n];

    for i in 0..n - 1 {
        let a: u64 = iter.next().unwrap().parse().unwrap();
        let b: u64 = iter.next().unwrap().parse().unwrap();
        let x: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

        graph[i].push((i + 1, a));
        graph[i].push((x, b));
    }

    let mut dist = vec![u64::MAX; n];
    let mut heap = BinaryHeap::new();

    dist[0] = 0;
    heap.push(Reverse((0_u64, 0_usize)));

    while let Some(Reverse((cost, node))) = heap.pop() {
        if cost != dist[node] {
            continue;
        }
        if node == n - 1 {
            break;
        }

        for &(next, weight) in &graph[node] {
            let next_cost = cost + weight;
            if next_cost < dist[next] {
                dist[next] = next_cost;
                heap.push(Reverse((next_cost, next)));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dist[n - 1]).unwrap();
}
