use std::io::{self, Read, Write};

struct Fenwick {
    n: usize,
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            n,
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, index: usize, value: i64) {
        let mut i = index + 1;
        while i <= self.n {
            self.tree[i] += value;
            i += i & (!i + 1);
        }
    }

    fn prefix_sum(&self, index: usize) -> i64 {
        let mut i = index + 1;
        let mut result = 0;
        while i > 0 {
            result += self.tree[i];
            i &= i - 1;
        }
        result
    }

    fn range_add(&mut self, left: usize, right: usize, value: i64) {
        if left >= right {
            return;
        }
        self.add(left, value);
        if right < self.n {
            self.add(right, -value);
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut fenwick = Fenwick::new(n);
    let mut previous = 0i64;

    for i in 0..n {
        let value: i64 = iter.next().unwrap().parse().unwrap();
        fenwick.add(i, value - previous);
        previous = value;
    }

    for _ in 0..m {
        let b: usize = iter.next().unwrap().parse().unwrap();
        let balls = fenwick.prefix_sum(b);

        fenwick.range_add(b, b + 1, -balls);

        let quotient = balls / n as i64;
        let remainder = (balls % n as i64) as usize;

        if quotient > 0 {
            fenwick.range_add(0, n, quotient);
        }

        if remainder > 0 {
            let start = (b + 1) % n;
            if start + remainder <= n {
                fenwick.range_add(start, start + remainder, 1);
            } else {
                fenwick.range_add(start, n, 1);
                fenwick.range_add(0, start + remainder - n, 1);
            }
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());

    for i in 0..n {
        if i > 0 {
            write!(output, " ").unwrap();
        }
        write!(output, "{}", fenwick.prefix_sum(i)).unwrap();
    }
    writeln!(output).unwrap();
}
