    let w: usize = iter.next().unwrap().parse().unwrap();
    let _n: usize = iter.next().unwrap().parse().unwrap();
    let moves = iter.next().unwrap().as_bytes();

    let words = (w + 63) / 64;
    let mut land = vec![0u64; h * words];

    for r in 0..h {
        let row = iter.next().unwrap().as_bytes();
        for c in 0..w {
            if row[c] == b'.' {
                land[r * words + c / 64] |= 1u64 << (c % 64);
            }
        }
    }

    let mut current = land.clone();
    let mut next = vec![0u64; h * words];

    for &direction in moves {
        match direction {
            b'L' => {
                for r in 0..h {
                    let base = r * words;
                    for k in 0..words {
                        let mut shifted = current[base + k] >> 1;
                        if k + 1 < words {
                            shifted |= current[base + k + 1] << 63;
                        }
                        next[base + k] = shifted & land[base + k];
                    }
                }
            }
            b'R' => {
                for r in 0..h {
                    let base = r * words;
                    for k in 0..words {
                        let mut shifted = current[base + k] << 1;
                        if k > 0 {
                            shifted |= current[base + k - 1] >> 63;
                        }
                        next[base + k] = shifted & land[base + k];
                    }
                }
            }
            b'U' => {
                for r in 0..h {
                    let dest = r * words;
                    for k in 0..words {
                        next[dest + k] = if r + 1 < h {
                            current[(r + 1) * words + k] & land[dest + k]
                        } else {
                            0
                        };
                    }
                }
            }
            b'D' => {
                for r in 0..h {
                    let dest = r * words;
                    for k in 0..words {
                        next[dest + k] = if r > 0 {
                            current[(r - 1) * words + k] & land[dest + k]
                        } else {
                            0
                        };
                    }
                }
            }
            _ => unreachable!(),
        }
        std::mem::swap(&mut current, &mut next);
    }

    let answer: u64 = current.iter().map(|x| x.count_ones() as u64).sum();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
