use std::io::{self, Read, Write};

struct Fenwick {
    tree: Vec<i32>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut index: usize, value: i32) {
        while index < self.tree.len() {
            self.tree[index] += value;
            index += index & index.wrapping_neg();
        }
    }

    fn sum(&self, mut index: usize) -> i32 {
        let mut result = 0;
        while index > 0 {
            result += self.tree[index];
            index &= index - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    // bad[i] is true when the i-th and (i+1)-th characters are equal.
    let mut bad = vec![false; n + 1];
    let mut fenwick = Fenwick::new(n);

    for i in 1..n {
        if s[i - 1] == s[i] {
            bad[i] = true;
            fenwick.add(i, 1);
        }
    }

    let mut output = String::new();

    for _ in 0..q {
        let query_type: u8 = iter.next().unwrap().parse().unwrap();
        let l: usize = iter.next().unwrap().parse().unwrap();
        let r: usize = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            if l > 1 {
                let edge = l - 1;
                bad[edge] = !bad[edge];
                fenwick.add(edge, if bad[edge] { 1 } else { -1 });
            }
            if r < n {
                let edge = r;
                bad[edge] = !bad[edge];
                fenwick.add(edge, if bad[edge] { 1 } else { -1 });
            }
        } else {
            let bad_count = fenwick.sum(r - 1) - fenwick.sum(l - 1);
            if bad_count == 0 {
                output.push_str("Yes\n");
            } else {
                output.push_str("No\n");
            }
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
