use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Edge {
    from: usize,
    first: i64,
    interval: i64,
    count: i64,
    travel: i64,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut incoming: Vec<Vec<Edge>> = (0..n).map(|_| Vec::new()).collect();

    for _ in 0..m {
        let l: i64 = iter.next().unwrap().parse().unwrap();
        let d: i64 = iter.next().unwrap().parse().unwrap();
        let k: i64 = iter.next().unwrap().parse().unwrap();
        let c: i64 = iter.next().unwrap().parse().unwrap();
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

        incoming[b].push(Edge {
            from: a,
            first: l,
            interval: d,
            count: k,
            travel: c,
        });
    }

    const INF: i64 = 4_000_000_000_000_000_000;
    let mut latest = vec![-1_i64; n];
    latest[n - 1] = INF;

    let mut heap = BinaryHeap::new();
    heap.push((INF, n - 1));

    while let Some((deadline, station)) = heap.pop() {
        if latest[station] != deadline {
            continue;
        }

        for &edge in &incoming[station] {
            let latest_departure_limit = deadline - edge.travel;
            if latest_departure_limit < edge.first {
                continue;
            }

            let index = ((latest_departure_limit - edge.first) / edge.interval)
                .min(edge.count - 1);
            let departure = edge.first + index * edge.interval;

            if departure > latest[edge.from] {
                latest[edge.from] = departure;
                heap.push((departure, edge.from));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for &answer in &latest[..n - 1] {
        if answer < 0 {
            writeln!(out, "Unreachable").unwrap();
        } else {
            writeln!(out, "{answer}").unwrap();
        }
    }
}
