fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let t: usize = iter.next().unwrap().parse().unwrap();

    let mut scores = vec![0_i64; n];
    let mut counts: HashMap<i64, usize> = HashMap::new();
    counts.insert(0, n);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..t {
        let player: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let increase: i64 = iter.next().unwrap().parse().unwrap();

        let old_score = scores[player];
        if let Some(count) = counts.get_mut(&old_score) {
            *count -= 1;
            if *count == 0 {
                counts.remove(&old_score);
            }
        }

        let new_score = old_score + increase;
        scores[player] = new_score;
        *counts.entry(new_score).or_insert(0) += 1;

        writeln!(out, "{}", counts.len()).unwrap();
    }
}
