use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Point {
    x: i32,
    y: i32,
    z: i32,
    overlap_origin: i32,
}

fn overlap_len(a: i32, b: i32) -> i32 {
    (7 - (a - b).abs()).max(0)
}

fn pair_overlap(a: Point, b: Point) -> i32 {
    overlap_len(a.x, b.x) * overlap_len(a.y, b.y) * overlap_len(a.z, b.z)
}

fn triple_len(a: i32, b: i32) -> i32 {
    let left = 0.max(a).max(b);
    let right = 7.min(a + 7).min(b + 7);
    (right - left).max(0)
}

fn triple_overlap(a: Point, b: Point) -> i32 {
    triple_len(a.x, b.x) * triple_len(a.y, b.y) * triple_len(a.z, b.z)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let v1: i32 = it.next().unwrap().parse().unwrap();
    let v2: i32 = it.next().unwrap().parse().unwrap();
    let v3: i32 = it.next().unwrap().parse().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if v1 + 2 * v2 + 3 * v3 != 3 * 7 * 7 * 7 {
        writeln!(out, "No").unwrap();
        return;
    }

    let target_pair_sum = v2 + 3 * v3;
    let mut points = Vec::with_capacity(15 * 15 * 15);

    for x in -7..=7 {
        for y in -7..=7 {
            for z in -7..=7 {
                let overlap_origin =
                    overlap_len(0, x) * overlap_len(0, y) * overlap_len(0, z);
                points.push(Point {
                    x,
                    y,
                    z,
                    overlap_origin,
                });
            }
        }
    }

    for &p2 in &points {
        for &p3 in &points {
            let pair_sum =
                p2.overlap_origin + p3.overlap_origin + pair_overlap(p2, p3);

            if pair_sum != target_pair_sum {
                continue;
            }

            if triple_overlap(p2, p3) == v3 {
                writeln!(out, "Yes").unwrap();
                writeln!(
                    out,
                    "0 0 0 {} {} {} {} {} {}",
                    p2.x, p2.y, p2.z, p3.x, p3.y, p3.z
                )
                .unwrap();
                return;
            }
        }
    }

    writeln!(out, "No").unwrap();
}
