#[inline]
fn intersection(a: Pos, b: Pos) -> i32 {
    let x = (7 - (a.x - b.x).abs()).max(0);
    let y = (7 - (a.y - b.y).abs()).max(0);
    let z = (7 - (a.z - b.z).abs()).max(0);
    x * y * z
}

