    let c: Vec<u32> = (0..l)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();

    let mut sums = Vec::with_capacity(n * m * l);
    for &x in &a {
        for &y in &b {
            for &z in &c {
                sums.push(x + y + z);
            }
        }
    }
    sums.sort_unstable();
    sums.dedup();

    let q: usize = it.next().unwrap().parse().unwrap();
    let mut output = String::new();

