    let len = target.len();
    let inf = usize::MAX / 2;

    let mut dp = vec![inf; len + 1];
    dp[0] = 0;

    for _ in 0..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let mut strings = Vec::with_capacity(a);
        for _ in 0..a {
            strings.push(iter.next().unwrap().as_bytes().to_vec());
        }

        let mut next = dp.clone(); // Do nothing with this bag.
        for pos in 0..=len {
            if dp[pos] == inf {
                continue;
            }
            for s in &strings {
                let end = pos + s.len();
                if end <= len && target[pos..end] == s[..] {
                    next[end] = next[end].min(dp[pos] + 1);
                }
            }
        }
        dp = next;
    }

    let answer = if dp[len] == inf {
        -1
    } else {
        dp[len] as i32
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
