fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes().to_vec();
    let costs: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut answer = i64::MAX;

    for first in 0..=1u8 {
        let mut prefix_cost = vec![0i64; n + 1];
        let mut suffix_cost = vec![0i64; n + 1];

        for i in 0..n {
            let expected = first ^ ((i % 2) as u8);
            prefix_cost[i + 1] =
                prefix_cost[i] + if s[i] - b'0' != expected { costs[i] } else { 0 };
        }

        for i in (0..n).rev() {
            let expected = (first ^ ((i % 2) as u8)) ^ 1;
            suffix_cost[i] =
                suffix_cost[i + 1] + if s[i] - b'0' != expected { costs[i] } else { 0 };
        }

        for boundary in 1..n {
            answer = answer.min(prefix_cost[boundary] + suffix_cost[boundary]);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
