use std::io::{self, Read, Write};

const LINES: [u16; 8] = [
    0b000000111,
    0b000111000,
    0b111000000,
    0b001001001,
    0b010010010,
    0b100100100,
    0b100010001,
    0b001010100,
];

fn has_line(mask: u16) -> bool {
    LINES.iter().any(|&line| mask & line == line)
}

fn takahashi_wins(
    state: usize,
    red: u16,
    blue: u16,
    red_score: i64,
    blue_score: i64,
    values: &[i64; 9],
    powers: &[usize; 9],
    memo: &mut [i8],
) -> bool {
    if memo[state] != -1 {
        return memo[state] == 1;
    }

    let result = if has_line(red) {
        true
    } else if has_line(blue) {
        false
    } else {
        let occupied = red | blue;
        if occupied == 0x1FF {
            red_score > blue_score
        } else {
            let takahashi_turn = occupied.count_ones() % 2 == 0;

            if takahashi_turn {
                let mut can_win = false;
                for cell in 0..9 {
                    let bit = 1u16 << cell;
                    if occupied & bit == 0
                        && takahashi_wins(
                            state + powers[cell],
                            red | bit,
                            blue,
                            red_score + values[cell],
                            blue_score,
                            values,
                            powers,
                            memo,
                        )
                    {
                        can_win = true;
                        break;
                    }
                }
                can_win
            } else {
                let mut always_wins = true;
                for cell in 0..9 {
                    let bit = 1u16 << cell;
                    if occupied & bit == 0
                        && !takahashi_wins(
                            state + 2 * powers[cell],
                            red,
                            blue | bit,
                            red_score,
                            blue_score + values[cell],
                            values,
                            powers,
                            memo,
                        )
                    {
                        always_wins = false;
                        break;
                    }
                }
                always_wins
            }
        }
    };

    memo[state] = if result { 1 } else { 0 };
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let mut values = [0i64; 9];
    for value in &mut values {
        *value = iter.next().unwrap().parse().unwrap();
    }

    let mut powers = [1usize; 9];
    for i in 1..9 {
        powers[i] = powers[i - 1] * 3;
    }

    let mut memo = vec![-1i8; 3usize.pow(9)];
    let winner = if takahashi_wins(
        0,
        0,
        0,
        0,
        0,
        &values,
        &powers,
        &mut memo,
    ) {
        "Takahashi"
    } else {
        "Aoki"
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{winner}").unwrap();
}
