use std::collections::HashMap;
use std::io::{self, Read, Write};

fn expected_cost(
    n: u64,
    a: u64,
    x: f64,
    y: f64,
    memo: &mut HashMap<u64, f64>,
) -> f64 {
    if n == 0 {
        return 0.0;
    }
    if let Some(&value) = memo.get(&n) {
        return value;
    }

    let fixed_operation = x + expected_cost(n / a, a, x, y, memo);

    let mut dice_sum = 0.0;
    for b in 2..=6 {
        dice_sum += expected_cost(n / b, a, x, y, memo);
    }
    let dice_operation = (6.0 * y + dice_sum) / 5.0;

    let result = fixed_operation.min(dice_operation);
    memo.insert(n, result);
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

