use std::io::{self, Read, Write};

fn sum_absolute_differences(values: &mut Vec<i64>) -> i128 {
    values.sort_unstable();

    let mut prefix = 0i128;
    let mut sum = 0i128;

    for (i, &value) in values.iter().enumerate() {
        let value = value as i128;
        sum += value * i as i128 - prefix;
        prefix += value;
    }

    sum
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut u = [Vec::<i64>::new(), Vec::<i64>::new()];
    let mut v = [Vec::<i64>::new(), Vec::<i64>::new()];

    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        let parity = ((x + y) & 1) as usize;

        u[parity].push(x + y);
        v[parity].push(x - y);
    }

    let mut transformed_sum = 0i128;
    for parity in 0..2 {
        transformed_sum += sum_absolute_differences(&mut u[parity]);
        transformed_sum += sum_absolute_differences(&mut v[parity]);
    }

    let answer = transformed_sum / 2;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
