use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut position = vec![0usize; n];
    for index in 0..n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        position[value - 1] = index;
    }

    let mut min_deque: VecDeque<usize> = VecDeque::new();
    let mut max_deque: VecDeque<usize> = VecDeque::new();
    let mut answer = usize::MAX;

    for right in 0..n {
        while let Some(&idx) = min_deque.back() {
            if position[idx] >= position[right] {
                min_deque.pop_back();
            } else {
                break;
            }
        }
        min_deque.push_back(right);

        while let Some(&idx) = max_deque.back() {
            if position[idx] <= position[right] {
                max_deque.pop_back();
            } else {
                break;
            }
        }
        max_deque.push_back(right);

        if right + 1 >= k {
            let left = right + 1 - k;

            while min_deque.front().is_some_and(|&idx| idx < left) {
                min_deque.pop_front();
            }
            while max_deque.front().is_some_and(|&idx| idx < left) {
                max_deque.pop_front();
            }

            let min_position = position[*min_deque.front().unwrap()];
            let max_position = position[*max_deque.front().unwrap()];
            answer = answer.min(max_position - min_position);
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
