use std::collections::VecDeque;
use std::io::{self, BufRead, BufReader, BufWriter, Write};

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut input = BufReader::new(stdin.lock());
    let mut output = BufWriter::new(stdout.lock());

    let mut first_line = String::new();
    loop {
        first_line.clear();
        if input.read_line(&mut first_line).unwrap() == 0 {
            return;
        }
        if !first_line.trim().is_empty() {
            break;
        }
    }

    let values: Vec<usize> = first_line
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let n = values[0];
    let start = values[1];
    let goal = values[2] + 1;
    let size = 1usize << n;

    let mut parent = vec![usize::MAX; size + 1];
    let mut queue = VecDeque::new();

    parent[start] = start;
    queue.push_back(start);

    while let Some(x) = queue.pop_front() {
        if x == goal {
            break;
        }

        for i in 0..=n {
            let d = 1usize << i;
            if x % d != 0 {
                continue;
            }

            if x >= d {
                let next = x - d;
                if parent[next] == usize::MAX {
                    parent[next] = x;
                    queue.push_back(next);
                }
            }

            if x + d <= size {
                let next = x + d;
                if parent[next] == usize::MAX {
                    parent[next] = x;
                    queue.push_back(next);
                }
            }
        }
    }

    let mut path = Vec::new();
    let mut current = goal;
    while current != start {
        path.push(current);
        current = parent[current];
    }
    path.push(start);
    path.reverse();

    let mut answer = 0i32;
    let mut response = String::new();

    for edge in path.windows(2) {
        let from = edge[0];
        let to = edge[1];
        let low = from.min(to);
        let distance = from.abs_diff(to);
        let i = distance.trailing_zeros() as usize;
        let j = low / distance;

        writeln!(output, "? {} {}", i, j).unwrap();
        output.flush().unwrap();

        response.clear();
        if input.read_line(&mut response).unwrap() == 0 {
            return;
        }

        let t: i32 = response.trim().parse().unwrap();
        if t == -1 {
            return;
        }

        if from < to {
            answer += t;
        } else {
            answer -= t;
        }
        answer = answer.rem_euclid(100);
    }

    writeln!(output, "! {}", answer).unwrap();
    output.flush().unwrap();
}
