    let mut parent = vec![usize::MAX; size + 1];
    let mut queue = VecDeque::new();
    parent[start] = start;
    queue.push_back(start);

    while let Some(v) = queue.pop_front() {
        if v == goal {
            break;
        }

        for i in 0..=n {
            let len = 1usize << i;
            if v % len != 0 {
                continue;
            }

            if v + len <= size && parent[v + len] == usize::MAX {
                parent[v + len] = v;
                queue.push_back(v + len);
            }

            if v >= len && parent[v - len] == usize::MAX {
                parent[v - len] = v;
                queue.push_back(v - len);
            }
        }
    }

    let mut path = Vec::new();
    let mut current = goal;
    while current != start {
        path.push(current);
        current = parent[current];
    }
    path.push(start);
    path.reverse();

    let stdout = io::stdout();
    let mut output = BufWriter::new(stdout.lock());
    let mut answer = 0i32;

    for pair in path.windows(2) {
        let from = pair[0];
        let to = pair[1];
        let low = from.min(to);
        let len = from.abs_diff(to);
        let i = len.trailing_zeros() as usize;
        let j = low / len;

        writeln!(output, "? {} {}", i, j).unwrap();
        output.flush().unwrap();

        let mut response = String::new();
        input.read_line(&mut response).unwrap();
        let value: i32 = response.trim().parse().unwrap();

        if value == -1 {
            return;
        }

        if from < to {
            answer = (answer + value).rem_euclid(100);
        } else {
            answer = (answer - value).rem_euclid(100);
        }
    }

    writeln!(output, "! {}", answer).unwrap();
    output.flush().unwrap();
}
