            continue;
        }

        let half = 1u64 << bit;
        let cycle = half << 1;
        let full_cycles = count / cycle;
        let remainder = count % cycle;

        let ones = full_cycles * half + remainder.saturating_sub(half);
        answer = (answer + ones % MOD) % MOD;
    }

