use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut values = Vec::with_capacity(n);
    let mut max_value = 0usize;

    for _ in 0..n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        max_value = max_value.max(value);
        values.push(value);
    }

    let mut frequency = vec![0u64; max_value + 1];
    for value in values {
        frequency[value] += 1;
    }

    let mut prefix = vec![0u64; max_value + 1];
    for value in 1..=max_value {
        prefix[value] = prefix[value - 1] + frequency[value];
    }

    let mut answer = 0u64;

    for x in 1..=max_value {
        let fx = frequency[x];
        if fx == 0 {
            continue;
        }

        // Pairs of equal values have quotient 1.
        answer += fx * (fx - 1) / 2;

        let mut quotient = 1usize;
        while quotient * x <= max_value {
            let left = (quotient * x).max(x + 1);
            let right = max_value.min((quotient + 1) * x - 1);

            if left <= right {
                let count = prefix[right] - prefix[left - 1];
                answer += fx * count * quotient as u64;
            }

            quotient += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
