use std::io::{self, Read, Write};

fn main() {
    const MOD: u64 = 998_244_353;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    let state_count = 1usize << (k - 1);
    let state_mask = state_count - 1;

    let mut is_palindrome = vec![true; 1usize << k];
    for mask in 0..(1usize << k) {
        for i in 0..(k / 2) {
            if ((mask >> i) & 1) != ((mask >> (k - 1 - i)) & 1) {
                is_palindrome[mask] = false;
                break;
            }
        }
    }

    let mut dp = vec![0u64; state_count];
    dp[0] = 1;

    for (i, &ch) in s.iter().enumerate().take(n) {
        let mut next = vec![0u64; state_count];

        for state in 0..state_count {
            if dp[state] == 0 {
                continue;
            }

            for bit in 0..=1usize {
                if (ch == b'A' && bit != 0) || (ch == b'B' && bit != 1) {
                    continue;
                }

                let combined = (state << 1) | bit;
                if i + 1 >= k && is_palindrome[combined] {
                    continue;
                }

                let new_state = combined & state_mask;
                next[new_state] += dp[state];
                if next[new_state] >= MOD {
                    next[new_state] -= MOD;
                }
            }
        }

        dp = next;
    }

    let answer = dp.into_iter().fold(0u64, |sum, value| (sum + value) % MOD);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
