use std::collections::HashSet;
use std::io::{self, Read, Write};

fn integer_sqrt(n: u64) -> u64 {
    let mut r = (n as f64).sqrt() as u64;
    while (r as u128 + 1) * (r as u128 + 1) <= n as u128 {
        r += 1;
    }
    while (r as u128) * (r as u128) > n as u128 {
        r -= 1;
    }
    r
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u64 = input.trim().parse().unwrap();
    let limit = n as u128;

    // All squares, including 1.
    let square_count = integer_sqrt(n);

    // Store non-square perfect powers. Such a number has a representation
    // with an odd exponent at least 3.
    let mut powers = HashSet::with_capacity(1_100_000);
    let mut a = 2u64;

    let mut square_root = 2u64;
    let mut next_square = 4u64;

    while (a as u128) * (a as u128) * (a as u128) <= limit {
        // Odd powers of a square base are squares and are already counted.
        if a == next_square {
            square_root += 1;
            next_square = square_root * square_root;
            a += 1;
            continue;
        }

        let base = a as u128;
        let step = base * base;
        let mut value = step * base; // a^3

        while value <= limit {
            powers.insert(value as u64);
            if value > limit / step {
                break;
            }
            value *= step; // a^3, a^5, a^7, ...
        }

        a += 1;
    }

    let answer = square_count + powers.len() as u64;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
