use std::io::{self, Read, Write};

fn dfs(
    pos: usize,
    n: usize,
    k: usize,
    counts: &mut [usize],
    current: &mut [usize],
) -> u64 {
    if pos == n {
        return 1;
    }

    let mut total = 0u64;

    for ch in 0..counts.len() {
        if counts[ch] == 0 {
            continue;
        }

        current[pos] = ch;
        counts[ch] -= 1;

        let mut valid = true;
        if pos + 1 >= k {
            let start = pos + 1 - k;
            for offset in 0..(k / 2) {
                if current[start + offset] != current[pos - offset] {
                    valid = false;
                    break;
                }
            }
        }

        if valid {
            total += dfs(pos + 1, n, k, counts, current);
        }

        counts[ch] += 1;
    }

    total
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    let mut frequency = [0usize; 26];
    for &byte in s {
        frequency[(byte - b'a') as usize] += 1;
    }

    let mut counts: Vec<usize> = frequency.into_iter().filter(|&count| count > 0).collect();
    let mut current = vec![0usize; n];

    let answer = dfs(0, n, k, &mut counts, &mut current);

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
