use std::io::{self, Read, Write};

fn dfs(
    n: usize,
    k: usize,
    counts: &mut [usize; 26],
    current: &mut Vec<usize>,
) -> u64 {
    if current.len() == n {
        return 1;
    }

    let mut total = 0u64;

    for ch in 0..26 {
        if counts[ch] == 0 {
            continue;
        }

        counts[ch] -= 1;
        current.push(ch);

        let len = current.len();
        let mut valid = true;

        if len >= k {
            let start = len - k;
            for j in 0..(k / 2) {
                if current[start + j] != current[len - 1 - j] {
                    break;
                }
                if j + 1 == k / 2 {
                    valid = false;
                }
            }
        }

        if valid {
            total += dfs(n, k, counts, current);
        }

        current.pop();
        counts[ch] += 1;
    }

    total
}

