fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u128 = input.trim().parse().unwrap();

    let answer = if n == 1 {
        "0".to_string()
    } else {
        let mut rank = n - 1; // 1-based rank among positive palindromes
        let mut length = 1usize;
        let mut power10 = 1u128;

        loop {
            let half_length = (length + 1) / 2;
            if half_length > 1 && length % 2 == 1 {
                power10 *= 10;
            }

            let count = 9 * power10;
            if rank <= count {
                let prefix = power10 + rank - 1;
                let prefix_str = prefix.to_string();
                let mut result = prefix_str.clone();

                let mirrored_len = if length % 2 == 0 {
                    prefix_str.len()
                } else {
                    prefix_str.len() - 1
                };

                for byte in prefix_str.as_bytes()[..mirrored_len].iter().rev() {
                    result.push(*byte as char);
                }
                break result;
            }

            rank -= count;
            length += 1;
        }
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
