use std::collections::HashSet;
use std::io::{self, Read, Write};

fn reverse_number(mut n: u64) -> u64 {
    let mut reversed = 0;
    while n > 0 {
        reversed = reversed * 10 + n % 10;
        n /= 10;
    }
    reversed
}

fn has_no_zero(mut n: u64) -> bool {
    if n == 0 {
        return false;
    }
    while n > 0 {
        if n % 10 == 0 {
            return false;
        }
        n /= 10;
    }
    true
}

fn is_valid_center(n: u64) -> bool {
    has_no_zero(n) && n == reverse_number(n)
}

fn dfs(
    value: u64,
    candidates: &[(u64, u64)],
    failed: &mut HashSet<u64>,
    path: &mut Vec<u64>,
) -> Option<u64> {
    if is_valid_center(value) {
        return Some(value);
    }

    if failed.contains(&value) {
        return None;
    }

    for &(x, reversed) in candidates {
        if x > value || value % x != 0 {
            continue;
        }

        let remaining = value / x;
        if remaining % reversed != 0 {
            continue;
        }

        let next = remaining / reversed;
        if next >= value {
            continue;
        }

        path.push(x);
        if let Some(center) = dfs(next, candidates, failed, path) {
            return Some(center);
        }
        path.pop();
    }

    failed.insert(value);
    None
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u64 = input.trim().parse().unwrap();

    let mut remaining = n;
    let mut factors = Vec::new();

    let mut p = 2u64;
    while p * p <= remaining {
        if remaining % p == 0 {
            let mut exponent = 0;
            while remaining % p == 0 {
                remaining /= p;
                exponent += 1;
            }
            factors.push((p, exponent));
        }
        p = if p == 2 { 3 } else { p + 2 };
    }
    if remaining > 1 {
        factors.push((remaining, 1));
    }

    let mut divisors = vec![1u64];
    for &(prime, exponent) in &factors {
        let previous = divisors.clone();
        let mut power = 1u64;
        for _ in 0..exponent {
            power *= prime;
            for &d in &previous {
                divisors.push(d * power);
            }
        }
    }
    divisors.sort_unstable();

    let candidates: Vec<(u64, u64)> = divisors
        .into_iter()
        .filter(|&x| x >= 2 && has_no_zero(x))
        .map(|x| (x, reverse_number(x)))
        .collect();

    let mut failed = HashSet::new();
    let mut path = Vec::new();

    let answer = if let Some(center) = dfs(n, &candidates, &mut failed, &mut path) {
        let mut parts = Vec::with_capacity(path.len() * 2 + 1);

        for &x in &path {
            parts.push(x.to_string());
        }
        parts.push(center.to_string());
        for &x in path.iter().rev() {
            parts.push(reverse_number(x).to_string());
        }

        parts.join("*")
    } else {
        "-1".to_string()
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
