use std::collections::HashSet;
use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Candidate {
    product: u64,
    value: u64,
    reversed: u64,
}

fn reverse_without_zero(mut n: u64) -> Option<u64> {
    let mut reversed = 0u64;
    while n > 0 {
        let digit = n % 10;
        if digit == 0 {
            return None;
        }
        reversed = reversed * 10 + digit;
        n /= 10;
    }
    Some(reversed)
}

fn is_valid_center(n: u64) -> bool {
    reverse_without_zero(n) == Some(n)
}

fn search(
    remaining: u64,
    candidates: &[Candidate],
    failed: &mut HashSet<u64>,
    path: &mut Vec<Candidate>,
    center: &mut u64,
) -> bool {
    if is_valid_center(remaining) {
        *center = remaining;
        return true;
    }

    if failed.contains(&remaining) {
        return false;
    }

    for &candidate in candidates {
        if candidate.product > remaining {
            break;
        }
        if remaining % candidate.product != 0 {
            continue;
        }

        path.push(candidate);
        if search(
            remaining / candidate.product,
            candidates,
            failed,
            path,
            center,
        ) {
            return true;
        }
        path.pop();
    }

    failed.insert(remaining);
    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u64 = input.trim().parse().unwrap();

    let limit = n.min(999_999);
    let mut candidates = Vec::new();
    let mut seen_products = HashSet::new();

    for value in 2..=limit {
        let Some(reversed) = reverse_without_zero(value) else {
            continue;
        };

        let product = value * reversed;
        if product <= n && n % product == 0 && seen_products.insert(product) {
            candidates.push(Candidate {
                product,
                value,
                reversed,
            });
        }
    }

    candidates.sort_by_key(|candidate| candidate.product);

    let mut failed = HashSet::new();
    let mut path = Vec::new();
    let mut center = 0u64;

    let mut writer = io::BufWriter::new(io::stdout().lock());

    if !search(
        n,
        &candidates,
        &mut failed,
        &mut path,
        &mut center,
    ) {
        writeln!(writer, "-1").unwrap();
        return;
    }

    let mut answer = String::new();

    for candidate in &path {
        answer.push_str(&candidate.value.to_string());
        answer.push('*');
    }

    answer.push_str(&center.to_string());

    for candidate in path.iter().rev() {
        answer.push('*');
        answer.push_str(&candidate.reversed.to_string());
    }

    writeln!(writer, "{answer}").unwrap();
}
