use std::io::{self, Read, Write};

fn lower_bound(a: &[i64], x: i64) -> usize {
    let (mut left, mut right) = (0, a.len());
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn upper_bound(a: &[i64], x: i64) -> usize {
    let (mut left, mut right) = (0, a.len());
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] <= x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    for _ in 0..n {
        a.push(it.next().unwrap().parse::<i64>().unwrap());
    }
    a.sort_unstable();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let b: i64 = it.next().unwrap().parse().unwrap();
        let k: usize = it.next().unwrap().parse().unwrap();

        let mut low = -1_i64;
        let mut high = (a[0] - b).abs().max((a[n - 1] - b).abs());

        while high - low > 1 {
            let mid = low + (high - low) / 2;
            let left = lower_bound(&a, b - mid);
            let right = upper_bound(&a, b + mid);
            if right - left >= k {
                high = mid;
            } else {
                low = mid;
            }
        }

        writeln!(out, "{high}").unwrap();
    }
}
