use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let x: usize = it.next().unwrap().parse().unwrap();
    let y: usize = it.next().unwrap().parse().unwrap();

    let mut dishes = Vec::with_capacity(n);
    for _ in 0..n {
        let a: usize = it.next().unwrap().parse().unwrap();
        let b: usize = it.next().unwrap().parse().unwrap();
        dishes.push((a, b));
    }

    // Use the smaller limit as the indexed dimension.
    let (limit, other_limit, items): (usize, usize, Vec<(usize, usize)>) = if x <= y {
        (x, y, dishes)
    } else {
        (y, x, dishes.into_iter().map(|(a, b)| (b, a)).collect())
    };

    let width = limit + 1;
    let inf = usize::MAX / 4;
    // dp[k][s] = minimum sum in the other dimension when choosing k dishes
    // with indexed-dimension sum exactly s.
    let mut dp = vec![inf; (n + 1) * width];
    dp[0] = 0;

    for (i, &(weight, cost)) in items.iter().enumerate() {
        if weight > limit {
            continue;
        }

        for k in (1..=i + 1).rev() {
            let prev_base = (k - 1) * width;
            let cur_base = k * width;

            for s in 0..=limit - weight {
                let prev = dp[prev_base + s];
                if prev == inf || prev + cost > other_limit {
                    continue;
                }

                let idx = cur_base + s + weight;
                dp[idx] = dp[idx].min(prev + cost);
            }
        }
    }

    let mut feasible = 0;
    for k in 0..=n {
        let base = k * width;
        if dp[base..base + width]
            .iter()
            .any(|&cost| cost <= other_limit)
        {
            feasible = k;
        }
    }

    // One additional dish can be eaten even if it makes a limit exceed.
    let answer = n.min(feasible + 1);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
