        let aoki = match s[i] {
            b'R' => 0,
            b'P' => 1,
            b'S' => 2,
            _ => unreachable!(),
        };

        let mut next = [NEG; 3];
        for current in 0..3 {
            if current == (aoki + 2) % 3 {
                continue; // This move loses to Aoki.
            }

            let win = if current == (aoki + 1) % 3 { 1 } else { 0 };

            if i == 0 {
                next[current] = win;
            } else {
                for previous in 0..3 {
                    if previous != current {
                        next[current] = next[current].max(dp[previous] + win);
                    }
                }
            }
        }
        dp = next;
    }

    let answer = *dp.iter().max().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
