        let lz: usize = iter.next().unwrap().parse().unwrap();
        let rz: usize = iter.next().unwrap().parse().unwrap();

        let x0 = lx - 1;
        let y0 = ly - 1;
        let z0 = lz - 1;

        let answer = prefix[idx(rx, ry, rz)]
            - prefix[idx(x0, ry, rz)]
            - prefix[idx(rx, y0, rz)]
            - prefix[idx(rx, ry, z0)]
            + prefix[idx(x0, y0, rz)]
            + prefix[idx(x0, ry, z0)]
            + prefix[idx(rx, y0, z0)]
            - prefix[idx(x0, y0, z0)];

        writeln!(out, "{answer}").unwrap();
    }
