use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let mut matrix = vec![0u64; n];
    for _ in 0..m {
        let u: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        matrix[u] |= 1u64 << v;
        matrix[v] |= 1u64 << u;
    }

    // Reduce the adjacency matrix over GF(2) to reduced row echelon form.
    let mut rank = 0usize;
    let mut pivot_columns = Vec::new();

    for col in 0..n {
        let mut pivot = None;
        for row in rank..n {
            if ((matrix[row] >> col) & 1) != 0 {
                pivot = Some(row);
                break;
            }
        }

        if let Some(pivot_row) = pivot {
            matrix.swap(rank, pivot_row);

            for row in 0..n {
                if row != rank && ((matrix[row] >> col) & 1) != 0 {
                    matrix[row] ^= matrix[rank];
                }
            }

            pivot_columns.push(col);
            rank += 1;
        }
    }

    let mut is_pivot = vec![false; n];
    for &col in &pivot_columns {
        is_pivot[col] = true;
    }

    // Assign one bit to each standard nullspace basis vector.
    let mut values = vec![0u64; n];
    let mut basis_index = 0usize;

    for free_col in 0..n {
        if is_pivot[free_col] {
            continue;
        }

        let bit = 1u64 << basis_index;
        basis_index += 1;
        values[free_col] |= bit;

        for row in 0..rank {
            if ((matrix[row] >> free_col) & 1) != 0 {
                values[pivot_columns[row]] |= bit;
            }
        }
    }

    if values.iter().any(|&x| x == 0) {
        println!("No");
        return;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "Yes").unwrap();
    for i in 0..n {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", values[i]).unwrap();
    }
    writeln!(out).unwrap();
}
