        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut sequence = vec![0; n];
    let mut output = String::new();

    dfs(0, 0, n, k, &limits, &mut sequence, &mut output);

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
