use std::io::{self, Read, Write};
use std::time::{SystemTime, UNIX_EPOCH};

fn splitmix64(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E3779B97F4A7C15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
    z ^ (z >> 31)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    let mut b = Vec::with_capacity(n);

    for _ in 0..n {
        a.push(it.next().unwrap().parse::<usize>().unwrap());
    }
    for _ in 0..n {
        b.push(it.next().unwrap().parse::<usize>().unwrap());
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();

    let mut state1 = (now as u64) ^ 0x243F6A8885A308D3;
    let mut state2 = ((now >> 64) as u64)
        ^ state1.rotate_left(29)
        ^ 0x13198A2E03707344;

    let mut weight = vec![0u128; n + 1];
    for x in 1..=n {
        let low = splitmix64(&mut state1);
        let high = splitmix64(&mut state2);
        weight[x] = ((high as u128) << 64) | low as u128;
    }

    let mut prefix_a = vec![0u128; n + 1];
    let mut prefix_b = vec![0u128; n + 1];

    for i in 0..n {
        prefix_a[i + 1] = prefix_a[i].wrapping_add(weight[a[i]]);
        prefix_b[i + 1] = prefix_b[i].wrapping_add(weight[b[i]]);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let l: usize = it.next().unwrap().parse().unwrap();
        let r: usize = it.next().unwrap().parse().unwrap();
        let left_b: usize = it.next().unwrap().parse().unwrap();
        let right_b: usize = it.next().unwrap().parse().unwrap();

        let same_length = r - l == right_b - left_b;
        let hash_a = prefix_a[r].wrapping_sub(prefix_a[l - 1]);
        let hash_b = prefix_b[right_b].wrapping_sub(prefix_b[left_b - 1]);

        if same_length && hash_a == hash_b {
            writeln!(out, "Yes").unwrap();
        } else {
            writeln!(out, "No").unwrap();
        }
    }
