use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: usize) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn add_mod(a: i64, b: i64) -> i64 {
    let s = a + b;
    if s >= MOD { s - MOD } else { s }
}

fn sub_mod(a: i64, b: i64) -> i64 {
    let d = a - b;
    if d < 0 { d + MOD } else { d }
}

fn fwht_mod(a: &mut [i64]) {
    let n = a.len();
    let mut len = 1usize;
    while len < n {
        let step = len * 2;
        for base in (0..n).step_by(step) {
            for j in 0..len {
                let x = a[base + j];
                let y = a[base + j + len];
                a[base + j] = add_mod(x, y);
                a[base + j + len] = sub_mod(x, y);
            }
        }
        len *= 2;
    }
}

fn fwht_integer(a: &mut [i32]) {
    let n = a.len();
    let mut len = 1usize;
    while len < n {
        let step = len * 2;
        for base in (0..n).step_by(step) {
            for j in 0..len {
                let x = a[base + j];
                let y = a[base + j + len];
                a[base + j] = x + y;
                a[base + j + len] = x - y;
            }
        }
        len *= 2;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();

    let mut values = Vec::with_capacity(n);
    let mut max_value = 0usize;
    for _ in 0..n {
        let x: usize = it.next().unwrap().parse().unwrap();
        max_value = max_value.max(x);
        values.push(x);
    }

    // f[c] is the sum of signs over subsets whose sizes are multiples of M,
    // when exactly c elements have Walsh character -1.
    let mut inverses = vec![0i64; n + 1];
    if n >= 1 {
        inverses[1] = 1;
        for i in 2..=n {
            inverses[i] = MOD
                - (MOD / i as i64) * inverses[(MOD as usize) % i] % MOD;
        }
    }

    // Residue coefficients of (1+y)^N modulo y^M - 1.
    let mut current = vec![0i64; m];
    let mut combination = 1i64;
    for j in 0..=n {
        current[j % m] = add_mod(current[j % m], combination);
        if j < n {
            combination = combination * (n - j) as i64 % MOD;
            combination = combination * inverses[j + 1] % MOD;
        }
    }

    let mut f = vec![0i64; n + 1];
    f[0] = current[0];

    let mut next = vec![0i64; m];
    let mut d = vec![0i64; m];
    let inv_two = (MOD + 1) / 2;
    let inv_m = mod_pow(m as i64, (MOD - 2) as usize);
    let two_pow_n = mod_pow(2, n);

    for c in 1..=n {
        for r in 0..m {
            let prev_r = if r == 0 { m - 1 } else { r - 1 };
            d[r] = sub_mod(current[r], current[prev_r]);
        }

        let p0;
        if m % 2 == 1 {
            let mut constant = 0i64;
            for r in 1..m {
                constant = sub_mod(d[r], constant);
            }
            p0 = sub_mod(d[0], constant) * inv_two % MOD;
        } else {
            let mut constant = 0i64;
            let mut alternating_sum = 0i64;
            for r in 1..m {
                constant = sub_mod(d[r], constant);
                if r % 2 == 0 {
                    alternating_sum = add_mod(alternating_sum, constant);
                } else {
                    alternating_sum = sub_mod(alternating_sum, constant);
                }
            }

            let target = if c == n { two_pow_n } else { 0 };
            p0 = sub_mod(target, alternating_sum) * inv_m % MOD;
        }

        next[0] = p0;
        for r in 1..m {
            next[r] = sub_mod(d[r], next[r - 1]);
        }

        std::mem::swap(&mut current, &mut next);
        f[c] = current[0];
    }

    let mut xor_size = 1usize;
    while xor_size <= max_value {
        xor_size <<= 1;
    }

    let mut frequency = vec![0i32; xor_size];
    for x in values {
        frequency[x] += 1;
    }
    fwht_integer(&mut frequency);

    let mut power_transform = vec![0i64; xor_size];
    for x in 0..xor_size {
        power_transform[x] = mod_pow(x as i64, k);
    }
    fwht_mod(&mut power_transform);

    let mut answer = 0i64;
    for s in 0..xor_size {
        let walsh_sum = frequency[s] as i64;
        let negative_count = ((n as i64 - walsh_sum) / 2) as usize;
        answer = (answer + f[negative_count] * power_transform[s]) % MOD;
    }

    answer = answer * mod_pow(xor_size as i64, (MOD - 2) as usize) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
