use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::new(); n];
    let mut degree = vec![0usize; n];

    for _ in 0..n - 1 {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[a].push(b);
        graph[b].push(a);
        degree[a] += 1;
        degree[b] += 1;
    }

    let mut required = vec![false; n];
    for _ in 0..k {
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        required[v] = true;
    }

    let mut queue = VecDeque::new();
    for v in 0..n {
        if !required[v] && degree[v] <= 1 {
            queue.push_back(v);
        }
    }

    let mut removed = vec![false; n];
    let mut remaining = n;

    while let Some(v) = queue.pop_front() {
        if removed[v] || required[v] || degree[v] > 1 {
            continue;
        }

        removed[v] = true;
        remaining -= 1;

        for &to in &graph[v] {
            if !removed[to] {
                degree[to] -= 1;
                if !required[to] && degree[to] <= 1 {
                    queue.push_back(to);
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{remaining}").unwrap();
}
