    let x1: i64 = it.next().unwrap().parse().unwrap();

    let mut a = vec![0usize; m];
    let mut b = vec![0usize; m];
    let mut s = vec![0i64; m];
    let mut t = vec![0i64; m];
    let mut events = Vec::with_capacity(2 * m);

    for i in 0..m {
        a[i] = it.next().unwrap().parse::<usize>().unwrap() - 1;
        b[i] = it.next().unwrap().parse::<usize>().unwrap() - 1;
        s[i] = it.next().unwrap().parse().unwrap();
        t[i] = it.next().unwrap().parse().unwrap();

        // Arrival events must be processed before departure events
        // when their times are equal.
        events.push((s[i], 1u8, i));
        events.push((t[i], 0u8, i));
    }

    events.sort_unstable();

    let mut delays = vec![0i64; m];
    delays[0] = x1;

    // best[city] is the maximum delayed arrival time among trains
    // that have already arrived at this city.
    let mut best = vec![0i64; n];

    for (_, kind, i) in events {
        if kind == 0 {
            best[b[i]] = best[b[i]].max(t[i] + delays[i]);
        } else if i != 0 {
            delays[i] = (best[a[i]] - s[i]).max(0);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 1..m {
        if i > 1 {
            write!(out, " ").unwrap();
