    let mut nim_sum = 0usize;
    for mut value in values {
        let mut prime_factor_count = 0usize;
        while value > 1 {
            value /= spf[value];
            prime_factor_count += 1;
        }
        nim_sum ^= prime_factor_count;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
