use std::io::{self, Read, Write};

const LIMIT: u64 = 1_000_000_000_000_000_001;

#[derive(Clone, Copy, PartialEq, Eq)]
struct Piece {
    start: u64,
    p: u64,
    c: u64,
}

type Func = Vec<Piece>;

fn sat_add(a: u64, b: u64) -> u64 {
    let v = a as u128 + b as u128;
    if v >= LIMIT as u128 {
        LIMIT
    } else {
        v as u64
    }
}

fn sat_mul(a: u64, b: u64) -> u64 {
    let v = a as u128 * b as u128;
    if v >= LIMIT as u128 {
        LIMIT
    } else {
        v as u64
    }
}

fn eval_piece(piece: Piece, x: u64) -> u64 {
    sat_add(sat_mul(piece.p, x), piece.c)
}

fn push_piece(func: &mut Func, start: u64, p: u64, c: u64) {
    let piece = Piece { start, p, c };
    if let Some(last) = func.last() {
        if last.p == p && last.c == c {
            return;
        }
    }
    func.push(piece);
}

fn append_interval(func: &mut Func, start: u64, end: u64, p: u64, c: u64) {
    if start > end {
        return;
    }

    if c >= LIMIT {
        push_piece(func, start, 0, LIMIT);
        return;
    }

    if p == 0 {
        push_piece(func, start, 0, c);
        return;
    }

    let remaining = LIMIT - c;
    let saturation_start =
        ((remaining as u128 + p as u128 - 1) / p as u128) as u64;

    if saturation_start <= start {
        push_piece(func, start, 0, LIMIT);
    } else if saturation_start <= end {
        push_piece(func, start, p, c);
        push_piece(func, saturation_start, 0, LIMIT);
    } else {
        push_piece(func, start, p, c);
    }
}

fn identity() -> Func {
    vec![Piece {
        start: 0,
        p: 1,
        c: 0,
    }]
}

fn make_operation(a: u64, b: u64) -> Func {
    let mut result = Vec::new();

    if b == 1 {
        append_interval(&mut result, 0, LIMIT, 1, a);
        return result;
    }

    let denominator = b - 1;
    let threshold =
        ((a as u128 + denominator as u128 - 1) / denominator as u128) as u64;

    if threshold > 0 {
        append_interval(
            &mut result,
            0,
            threshold.saturating_sub(1).min(LIMIT),
            1,
            a,
        );
    }
    if threshold <= LIMIT {
        append_interval(&mut result, threshold, LIMIT, b, 0);
    }

    result
}

// Returns second(first(x)).
fn compose(first: &Func, second: &Func) -> Func {
    let mut result = Vec::new();
    let mut i = 0usize;
    let mut j = 0usize;
    let mut x = 0u64;

    loop {
        while i + 1 < first.len() && first[i + 1].start <= x {
            i += 1;
        }

        let fp = first[i];
        let y = eval_piece(fp, x);

        while j + 1 < second.len() && second[j + 1].start <= y {
            j += 1;
        }

        let gp = second[j];

        let end_first = if i + 1 < first.len() {
            first[i + 1].start - 1
        } else {
            LIMIT
        };

        let end_second = if j + 1 >= second.len() {
            LIMIT
        } else {
            let next_y = second[j + 1].start;
            if fp.p == 0 {
                LIMIT
            } else if fp.c >= next_y {
                x
            } else {
                ((next_y - 1 - fp.c) / fp.p).min(LIMIT)
            }
        };

        let end = end_first.min(end_second).max(x);
        let new_p = sat_mul(gp.p, fp.p);
        let new_c = sat_add(sat_mul(gp.p, fp.c), gp.c);
        append_interval(&mut result, x, end, new_p, new_c);

        if end == LIMIT {
            break;
        }
        x = end + 1;
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a = vec![0u64; n];
    let mut b = vec![0u64; n];

    for value in &mut a {
        *value = it.next().unwrap().parse().unwrap();
    }
    for value in &mut b {
        *value = it.next().unwrap().parse().unwrap();
    }

    let mut size = 1usize;
    while size < n {
        size <<= 1;
    }

    let mut seg: Vec<Func> = (0..2 * size).map(|_| identity()).collect();

    for i in 0..n {
        seg[size + i] = make_operation(a[i], b[i]);
    }

    for i in (1..size).rev() {
        seg[i] = compose(&seg[i << 1], &seg[i << 1 | 1]);
    }

    let q: usize = it.next().unwrap().parse().unwrap();
    let mut output = io::BufWriter::new(io::stdout().lock());

    for _ in 0..q {
        let query_type: u32 = it.next().unwrap().parse().unwrap();
        let x: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let y: u64 = it.next().unwrap().parse().unwrap();

        match query_type {
            1 => {
                a[x] = y;
                let mut pos = size + x;
                seg[pos] = make_operation(a[x], b[x]);
                pos >>= 1;
                while pos > 0 {
                    seg[pos] = compose(&seg[pos << 1], &seg[pos << 1 | 1]);
                    pos >>= 1;
                }
            }
            2 => {
                b[x] = y;
                let mut pos = size + x;
                seg[pos] = make_operation(a[x], b[x]);
                pos >>= 1;
                while pos > 0 {
                    seg[pos] = compose(&seg[pos << 1], &seg[pos << 1 | 1]);
                    pos >>= 1;
                }
            }
            3 => {
                let mut left = x + size;
                let mut right = y as usize + size;
                let mut left_func = identity();
                let mut right_func = identity();

                while left < right {
                    if left & 1 == 1 {
                        left_func = compose(&left_func, &seg[left]);
                        left += 1;
                    }
                    if right & 1 == 1 {
                        right -= 1;
                        right_func = compose(&seg[right], &right_func);
                    }
                    left >>= 1;
                    right >>= 1;
                }

                let total = compose(&left_func, &right_func);
                let answer = eval_piece(total[0], 0);
                writeln!(output, "{answer}").unwrap();
            }
            _ => unreachable!(),
        }
    }
}
