use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::<(usize, i64)>::new(); n];

    for _ in 0..n - 1 {
        let u: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let len: i64 = it.next().unwrap().parse().unwrap();
        graph[u].push((v, len));
        graph[v].push((u, len));
    }

    let mut parent = vec![usize::MAX; n];
    let mut parent_edge = vec![0_i64; n];
    let mut child_count = vec![0_usize; n];
    let mut order = Vec::with_capacity(n);

    parent[0] = 0;
    order.push(0);

    let mut pos = 0;
    while pos < order.len() {
        let v = order[pos];
        pos += 1;

        for &(to, len) in &graph[v] {
            if to == parent[v] {
                continue;
            }
            parent[to] = v;
            parent_edge[to] = len;
            child_count[v] += 1;
            order.push(to);
        }
    }

    // Each rooted leaf represents one marginal gain.
    let mut gain = vec![0_i64; n];
    let mut representative = vec![usize::MAX; n];

    for &v in order.iter().rev() {
        if child_count[v] == 0 {
            representative[v] = v;
        }

        if v != 0 {
            let leaf = representative[v];
            gain[leaf] += parent_edge[v];

            let p = parent[v];
            if representative[p] == usize::MAX
                || gain[leaf] > gain[representative[p]]
            {
                representative[p] = leaf;
            }
        }
    }

    let mut marginals = Vec::new();
    for v in 0..n {
        if child_count[v] == 0 {
            marginals.push(gain[v]);
        }
    }
    marginals.sort_unstable_by(|a, b| b.cmp(a));

    let mut out = io::BufWriter::new(io::stdout().lock());
    let mut total = 0_i64;

    for k in 1..=n {
        if k <= marginals.len() {
            total += marginals[k - 1];
        }
        writeln!(out, "{}", total * 2).unwrap();
    }
}
