    // Changes that make the string larger are performed from right to left.
    for i in (0..current.len()).rev() {
        if current[i] < t[i] {
            order.push(i);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "{}", order.len()).unwrap();
    for i in order {
        current[i] = t[i];
        writeln!(out, "{}", std::str::from_utf8(&current).unwrap()).unwrap();
    }
