    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: i64 = iter.next().unwrap().parse().unwrap();

    let mut prefix = 0_i64;
    let mut total = 1_i64; // Sum of dp[0..i), initially dp[0] = 1.
    let mut sums: HashMap<i64, i64> = HashMap::new();
    sums.insert(0, 1);

    let mut answer = 1_i64;

    for _ in 0..n {
        let a: i64 = iter.next().unwrap().parse().unwrap();
        prefix += a;

        let forbidden = sums.get(&(prefix - k)).copied().unwrap_or(0);
        answer = (total - forbidden + MOD) % MOD;

        let entry = sums.entry(prefix).or_insert(0);
        *entry = (*entry + answer) % MOD;
        total = (total + answer) % MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
