        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut prefix = vec![0_i64; n + 1];
    for i in 0..n {
        let population: i64 = iter.next().unwrap().parse().unwrap();
        prefix[i + 1] = prefix[i] + population;
