        while let Some(&j) = stack.last() {
            if heights[j] < heights[i] {
                stack.pop();
            } else {
                break;
            }
        }

        record_counts[i] = match stack.last() {
            Some(&j) => 1 + record_counts[j],
            None => 1,
        };

        stack.push(i);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 0..n {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        let answer = if i + 1 < n {
            record_counts[i + 1]
        } else {
            0
        };
        write!(out, "{}", answer).unwrap();
    }
    writeln!(out).unwrap();
