```rust
use std::cmp::Ordering;
use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Point {
    x: i64,
    y: i64,
}

#[derive(Clone, Copy)]
struct Item {
    kind: u8, // 0: P, 1: Q
    index: usize,
    dx: i64,
    dy: i64,
}

fn cross(ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    ax * by - ay * bx
}

fn half(dx: i64, dy: i64) -> u8 {
    if dy > 0 || (dy == 0 && dx > 0) {
        0
    } else {
        1
    }
}

fn solve(
    ps: Vec<usize>,
    qs: Vec<usize>,
    p_points: &[Point],
    q_points: &[Point],
    answer: &mut [usize],
) -> bool {
    let k = ps.len();
    if k == 0 {
        return true;
    }
    if k == 1 {
        answer[ps[0]] = qs[0];
        return true;
    }

    let mut selected: Option<(usize, usize)> = None;

    for &pi in &ps {
        let origin = p_points[pi];
        let mut items = Vec::with_capacity(2 * k - 1);

        for &pj in &ps {
            if pj != pi {
                items.push(Item {
                    kind: 0,
                    index: pj,
                    dx: p_points[pj].x - origin.x,
                    dy: p_points[pj].y - origin.y,
                });
            }
        }
        for &qj in &qs {
            items.push(Item {
                kind: 1,
                index: qj,
                dx: q_points[qj].x - origin.x,
                dy: q_points[qj].y - origin.y,
            });
        }

        items.sort_unstable_by(|a, b| {
            let ha = half(a.dx, a.dy);
            let hb = half(b.dx, b.dy);
            if ha != hb {
                return ha.cmp(&hb);
            }
            let cr = cross(a.dx, a.dy, b.dx, b.dy);
            if cr > 0 {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        });

        let m = items.len();
        let mut prefix_p = vec![0usize; 2 * m + 1];
        for t in 0..2 * m {
            prefix_p[t + 1] = prefix_p[t] + usize::from(items[t % m].kind == 0);
        }

        let mut j = 1usize;
        for i in 0..m {
            if j < i + 1 {
                j = i + 1;
            }
            while j < i + m
                && cross(
                    items[i].dx,
                    items[i].dy,
                    items[j % m].dx,
                    items[j % m].dy,
                ) > 0
            {
                j += 1;
            }

            if items[i].kind == 1 {
                let left_p = prefix_p[j] - prefix_p[i + 1];
                let left_total = j - (i + 1);
                let left_q = left_total - left_p;
                if left_p == left_q {
                    selected = Some((pi, items[i].index));
                    break;
                }
            }
        }

        if selected.is_some() {
            break;
        }
    }

    let (pi, qi) = match selected {
        Some(pair) => pair,
        None => return false,
    };

    answer[pi] = qi;

    let base = p_points[pi];
    let vx = q_points[qi].x - base.x;
    let vy = q_points[qi].y - base.y;

    let mut left_p = Vec::new();
    let mut right_p = Vec::new();
    let mut left_q = Vec::new();
    let mut right_q = Vec::new();

    for &pj in &ps {
        if pj == pi {
            continue;
        }
        let wx = p_points[pj].x - base.x;
        let wy = p_points[pj].y - base.y;
        if cross(vx, vy, wx, wy) > 0 {
            left_p.push(pj);
        } else {
            right_p.push(pj);
        }
    }

    for &qj in &qs {
        if qj == qi {
            continue;
        }
        let wx = q_points[qj].x - base.x;
        let wy = q_points[qj].y - base.y;
        if cross(vx, vy, wx, wy) > 0 {
            left_q.push(qj);
        } else {
            right_q.push(qj);
        }
    }

    if left_p.len() != left_q.len() || right_p.len() != right_q.len() {
        return false;
    }

    solve(left_p, left_q, p_points, q_points, answer)
        && solve(right_p, right_q, p_points, q_points, answer)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut p_points = Vec::with_capacity(n);
    let mut q_points = Vec::with_capacity(n);

    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        p_points.push(Point { x, y });
    }
    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        q_points.push(Point { x, y });
    }

    let ps: Vec<usize> = (0..n).collect();
    let qs: Vec<usize> = (0..n).collect();
    let mut answer = vec![0usize; n];

    let possible = solve(ps, qs, &p_points, &q_points, &mut answer);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if !possible {
        writeln!(out, "-1").unwrap();
    } else {
        for (i, &q) in answer.iter().enumerate() {
            if i > 0 {
                write!(out, " ").unwrap();
            }
            write!(out, "{}", q + 1).unwrap();
        }
        writeln!(out).unwrap();
    }
}
