use std::cmp::Ordering;
use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Point {
    x: i64,
    y: i64,
    is_p: bool,
    index: usize,
}

fn construct(ids: Vec<usize>, points: &[Point], answer: &mut [usize]) -> bool {
    if ids.is_empty() {
        return true;
    }

    let mut pivot = ids[0];
    for &id in &ids[1..] {
        if (points[id].x, points[id].y) < (points[pivot].x, points[pivot].y) {
            pivot = id;
        }
    }

    let px = points[pivot].x;
    let py = points[pivot].y;

    let mut others: Vec<usize> = ids.into_iter().filter(|&id| id != pivot).collect();
    others.sort_unstable_by(|&u, &v| {
        if u == v {
            return Ordering::Equal;
        }
        let ux = points[u].x - px;
        let uy = points[u].y - py;
        let vx = points[v].x - px;
        let vy = points[v].y - py;
        let cross = ux * vy - uy * vx;
        if cross > 0 {
            Ordering::Less
        } else {
            Ordering::Greater
        }
    });

    let pivot_color = points[pivot].is_p;
    let mut balance = 0i32;
    let mut partner_pos = None;

    for (pos, &id) in others.iter().enumerate() {
        if points[id].is_p == pivot_color {
            balance += 1;
        } else {
            if balance == 0 {
                partner_pos = Some(pos);
                break;
            }
            balance -= 1;
        }
    }

    let Some(pos) = partner_pos else {
        return false;
    };
    let partner = others[pos];

    if points[pivot].is_p {
        answer[points[pivot].index] = points[partner].index;
    } else {
        answer[points[partner].index] = points[pivot].index;
    }

    let left = others[..pos].to_vec();
    let right = others[pos + 1..].to_vec();

    construct(left, points, answer) && construct(right, points, answer)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut points = Vec::with_capacity(2 * n);

    for i in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        points.push(Point {
            x,
            y,
            is_p: true,
            index: i,
        });
    }

    for i in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        points.push(Point {
            x,
            y,
            is_p: false,
            index: i,
        });
    }

    let ids: Vec<usize> = (0..2 * n).collect();
    let mut answer = vec![0usize; n];

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if !construct(ids, &points, &mut answer) {
        writeln!(out, "-1").unwrap();
        return;
    }

    for (i, &value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", value + 1).unwrap();
    }
    writeln!(out).unwrap();
}
