use std::io::{self, Read, Write};

fn distance(a: (f64, f64), b: (f64, f64)) -> f64 {
    (a.0 - b.0).hypot(a.1 - b.1)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let s: f64 = iter.next().unwrap().parse().unwrap();
    let t: f64 = iter.next().unwrap().parse().unwrap();

    let mut segments = vec![[(0.0, 0.0); 2]; n];
    let mut drawing_time = 0.0;

    for i in 0..n {
        let a: f64 = iter.next().unwrap().parse().unwrap();
        let b: f64 = iter.next().unwrap().parse().unwrap();
        let c: f64 = iter.next().unwrap().parse().unwrap();
        let d: f64 = iter.next().unwrap().parse().unwrap();

        segments[i][0] = (a, b);
        segments[i][1] = (c, d);
        drawing_time += distance(segments[i][0], segments[i][1]) / t;
    }

    let states = 1usize << n;
    let inf = f64::INFINITY;
    let mut dp = vec![inf; states * n * 2];

    let index = |mask: usize, line: usize, start: usize| -> usize {
        (mask * n + line) * 2 + start
    };

    let origin = (0.0, 0.0);

    for i in 0..n {
        for start in 0..2 {
            dp[index(1 << i, i, start)] = distance(origin, segments[i][start]) / s;
        }
    }

    for mask in 1..states {
        for last in 0..n {
            if mask & (1 << last) == 0 {
                continue;
            }

            for last_start in 0..2 {
                let current = dp[index(mask, last, last_start)];
                if !current.is_finite() {
                    continue;
                }

                let current_position = segments[last][1 - last_start];

                for next in 0..n {
                    if mask & (1 << next) != 0 {
                        continue;
                    }

                    let next_mask = mask | (1 << next);
                    for next_start in 0..2 {
                        let movement =
                            distance(current_position, segments[next][next_start]) / s;
                        let next_index = index(next_mask, next, next_start);
                        dp[next_index] = dp[next_index].min(current + movement);
                    }
                }
            }
        }
    }

    let full_mask = states - 1;
    let mut movement_time = inf;

    for last in 0..n {
        for start in 0..2 {
            movement_time = movement_time.min(dp[index(full_mask, last, start)]);
        }
    }

    let answer = drawing_time + movement_time;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.20}", answer).unwrap();
}
