use std::io::{self, Read, Write};

fn min_cost(w: i64, a: i64, p: i64, b: i64, q: i64) -> i64 {
    let mut best = i64::MAX;

    for s in 0..=b {
        let remaining = (w - s * a).max(0);
        let t = (remaining + b - 1) / b;
        best = best.min(s * p + t * q);
    }

    for t in 0..=a {
        let remaining = (w - t * b).max(0);
        let s = (remaining + a - 1) / a;
        best = best.min(s * p + t * q);
    }

    best
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let x: i64 = it.next().unwrap().parse().unwrap();

    let mut processes = Vec::with_capacity(n);
    for _ in 0..n {
        let a: i64 = it.next().unwrap().parse().unwrap();
        let p: i64 = it.next().unwrap().parse().unwrap();
        let b: i64 = it.next().unwrap().parse().unwrap();
        let q: i64 = it.next().unwrap().parse().unwrap();
        processes.push((a, p, b, q));
    }

    let feasible = |capacity: i64| -> bool {
        let mut total = 0_i64;
        for &(a, p, b, q) in &processes {
            total += min_cost(capacity, a, p, b, q);
            if total > x {
                return false;
            }
        }
        true
    };

    let mut low = 0_i64;
    let mut high = 1_000_000_001_i64;

    while high - low > 1 {
        let mid = low + (high - low) / 2;
        if feasible(mid) {
            low = mid;
        } else {
            high = mid;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
}
