use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let x: i64 = iter.next().unwrap().parse().unwrap();

    let mut t = vec![0_i64; n];
    for value in &mut t {
        *value = iter.next().unwrap().parse().unwrap();
    }

    let mut prefix_sum = vec![0_i64; n + 1];
    for i in 0..n {
        prefix_sum[i + 1] = prefix_sum[i] + t[i];
    }

    // Every date in an earliest optimal schedule has the form T_i + qX.
    let mut dates = Vec::with_capacity(n * (n + 1));
    for &time in &t {
        for q in 0..=n {
            dates.push(time + q as i64 * x);
        }
    }
    dates.sort_unstable();
    dates.dedup();

    let m = dates.len();
    let mut previous_index = vec![None; m];
    let mut p = 0usize;
    for c in 0..m {
        let limit = dates[c] - x;
        while p < m && dates[p] <= limit {
            p += 1;
        }
        if p > 0 {
            previous_index[c] = Some(p - 1);
        }
    }

    const INF: i64 = i64::MAX / 4;

    // best_prefix[i][c] is the minimum cost for shipping the first i orders,
    // with the last shipment date at most dates[c].
    let mut best_prefix: Vec<Vec<i64>> = Vec::with_capacity(n + 1);
    best_prefix.push(vec![0; m]);

    for i in 1..=n {
        let mut exact = vec![INF; m];
        let first_j = i.saturating_sub(k);

        let mut start_date_index = 0usize;
        while start_date_index < m && dates[start_date_index] < t[i - 1] {
            start_date_index += 1;
        }

        for j in first_j..i {
            let batch_size = (i - j) as i64;
            let release_sum = prefix_sum[i] - prefix_sum[j];

            for c in start_date_index..m {
                let previous_cost = if j == 0 {
                    0
                } else if let Some(pc) = previous_index[c] {
                    best_prefix[j][pc]
                } else {
                    continue;
                };

                if previous_cost == INF {
                    continue;
                }

                let cost =
                    previous_cost + batch_size * dates[c] - release_sum;
                if cost < exact[c] {
                    exact[c] = cost;
                }
            }
        }

        for c in 1..m {
            if exact[c - 1] < exact[c] {
                exact[c] = exact[c - 1];
            }
        }
        best_prefix.push(exact);
    }

    let answer = best_prefix[n][m - 1];
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
