use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut people = Vec::with_capacity(n);
    let mut total = 0usize;

    for _ in 0..n {
        let team: usize = iter.next().unwrap().parse().unwrap();
        let strength: usize = iter.next().unwrap().parse().unwrap();
        people.push((team, strength));
        total += strength;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if total % 3 != 0 {
        writeln!(out, "-1").unwrap();
        return;
    }

    let target = total / 3;
    let width = target + 1;
    let size = width * width;
    const INF: u8 = u8::MAX;

    // dp[s1][s2] is the minimum number of switches after assigning
    // processed people, where teams 1 and 2 have strengths s1 and s2.
    let mut dp = vec![INF; size];
    dp[0] = 0;

    for (original_team, strength) in people {
        let mut next = vec![INF; size];

        for s1 in 0..=target {
            let row = s1 * width;
            for s2 in 0..=target {
                let idx = row + s2;
                let current = dp[idx];
                if current == INF {
                    continue;
                }

                // Assign to team 1.
                if s1 + strength <= target {
                    let next_idx = idx + strength * width;
                    let cost = current + if original_team == 1 { 0 } else { 1 };
                    if cost < next[next_idx] {
                        next[next_idx] = cost;
                    }
                }

                // Assign to team 2.
                if s2 + strength <= target {
                    let next_idx = idx + strength;
                    let cost = current + if original_team == 2 { 0 } else { 1 };
                    if cost < next[next_idx] {
                        next[next_idx] = cost;
                    }
                }

                // Assign to team 3.
                let cost = current + if original_team == 3 { 0 } else { 1 };
                if cost < next[idx] {
                    next[idx] = cost;
                }
            }
        }

        dp = next;
    }

    let answer = dp[target * width + target];
    if answer == INF {
        writeln!(out, "-1").unwrap();
    } else {
        writeln!(out, "{}", answer).unwrap();
    }
}
