use std::fmt::Write as FmtWrite;
use std::io::{self, Read, Write};

enum Query {
    Close(usize),
    Ask(usize, usize),
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut roads = Vec::with_capacity(m);
    for _ in 0..m {
        let a: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: i64 = it.next().unwrap().parse().unwrap();
        roads.push((a, b, c));
    }

    let mut queries = Vec::with_capacity(q);
    let mut eventually_closed = vec![false; m];

    for _ in 0..q {
        let kind: u8 = it.next().unwrap().parse().unwrap();
        if kind == 1 {
            let edge: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
            eventually_closed[edge] = true;
            queries.push(Query::Close(edge));
        } else {
            let x: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
            let y: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
            queries.push(Query::Ask(x, y));
        }
    }

    const INF: i64 = i64::MAX / 4;
    let mut dist = vec![INF; n * n];

    for i in 0..n {
        dist[i * n + i] = 0;
    }

    for (idx, &(a, b, c)) in roads.iter().enumerate() {
        if !eventually_closed[idx] {
            dist[a * n + b] = c;
            dist[b * n + a] = c;
        }
    }

    // All-pairs shortest paths after every requested closure has occurred.
    for k in 0..n {
        for i in 0..n {
            let dik = dist[i * n + k];
            if dik == INF {
                continue;
            }
            for j in 0..n {
                let dkj = dist[k * n + j];
                if dkj == INF {
                    continue;
                }
                let candidate = dik + dkj;
                let idx = i * n + j;
                if candidate < dist[idx] {
                    dist[idx] = candidate;
                }
            }
        }
    }

    let mut answers = Vec::new();

    // Process backwards: each closure becomes an edge insertion.
    for query in queries.iter().rev() {
        match *query {
            Query::Ask(x, y) => {
                let d = dist[x * n + y];
                answers.push(if d == INF { -1 } else { d });
            }
            Query::Close(edge) => {
                let (a, b, c) = roads[edge];

                // Snapshot distances before inserting this edge.
                let mut to_a = vec![INF; n];
                let mut to_b = vec![INF; n];
                for i in 0..n {
                    to_a[i] = dist[i * n + a];
                    to_b[i] = dist[i * n + b];
                }

                for i in 0..n {
                    for j in 0..n {
                        let idx = i * n + j;
                        let mut best = dist[idx];

                        if to_a[i] != INF && to_b[j] != INF {
                            best = best.min(to_a[i] + c + to_b[j]);
                        }
                        if to_b[i] != INF && to_a[j] != INF {
                            best = best.min(to_b[i] + c + to_a[j]);
                        }

                        dist[idx] = best;
                    }
                }
            }
        }
    }

    let mut output = String::new();
    for answer in answers.iter().rev() {
        writeln!(output, "{answer}").unwrap();
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
