use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

#[derive(Clone, Copy, Eq, PartialEq)]
struct Entry {
    weight: u64,
    size: u64,
    id: usize,
    version: usize,
}

impl Ord for Entry {
    fn cmp(&self, other: &Self) -> Ordering {
        let lhs = self.weight as u128 * other.size as u128;
        let rhs = other.weight as u128 * self.size as u128;
        lhs.cmp(&rhs)
            .then_with(|| self.id.cmp(&other.id))
            .then_with(|| self.version.cmp(&other.version))
    }
}

impl PartialOrd for Entry {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn find(x: usize, dsu: &mut [usize]) -> usize {
    let mut root = x;
    while dsu[root] != root {
        root = dsu[root];
    }

    let mut cur = x;
    while dsu[cur] != cur {
        let next = dsu[cur];
        dsu[cur] = root;
        cur = next;
    }
    root
}

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let t: usize = it.next().unwrap().parse().unwrap();
    let mut output = String::new();

    for _ in 0..t {
        let n: usize = it.next().unwrap().parse().unwrap();

        let mut parent = vec![0usize; n + 1];
        for i in 1..=n {
            parent[i] = it.next().unwrap().parse().unwrap();
        }

        let mut weight = vec![0u64; n + 1];
        let mut size = vec![0u64; n + 1];
        let mut cost = vec![0u64; n + 1];
        let mut total_weight = 0u64;

        for i in 1..=n {
            let a: u64 = it.next().unwrap().parse().unwrap();
            weight[i] = a;
            size[i] = 1;
            cost[i] = a % MOD;
            total_weight += a;
        }

        let mut dsu: Vec<usize> = (0..=n).collect();
        let mut version = vec![0usize; n + 1];
        let mut heap = BinaryHeap::new();

        for i in 1..=n {
            heap.push(Entry {
                weight: weight[i],
                size: size[i],
                id: i,
                version: 0,
            });
        }

        for _ in 0..n {
            let entry = loop {
                let e = heap.pop().unwrap();
                if dsu[e.id] == e.id && version[e.id] == e.version {
                    break e;
                }
            };

            let x = entry.id;
            let y = find(parent[x], &mut dsu);

            let shift = (size[y] % MOD) * (weight[x] % MOD) % MOD;
            cost[y] = (cost[y] + cost[x] + shift) % MOD;
            size[y] += size[x];
            weight[y] += weight[x];

            dsu[x] = y;

            if y != 0 {
                version[y] += 1;
                heap.push(Entry {
                    weight: weight[y],
                    size: size[y],
                    id: y,
                    version: version[y],
                });
            }
        }

        let answer = cost[0] * mod_pow(total_weight % MOD, MOD - 2) % MOD;
        output.push_str(&format!("{answer}\n"));
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
