use std::io::{self, Read, Write};

fn lower_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn count_in_range(values: &[i64], low: i64, high: i64) -> i64 {
    if low > high {
        return 0;
    }
    (lower_bound(values, high + 1) - lower_bound(values, low)) as i64
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: i64 = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut rows = Vec::with_capacity(m);
    let mut cols = Vec::with_capacity(m);
    let mut sums = Vec::with_capacity(m);
    let mut diffs = Vec::with_capacity(m);

    for _ in 0..m {
        let a: i64 = iter.next().unwrap().parse().unwrap();
        let b: i64 = iter.next().unwrap().parse().unwrap();
        rows.push(a);
        cols.push(b);
        sums.push(a + b);
        diffs.push(a - b);
    }

    rows.sort_unstable();
    rows.dedup();
    cols.sort_unstable();
    cols.dedup();
    sums.sort_unstable();
    sums.dedup();
    diffs.sort_unstable();
    diffs.dedup();

    let allowed_rows = n - rows.len() as i64;
    let allowed_cols = n - cols.len() as i64;
    let mut answer = allowed_rows * allowed_cols;

    // Count allowed-row/allowed-column cells lying on a forbidden sum diagonal.
    for &sum in &sums {
        let low = 1.max(sum - n);
        let high = n.min(sum - 1);
        let total = (high - low + 1).max(0);

        let bad_rows = count_in_range(&rows, low, high);
        let bad_cols = count_in_range(&cols, low, high);

        let mut bad_both = 0i64;
        for &row in &rows {
            let col = sum - row;
            if cols.binary_search(&col).is_ok() {
                bad_both += 1;
            }
        }

        answer -= total - bad_rows - bad_cols + bad_both;
    }

    // Count allowed-row/allowed-column cells lying on a forbidden difference diagonal.
    for &diff in &diffs {
        let row_low = 1.max(1 + diff);
        let row_high = n.min(n + diff);
        let col_low = 1.max(1 - diff);
        let col_high = n.min(n - diff);

        let total = (row_high - row_low + 1).max(0);
        let bad_rows = count_in_range(&rows, row_low, row_high);
        let bad_cols = count_in_range(&cols, col_low, col_high);

        let mut bad_both = 0i64;
        for &row in &rows {
            let col = row - diff;
            if cols.binary_search(&col).is_ok() {
                bad_both += 1;
            }
        }

        answer -= total - bad_rows - bad_cols + bad_both;
    }

    // Add back intersections counted in both kinds of forbidden diagonals.
    for &sum in &sums {
        for &diff in &diffs {
            if (sum + diff) % 2 != 0 {
                continue;
            }

            let row = (sum + diff) / 2;
            let col = (sum - diff) / 2;

            if row < 1 || row > n || col < 1 || col > n {
                continue;
            }
            if rows.binary_search(&row).is_ok() || cols.binary_search(&col).is_ok() {
                continue;
            }

            answer += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
