use std::io::{self, Read, Write};

const NONE: u32 = u32::MAX;

struct Node {
    children: [u32; 26],
    min_len: u32,
}

impl Node {
    fn new() -> Self {
        Self {
            children: [NONE; 26],
            min_len: NONE,
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut trie = Vec::with_capacity(200_001);
    trie.push(Node::new());

    let mut output = String::new();

    for _ in 0..n {
        let s = iter.next().unwrap().as_bytes();
        let len = s.len() as u32;
        let mut answer = len;
        let mut node = 0usize;

        for (i, &byte) in s.iter().enumerate() {
            let c = (byte - b'a') as usize;
            let next = trie[node].children[c];
            if next == NONE {
                break;
            }

            node = next as usize;
            let depth = (i + 1) as u32;
            if trie[node].min_len != NONE {
                let cost = len + trie[node].min_len - 2 * depth;
                answer = answer.min(cost);
            }
        }

        output.push_str(&answer.to_string());
        output.push('\n');

        trie[0].min_len = trie[0].min_len.min(len);
        node = 0;

        for &byte in s {
            let c = (byte - b'a') as usize;
            if trie[node].children[c] == NONE {
                let new_index = trie.len() as u32;
                trie.push(Node::new());
                trie[node].children[c] = new_index;
            }
            node = trie[node].children[c] as usize;
            trie[node].min_len = trie[node].min_len.min(len);
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
