use std::io::{self, Read, Write};

fn mod_pow(mut base: u64, mut exp: u64, modu: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % modu;
        }
        base = base * base % modu;
        exp >>= 1;
    }
    result
}

fn standard_tableaux_count(rows: &[usize], modu: u64) -> u64 {
    let n: usize = rows.iter().sum();

    let mut numerator = 1u64;
    for x in 1..=n {
        numerator = numerator * x as u64 % modu;
    }

    let mut denominator = 1u64;
    for i in 0..rows.len() {
        for j in 0..rows[i] {
            let right = rows[i] - j - 1;
            let below = ((i + 1)..rows.len())
                .filter(|&k| rows[k] > j)
                .count();
            let hook = right + below + 1;
            denominator = denominator * hook as u64 % modu;
        }
    }

    numerator * mod_pow(denominator, modu - 2, modu) % modu
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let a: usize = it.next().unwrap().parse().unwrap();
    let b: usize = it.next().unwrap().parse().unwrap();
    let m: u64 = it.next().unwrap().parse().unwrap();

    // Shape corresponding to LIS = A, LDS = B, and size AB - 1:
    // (A, A, ..., A, A - 1).
    let mut lambda = vec![a; b];
    lambda[b - 1] = a - 1;

    // Valid insertion tableaux are exactly those whose maximum is in
    // the corner (B - 1, A). Removing that corner gives this shape.
    let mut mu = lambda.clone();
    mu[b - 2] -= 1;

    let recording_tableaux = standard_tableaux_count(&lambda, m);
    let valid_insertion_tableaux = standard_tableaux_count(&mu, m);
    let answer = recording_tableaux * valid_insertion_tableaux % m;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
