```rust
use std::io::{self, Read, Write};

struct Solver {
    a: usize,
    b: usize,
    modu: i64,
    fact: Vec<i64>,
    inv_fact: Vec<i64>,
    parts: Vec<usize>,
    answer: i64,
}

impl Solver {
    fn mul(&self, x: i64, y: i64) -> i64 {
        ((x as i128 * y as i128) % self.modu as i128) as i64
    }

    fn straight_tableaux(&self, shape: &[usize]) -> i64 {
        let rows = shape.len();
        let size: usize = shape.iter().sum();
        let mut result = self.fact[size];
        let mut shifted = Vec::with_capacity(rows);

        for (i, &len) in shape.iter().enumerate() {
            let value = len + rows - 1 - i;
            shifted.push(value);
            result = self.mul(result, self.inv_fact[value]);
        }

        for i in 0..rows {
            for j in (i + 1)..rows {
                result = self.mul(result, (shifted[i] - shifted[j]) as i64);
            }
        }

        result
    }

    fn skew_suffix_tableaux(&self) -> i64 {
        let rows = self.b - 1;
        let mut inner = Vec::with_capacity(rows);
        inner.push(self.a);
        inner.extend_from_slice(&self.parts);

        let inner_size: usize = inner.iter().sum();
        let suffix_size = self.a * rows - inner_size;
        let mut result = self.fact[suffix_size];
        let mut x = Vec::with_capacity(rows);

        for (j, &len) in inner.iter().enumerate() {
            let value = self.a - len + j + 1;
            x.push(value);
            result = self.mul(result, self.inv_fact[value - 1]);
        }

        for i in 0..rows {
            for j in (i + 1)..rows {
                result = self.mul(result, (x[j] - x[i]) as i64);
            }
        }

        result
    }

    fn evaluate_partition(&mut self) {
        let mut prefix_shape = Vec::with_capacity(self.b);
        prefix_shape.push(self.a - 1);
        prefix_shape.push(self.a - 1);
        prefix_shape.extend_from_slice(&self.parts);

        let prefix_count = self.straight_tableaux(&prefix_shape);
        let suffix_count = self.skew_suffix_tableaux();
        let contribution = self.mul(prefix_count, suffix_count);

        self.answer += contribution;
        if self.answer >= self.modu {
            self.answer -= self.modu;
        }
    }

    fn enumerate(&mut self, pos: usize, max_value: usize) {
        if pos == self.parts.len() {
            self.evaluate_partition();
            return;
        }

        for value in (0..=max_value).rev() {
            self.parts[pos] = value;
            self.enumerate(pos + 1, value);
        }
    }
}

fn mod_pow(mut base: i64, mut exp: i64, modu: i64) -> i64 {
    let mut result = 1_i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = ((result as i128 * base as i128) % modu as i128) as i64;
        }
        base = ((base as i128 * base as i128) % modu as i128) as i64;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let mut a: usize = iter.next().unwrap().parse().unwrap();
    let mut b: usize = iter.next().unwrap().parse().unwrap();
    let modu: i64 = iter.next().unwrap().parse().unwrap();

    if b > a {
        std::mem::swap(&mut a, &mut b);
    }

    let n = a * b - 1;
    let mut fact = vec![1_i64; n + 1];
    for i in 1..=n {
        fact[i] = ((fact[i - 1] as i128 * i as i128) % modu as i128) as i64;
    }

    let mut inv_fact = vec![1_i64; n + 1];
    inv_fact[n] = mod_pow(fact[n], modu - 2, modu);
    for i in (1..=n).rev() {
        inv_fact[i - 1] =
            ((inv_fact[i] as i128 * i as i128) % modu as i128) as i64;
    }

    let mut target_shape = vec![a; b];
    target_shape[b - 1] = a - 1;

    let mut solver = Solver {
        a,
        b,
        modu,
        fact,
        inv_fact,
        parts: vec![0; b - 2],
        answer: 0,
    };

    let recording_tableaux = solver.straight_tableaux(&target_shape);
    solver.enumerate(0, a - 1);

    let result = solver.mul(recording_tableaux, solver.answer);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{result}").unwrap();
}
