use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: i128 = iter.next().unwrap().parse::<i64>().unwrap() as i128;
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut positions = Vec::with_capacity(m);
    for _ in 0..m {
        positions.push(iter.next().unwrap().parse::<i64>().unwrap() as i128);
    }

    let mut cells = Vec::with_capacity(m);
    for x in positions {
        let amount = iter.next().unwrap().parse::<i64>().unwrap() as i128;
        cells.push((x, amount));
    }
    cells.sort_unstable_by_key(|&(x, _)| x);

    let mut stones = 0i128;
    let mut initial_position_sum = 0i128;
    let mut possible = true;

    for &(x, amount) in &cells {
        if stones < x - 1 {
            possible = false;
        }
        stones += amount;
        initial_position_sum += x * amount;
    }

    if stones != n {
        possible = false;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if !possible {
        writeln!(out, "-1").unwrap();
    } else {
        let target_position_sum = n * (n + 1) / 2;
        writeln!(out, "{}", target_position_sum - initial_position_sum).unwrap();
    }
}
