    let q: usize = iter.next().unwrap().parse().unwrap();
    let mut elapsed: i64 = 0;
    let mut planted_at: Vec<i64> = Vec::with_capacity(q);
    let mut head = 0usize;
    let mut output = String::new();

    for _ in 0..q {
        let query_type: u8 = iter.next().unwrap().parse().unwrap();

        match query_type {
            1 => {
                planted_at.push(elapsed);
            }
            2 => {
                let t: i64 = iter.next().unwrap().parse().unwrap();
                elapsed += t;
            }
            3 => {
                let h: i64 = iter.next().unwrap().parse().unwrap();
                let threshold = elapsed - h;
                let start = head;

                while head < planted_at.len() && planted_at[head] <= threshold {
                    head += 1;
                }

                output.push_str(&(head - start).to_string());
                output.push('\n');
            }
            _ => unreachable!(),
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
