use std::io::{self, Read, Write};

fn range_max(tree: &[usize], size: usize, mut left: usize, mut right: usize) -> usize {
    left += size;
    right += size;
    let mut result = 0;

    while left < right {
        if left & 1 == 1 {
            result = result.max(tree[left]);
            left += 1;
        }
        if right & 1 == 1 {
            right -= 1;
            result = result.max(tree[right]);
        }
        left >>= 1;
        right >>= 1;
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut heights = vec![0usize; n];
    for h in &mut heights {
        *h = iter.next().unwrap().parse().unwrap();
    }

    // Segment tree for range maximum queries.
    let mut size = 1usize;
    while size < n {
        size <<= 1;
    }
    let mut segtree = vec![0usize; size * 2];
    for i in 0..n {
        segtree[size + i] = heights[i];
    }
    for i in (1..size).rev() {
        segtree[i] = segtree[i << 1].max(segtree[i << 1 | 1]);
    }

    // next_greater[i] is the first building to the right taller than i.
    let sentinel = n;
    let mut next_greater = vec![sentinel; n];
    let mut stack: Vec<usize> = Vec::new();

    for i in (0..n).rev() {
        while let Some(&j) = stack.last() {
            if heights[j] < heights[i] {
                stack.pop();
            } else {
                break;
            }
        }
        if let Some(&j) = stack.last() {
            next_greater[i] = j;
        }
        stack.push(i);
    }

    // chain_len[i] counts i and all nodes reached through next_greater.
    let mut chain_len = vec![1usize; n];
    for i in (0..n).rev() {
        if next_greater[i] != sentinel {
            chain_len[i] = 1 + chain_len[next_greater[i]];
        }
    }

    // Binary lifting over next-greater chains.
    let mut log = 1usize;
    while (1usize << log) <= n {
        log += 1;
    }

    let mut up = vec![vec![sentinel; n]; log];
    up[0].clone_from_slice(&next_greater);

    for k in 1..log {
        for i in 0..n {
            let middle = up[k - 1][i];
            if middle != sentinel {
                up[k][i] = up[k - 1][middle];
            }
        }
    }

    let mut output = String::new();

    for _ in 0..q {
        let l: usize = iter.next().unwrap().parse().unwrap();
        let r: usize = iter.next().unwrap().parse().unwrap();

        // Buildings L+1 through R correspond to zero-based range [l, r).
        let threshold = range_max(&segtree, size, l, r);

        // The first building east of R has zero-based index r.
        if r == n {
            output.push_str("0\n");
            continue;
        }

        let start = r;
        if heights[start] > threshold {
            output.push_str(&format!("{}\n", chain_len[start]));
            continue;
        }

        let mut current = start;

        // Skip all visible buildings whose heights do not exceed threshold.
        for k in (0..log).rev() {
            let candidate = up[k][current];
            if candidate != sentinel && heights[candidate] <= threshold {
                current = candidate;
            }
        }

        let first_valid = up[0][current];
        if first_valid == sentinel {
            output.push_str("0\n");
        } else {
            output.push_str(&format!("{}\n", chain_len[first_valid]));
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
