use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn generate_sources(
    target: &[u8],
    pos: usize,
    current: u8,
    first: u8,
    mask: usize,
    base: usize,
    sources: &mut Vec<u16>,
) {
    if pos + 1 == target.len() {
        let id = first as usize * base + mask;
        sources.push(id as u16);
        return;
    }

    let next_target = target[pos + 1];
    for next in 0u8..3 {
        if next == current || next == next_target {
            continue;
        }
        let next_mask = if next == (current + 1) % 3 {
            mask | (1usize << pos)
        } else {
            mask
        };
        generate_sources(
            target,
            pos + 1,
            next,
            first,
            next_mask,
            base,
            sources,
        );
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let original_h: usize = iter.next().unwrap().parse().unwrap();
    let original_w: usize = iter.next().unwrap().parse().unwrap();

    let mut original = Vec::with_capacity(original_h);
    for _ in 0..original_h {
        original.push(iter.next().unwrap().as_bytes().to_vec());
    }

    let (h, w, grid) = if original_h >= original_w {
        (original_h, original_w, original)
    } else {
        let mut transposed = vec![vec![b'?'; original_h]; original_w];
        for i in 0..original_h {
            for j in 0..original_w {
                transposed[j][i] = original[i][j];
            }
        }
        (original_w, original_h, transposed)
    };

    let base = 1usize << (w - 1);
    let state_count = 3 * base;

    // Every state is determined by its first color and whether each
    // subsequent color changes by +1 or -1 modulo 3.
    let mut state_colors = vec![0u8; state_count * w];
    for state in 0..state_count {
        let first = (state / base) as u8;
        let mask = state % base;
        state_colors[state * w] = first;

        let mut color = first;
        for col in 1..w {
            if ((mask >> (col - 1)) & 1) != 0 {
                color = (color + 1) % 3;
            } else {
                color = (color + 2) % 3;
            }
            state_colors[state * w + col] = color;
        }
    }

    let mut allowed = vec![0u8; h * state_count];
    for row in 0..h {
        for state in 0..state_count {
            let mut ok = true;
            for col in 0..w {
                let fixed = grid[row][col];
                if fixed != b'?' {
                    let required = fixed - b'1';
                    if state_colors[state * w + col] != required {
                        ok = false;
                        break;
                    }
                }
            }
            allowed[row * state_count + state] = ok as u8;
        }
    }

    // Adjacency is stored as CSR, grouped by the target state.
    // There are exactly 6 * 3^(w-1) compatible ordered pairs of rows.
    let edge_count = 6usize * 3usize.pow((w - 1) as u32);
    let mut sources = Vec::<u16>::with_capacity(edge_count);
    let mut offsets = Vec::<usize>::with_capacity(state_count + 1);
    offsets.push(0);

    let mut target = vec![0u8; w];
    for target_state in 0..state_count {
        target.copy_from_slice(
            &state_colors[target_state * w..(target_state + 1) * w],
        );

        for first in 0u8..3 {
            if first != target[0] {
                generate_sources(
                    &target,
                    0,
                    first,
                    first,
                    0,
                    base,
                    &mut sources,
                );
            }
        }
        offsets.push(sources.len());
    }

    let mut dp = vec![0u64; state_count];
    for state in 0..state_count {
        if allowed[state] != 0 {
            dp[state] = 1;
        }
    }

    let mut next_dp = vec![0u64; state_count];
    for row in 1..h {
        next_dp.fill(0);

        for target_state in 0..state_count {
            if allowed[row * state_count + target_state] == 0 {
                continue;
            }

            let mut sum = 0u64;
            for &source in &sources[offsets[target_state]..offsets[target_state + 1]] {
                sum += dp[source as usize];
            }
            next_dp[target_state] = sum % MOD;
        }

        std::mem::swap(&mut dp, &mut next_dp);
    }

    let answer = dp.iter().fold(0u64, |acc, &value| (acc + value) % MOD);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
