use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    left: Vec<usize>,
    right: Vec<usize>,
    color: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            left: (0..n).collect(),
            right: (0..n).collect(),
            color: (0..n).collect(),
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut current = x;
        while self.parent[current] != current {
            let next = self.parent[current];
            self.parent[current] = root;
            current = next;
        }
        root
    }

    fn unite(&mut self, a: usize, b: usize) -> usize {
        let mut ra = self.find(a);
        let mut rb = self.find(b);

        if ra == rb {
            return ra;
        }

        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        self.left[ra] = self.left[ra].min(self.left[rb]);
        self.right[ra] = self.right[ra].max(self.right[rb]);
        ra
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut dsu = Dsu::new(n);
    let mut color_count = vec![1usize; n];
    let mut output = String::new();

    for _ in 0..q {
        let query_type: usize = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            let x: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            let new_color: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

            let mut root = dsu.find(x);
            let old_color = dsu.color[root];

            if old_color == new_color {
                continue;
            }

            let component_size = dsu.size[root];
            color_count[old_color] -= component_size;
            color_count[new_color] += component_size;
            dsu.color[root] = new_color;

            let left = dsu.left[root];
            if left > 0 {
                let neighbor = dsu.find(left - 1);
                if dsu.color[neighbor] == new_color {
                    root = dsu.unite(root, neighbor);
                    dsu.color[root] = new_color;
                }
            }

            let right = dsu.right[root];
            if right + 1 < n {
                let neighbor = dsu.find(right + 1);
                if dsu.color[neighbor] == new_color {
                    root = dsu.unite(root, neighbor);
                    dsu.color[root] = new_color;
                }
            }
        } else {
            let color: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            output.push_str(&format!("{}\n", color_count[color]));
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
