use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

struct Fenwick {
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut index: usize, value: i64) {
        while index < self.tree.len() {
            self.tree[index] += value;
            index += index & index.wrapping_neg();
        }
    }

    fn sum(&self, mut index: usize) -> i64 {
        let mut result = 0;
        while index > 0 {
            result += self.tree[index];
            index &= index - 1;
        }
        result
    }
}

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let p: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    // Inversion number of the whole permutation.
    let mut bit = Fenwick::new(n);
    let mut total_inversions = 0i64;
    for (i, &x) in p.iter().enumerate() {
        let not_greater = bit.sum(x);
        total_inversions += i as i64 - not_greater;
        bit.add(x, 1);
    }

    // Sum of inversion numbers over all contiguous subarrays of length K.
    let mut window_bit = Fenwick::new(n);
    let mut window_inversions = 0i64;

    for (i, &x) in p[..k].iter().enumerate() {
        window_inversions += i as i64 - window_bit.sum(x);
        window_bit.add(x, 1);
    }

    let window_count = n - k + 1;
    let mut sum_window_inversions = window_inversions;

    for left in 0..(window_count - 1) {
        let removed = p[left];
        window_bit.add(removed, -1);

        // The removed element was the leftmost one, so it contributed
        // inversions with all smaller remaining elements.
        window_inversions -= window_bit.sum(removed - 1);

        let added = p[left + k];
        // The added element is the rightmost one, so every larger remaining
        // element forms an inversion with it.
        window_inversions += (k - 1) as i64 - window_bit.sum(added);
        window_bit.add(added, 1);

        sum_window_inversions += window_inversions;
    }

    let inverse_window_count = mod_pow(window_count as i64, MOD - 2);
    let inverse_four = mod_pow(4, MOD - 2);

    let expected_internal_after_shuffle =
        (k as i64 % MOD) * ((k - 1) as i64 % MOD) % MOD * inverse_four % MOD;

    let average_original_internal =
        (sum_window_inversions % MOD) * inverse_window_count % MOD;

    let mut answer = total_inversions % MOD;
    answer += expected_internal_after_shuffle;
    answer -= average_original_internal;
    answer %= MOD;
    if answer < 0 {
        answer += MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
