use std::io::{self, Read, Write};

fn binomial(n: u64, k: u64) -> u64 {
    let k = k.min(n - k);
    let mut result = 1u64;
    for i in 1..=k {
        result = result * (n - k + i) / i;
    }
    result
}

fn generate(
    pos: usize,
    n: usize,
    m: i32,
    min_value: i32,
    sequence: &mut [i32],
    output: &mut String,
) {
    if pos == n {
        for (i, value) in sequence.iter().enumerate() {
            if i > 0 {
                output.push(' ');
            }
            write!(output, "{}", value).unwrap();
        }
        output.push('\n');
        return;
    }

    let remaining = n - pos - 1;
    let max_value = m - 10 * remaining as i32;

    for value in min_value..=max_value {
        sequence[pos] = value;
        generate(pos + 1, n, m, value + 10, sequence, output);
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: i32 = iter.next().unwrap().parse().unwrap();

    let k = m - 10 * (n as i32 - 1);
    let count = binomial((k as usize + n - 1) as u64, n as u64);

    let mut output = String::new();
    writeln!(output, "{}", count).unwrap();

    let mut sequence = vec![0i32; n];
    generate(0, n, m, 1, &mut sequence, &mut output);

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
