use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

const B: i64 = 20;
const R: i64 = 40;
const INF: i64 = i64::MAX / 4;

#[derive(Clone, Copy)]
struct Tile {
    i: i64,
    j: i64,
    k: i64,
    horizontal: bool,
}

#[derive(Clone, Copy)]
struct Portal {
    i: i64,
    j: i64,
    state: usize,
    cost: i64,
}

fn tile_of(k_size: i64, x: i64, y: i64) -> Tile {
    let i = x.div_euclid(k_size);
    let j = y.div_euclid(k_size);
    let horizontal = (i + j).rem_euclid(2) == 0;
    let k = if horizontal {
        y.rem_euclid(k_size)
    } else {
        x.rem_euclid(k_size)
    };
    Tile {
        i,
        j,
        k,
        horizontal,
    }
}

fn add_portal(portals: &mut Vec<Portal>, p: Portal) {
    for old in portals.iter_mut() {
        if old.i == p.i && old.j == p.j && old.state == p.state {
            old.cost = old.cost.min(p.cost);
            return;
        }
    }
    portals.push(p);
}

fn make_portals(tile: Tile, k_size: i64) -> Vec<Portal> {
    let mut result = Vec::with_capacity(4);

    let d0 = tile.k.min(2);
    let d1 = (k_size - 1 - tile.k).min(2);

    add_portal(
        &mut result,
        Portal {
            i: tile.i,
            j: tile.j,
            state: 0,
            cost: d0,
        },
    );
    add_portal(
        &mut result,
        Portal {
            i: tile.i,
            j: tile.j,
            state: 1,
            cost: d1,
        },
    );

    if tile.horizontal {
        add_portal(
            &mut result,
            Portal {
                i: tile.i - 1,
                j: tile.j,
                state: 1,
                cost: 1,
            },
        );
        add_portal(
            &mut result,
            Portal {
                i: tile.i + 1,
                j: tile.j,
                state: 0,
                cost: 1,
            },
        );
    } else {
        add_portal(
            &mut result,
            Portal {
                i: tile.i,
                j: tile.j - 1,
                state: 1,
                cost: 1,
            },
        );
        add_portal(
            &mut result,
            Portal {
                i: tile.i,
                j: tile.j + 1,
                state: 0,
                cost: 1,
            },
        );
    }

    result
}

fn index(x: i64, y: i64, state: usize) -> usize {
    let side = (2 * R + 1) as usize;
    (((x + R) as usize) * side + (y + R) as usize) * 2 + state
}

fn build_dist(origin_horizontal: bool, start_state: usize, switch_cost: i64) -> Vec<i64> {
    let side = (2 * R + 1) as usize;
    let n = side * side * 2;
    let mut dist = vec![INF; n];
    let mut heap = BinaryHeap::new();

    let start = index(0, 0, start_state);
    dist[start] = 0;
    heap.push((Reverse(0_i64), 0_i64, 0_i64, start_state));

    while let Some((Reverse(d), x, y, state)) = heap.pop() {
        let idx = index(x, y, state);
        if dist[idx] != d {
            continue;
        }

        let other = state ^ 1;
        let nd = d + switch_cost;
        let oi = index(x, y, other);
        if nd < dist[oi] {
            dist[oi] = nd;
            heap.push((Reverse(nd), x, y, other));
        }

        let horizontal = origin_horizontal ^ ((x + y).rem_euclid(2) != 0);

        let mut relax = |nx: i64,
                         ny: i64,
                         ns: usize,
                         heap: &mut BinaryHeap<(Reverse<i64>, i64, i64, usize)>,
                         dist: &mut Vec<i64>| {
            if nx < -R || nx > R || ny < -R || ny > R {
                return;
            }
            let ni = index(nx, ny, ns);
            let nd = d + 1;
            if nd < dist[ni] {
                dist[ni] = nd;
                heap.push((Reverse(nd), nx, ny, ns));
            }
        };

        if horizontal {
            relax(x + 1, y, 0, &mut heap, &mut dist);
            relax(x - 1, y, 1, &mut heap, &mut dist);

            if state == 1 {
                relax(x, y + 1, 0, &mut heap, &mut dist);
                relax(x, y + 1, 1, &mut heap, &mut dist);
            }
            if state == 0 {
                relax(x, y - 1, 0, &mut heap, &mut dist);
                relax(x, y - 1, 1, &mut heap, &mut dist);
            }
        } else {
            relax(x, y + 1, 0, &mut heap, &mut dist);
            relax(x, y - 1, 1, &mut heap, &mut dist);

            if state == 1 {
                relax(x + 1, y, 0, &mut heap, &mut dist);
                relax(x + 1, y, 1, &mut heap, &mut dist);
            }
            if state == 0 {
                relax(x - 1, y, 0, &mut heap, &mut dist);
                relax(x - 1, y, 1, &mut heap, &mut dist);
            }
        }
    }

    dist
}

fn normalize(mut dx: i64, mut dy: i64) -> (i64, i64, i64) {
    let mut extra = 0_i64;

    let common = dx.abs().min(dy.abs());
    if common > B {
        let take = common - B;
        dx -= dx.signum() * take;
        dy -= dy.signum() * take;
        extra += 2 * take;
    }

    if dx.abs() > B + 1 {
        let take = (dx.abs() - B) / 2;
        dx -= dx.signum() * (2 * take);
        extra += 4 * take;
    }

    if dy.abs() > B + 1 {
        let take = (dy.abs() - B) / 2;
        dy -= dy.signum() * (2 * take);
        extra += 4 * take;
    }

    (dx, dy, extra)
}

fn canonical_distance(
    a: Portal,
    b: Portal,
    tables: &[Vec<Vec<i64>>],
) -> i64 {
    let dx = b.i - a.i;
    let dy = b.j - a.j;
    let (rx, ry, extra) = normalize(dx, dy);

    let origin_horizontal = (a.i + a.j).rem_euclid(2) == 0;
    let ori = if origin_horizontal { 0 } else { 1 };
    let d = tables[ori][a.state][index(rx, ry, b.state)];
    extra + d
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let t: usize = it.next().unwrap().parse().unwrap();

    let tables_k2 = vec![
        vec![
            build_dist(true, 0, 1),
            build_dist(true, 1, 1),
        ],
        vec![
            build_dist(false, 0, 1),
            build_dist(false, 1, 1),
        ],
    ];
    let tables_large = vec![
        vec![
            build_dist(true, 0, 2),
            build_dist(true, 1, 2),
        ],
        vec![
            build_dist(false, 0, 2),
            build_dist(false, 1, 2),
        ],
    ];

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..t {
        let k_size: i64 = it.next().unwrap().parse().unwrap();
        let sx: i64 = it.next().unwrap().parse().unwrap();
        let sy: i64 = it.next().unwrap().parse().unwrap();
        let tx: i64 = it.next().unwrap().parse().unwrap();
        let ty: i64 = it.next().unwrap().parse().unwrap();

        let start = tile_of(k_size, sx, sy);
        let target = tile_of(k_size, tx, ty);

        let start_portals = make_portals(start, k_size);
        let target_portals = make_portals(target, k_size);
        let tables = if k_size == 2 {
            &tables_k2
        } else {
            &tables_large
        };

        let mut answer = INF;

        if start.i == target.i && start.j == target.j {
            answer = answer.min((start.k - target.k).abs().min(2));
        }

        for &sp in &start_portals {
            for &tp in &target_portals {
                let d = sp.cost + canonical_distance(sp, tp, tables) + tp.cost;
                answer = answer.min(d);
            }
        }

        writeln!(out, "{answer}").unwrap();
    }
}
