fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let d: usize = iter.next().unwrap().parse().unwrap();

    let mut floors = Vec::new();

    for i in 0..h {
        let row = iter.next().unwrap().as_bytes();
        for j in 0..w {
            if row[j] == b'.' {
                floors.push((i, j));
            }
        }
    }

    let mut answer = 0;

    for a in 0..floors.len() {
        for b in (a + 1)..floors.len() {
            let (r1, c1) = floors[a];
            let (r2, c2) = floors[b];
            let mut count = 0;

            for &(r, c) in &floors {
                let dist1 = r.abs_diff(r1) + c.abs_diff(c1);
                let dist2 = r.abs_diff(r2) + c.abs_diff(c2);

                if dist1 <= d || dist2 <= d {
                    count += 1;
                }
            }

            answer = answer.max(count);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
