use std::io::{self, Read, Write};

fn integer_sqrt(n: u64) -> u64 {
    let mut low = 0u64;
    let mut high = n + 1;
    while high - low > 1 {
        let mid = low + (high - low) / 2;
        if (mid as u128) * (mid as u128) <= n as u128 {
            low = mid;
        } else {
            high = mid;
        }
    }
    low
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u64 = input.trim().parse().unwrap();

    let limit = integer_sqrt(n) as usize;

    let mut is_prime = vec![true; limit + 1];
    if limit >= 0 {
        is_prime[0] = false;
    }
    if limit >= 1 {
        is_prime[1] = false;
    }

    let mut i = 2usize;
    while i * i <= limit {
        if is_prime[i] {
            let mut multiple = i * i;
            while multiple <= limit {
                is_prime[multiple] = false;
                multiple += i;
            }
        }
        i += 1;
    }

    let primes: Vec<u64> = (2..=limit)
        .filter(|&x| is_prime[x])
        .map(|x| x as u64)
        .collect();

    let mut answer = 0u64;

    // Numbers of the form p^8.
    for &p in &primes {
        let mut power = 1u128;
        for _ in 0..8 {
            power *= p as u128;
        }
        if power <= n as u128 {
            answer += 1;
        } else {
            break;
        }
    }

    // Numbers of the form p^2 * q^2 for distinct primes p < q.
    if primes.len() >= 2 {
        let max_product = limit as u64;
        let mut right = primes.len() - 1;

        for left in 0..primes.len() {
            while right > left
                && (primes[left] as u128) * (primes[right] as u128)
                    > max_product as u128
            {
                right -= 1;
            }

            if right <= left {
                break;
            }

            answer += (right - left) as u64;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
