use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    balance: Vec<i64>,
}

impl Dsu {
    fn new(balance: Vec<i64>) -> Self {
        let n = balance.len();
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            balance,
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut current = x;
        while self.parent[current] != current {
            let next = self.parent[current];
            self.parent[current] = root;
            current = next;
        }
        root
    }

    fn merge(&mut self, a: usize, b: usize) -> Option<(i64, i64)> {
        let mut ra = self.find(a);
        let mut rb = self.find(b);

        if ra == rb {
            return None;
        }

        let ba = self.balance[ra];
        let bb = self.balance[rb];

        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        self.balance[ra] = ba + bb;

        Some((ba, bb))
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut edges = Vec::with_capacity(m);
    for _ in 0..m {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let w: i64 = iter.next().unwrap().parse().unwrap();
        edges.push((w, u, v));
    }

    let mut balance = vec![0_i64; n];

    for _ in 0..k {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        balance[a] += 1;
    }

    for _ in 0..k {
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        balance[b] -= 1;
    }

    edges.sort_unstable_by_key(|&(w, _, _)| w);

    let mut dsu = Dsu::new(balance);
    let mut answer = 0_i64;

    for (w, u, v) in edges {
        if let Some((bu, bv)) = dsu.merge(u, v) {
            if (bu > 0 && bv < 0) || (bu < 0 && bv > 0) {
                answer += bu.abs().min(bv.abs()) * w;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
