fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let s: u64 = iter.next().unwrap().parse().unwrap();
    let a: Vec<u64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let total: u64 = a.iter().sum();
    let target = s % total;

    let exists = if target == 0 {
        true
    } else {
        let mut right = 0usize;
        let mut sum = 0u64;
        let mut found = false;

        for left in 0..n {
            while right < left + n && sum < target {
                sum += a[right % n];
                right += 1;
            }

            if sum == target {
                found = true;
                break;
            }

            if right > left {
                sum -= a[left];
            } else {
                right = left + 1;
            }
        }

        found
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if exists { "Yes" } else { "No" }).unwrap();
}
