use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Group {
    residue: u32,
    count: i128,
    quotient_sum: i128,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut values = Vec::with_capacity(n);
    let mut total_sum = 0i128;
    let mut max_value = 0u32;

    for _ in 0..n {
        let x: u32 = it.next().unwrap().parse().unwrap();
        values.push(x);
        total_sum += x as i128;
        max_value = max_value.max(x);
    }

    // Sum of A_i + A_j over all 1 <= i <= j <= N.
    let mut answer = (n as i128 + 1) * total_sum;

    let mut buffer = vec![0u32; n];
    let mut groups: Vec<Group> = Vec::with_capacity(n);

    let max_sum = 2 * max_value;
    let mut k = 1u32;
    let mut modulus = 2u32;

    while modulus <= max_sum {
        let bit = 1u32 << (k - 1);

        // Stable partition by the next bit. Inductively, this sorts values by
        // their residues modulo 2^k.
        let zero_count = values.iter().filter(|&&x| x & bit == 0).count();
        let mut zero_pos = 0usize;
        let mut one_pos = zero_count;

        for &x in &values {
            if x & bit == 0 {
                buffer[zero_pos] = x;
                zero_pos += 1;
            } else {
                buffer[one_pos] = x;
                one_pos += 1;
            }
        }
        std::mem::swap(&mut values, &mut buffer);

        groups.clear();
        let mask = modulus - 1;

        for &x in &values {
            let residue = x & mask;
            let quotient = (x >> k) as i128;

            if let Some(last) = groups.last_mut() {
                if last.residue == residue {
                    last.count += 1;
                    last.quotient_sum += quotient;
                    continue;
                }
            }

            groups.push(Group {
                residue,
                count: 1,
                quotient_sum: quotient,
            });
        }

        let mut correction = 0i128;
        let mut left = 0usize;

        // Residue 0 pairs with itself, without an extra carry.
        if !groups.is_empty() && groups[0].residue == 0 {
            let g = groups[0];
            correction += (g.count + 1) * g.quotient_sum;
            left = 1;
        }

        // For nonzero residue r, the complementary residue is modulus - r.
        let mut right = groups.len();
        while left < groups.len() && groups[left].residue <= modulus / 2 {
            let g1 = groups[left];
            let target = modulus - g1.residue;

            while right > 0 && groups[right - 1].residue > target {
                right -= 1;
            }

            if right > 0 && groups[right - 1].residue == target {
                let g2 = groups[right - 1];

                if g1.residue == target {
                    let pair_count = g1.count * (g1.count + 1) / 2;
                    correction += (g1.count + 1) * g1.quotient_sum + pair_count;
                } else {
                    correction += g1.quotient_sum * g2.count
                        + g2.quotient_sum * g1.count
                        + g1.count * g2.count;
                }
            }

            left += 1;
        }

        answer -= correction;
        k += 1;
        modulus <<= 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
