use std::collections::{BTreeSet, HashMap};
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let mut x: i64 = iter.next().unwrap().parse().unwrap();
    let mut y: i64 = iter.next().unwrap().parse().unwrap();

    let mut by_x: HashMap<i64, BTreeSet<i64>> = HashMap::new();
    let mut by_y: HashMap<i64, BTreeSet<i64>> = HashMap::new();

    for _ in 0..n {
        let hx: i64 = iter.next().unwrap().parse().unwrap();
        let hy: i64 = iter.next().unwrap().parse().unwrap();
        by_x.entry(hx).or_default().insert(hy);
        by_y.entry(hy).or_default().insert(hx);
    }

    let mut visited = 0usize;

    for _ in 0..m {
        let direction = iter.next().unwrap().as_bytes()[0];
        let distance: i64 = iter.next().unwrap().parse().unwrap();

        match direction {
            b'U' | b'D' => {
                let next_y = if direction == b'U' {
                    y + distance
                } else {
                    y - distance
                };
                let low = y.min(next_y);
                let high = y.max(next_y);

                let found: Vec<i64> = if let Some(set) = by_x.get_mut(&x) {
                    let values: Vec<i64> = set.range(low..=high).copied().collect();
                    for &hy in &values {
                        set.remove(&hy);
                    }
                    values
                } else {
                    Vec::new()
                };

                for hy in found {
                    if let Some(set) = by_y.get_mut(&hy) {
                        set.remove(&x);
                    }
                    visited += 1;
                }

                y = next_y;
            }
            b'L' | b'R' => {
                let next_x = if direction == b'R' {
                    x + distance
                } else {
                    x - distance
                };
                let low = x.min(next_x);
                let high = x.max(next_x);

                let found: Vec<i64> = if let Some(set) = by_y.get_mut(&y) {
                    let values: Vec<i64> = set.range(low..=high).copied().collect();
                    for &hx in &values {
                        set.remove(&hx);
                    }
                    values
                } else {
                    Vec::new()
                };

                for hx in found {
                    if let Some(set) = by_x.get_mut(&hx) {
                        set.remove(&y);
                    }
                    visited += 1;
                }

                x = next_x;
            }
            _ => unreachable!(),
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{} {} {}", x, y, visited).unwrap();
}
