fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::<usize>::new(); n];

    for _ in 0..n - 1 {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[u].push(v);
        graph[v].push(u);
    }

    let degrees: Vec<usize> = graph.iter().map(Vec::len).collect();
    let mut max_remaining = 0usize;

    for center in 0..n {
        let mut capacities: Vec<usize> = graph[center]
            .iter()
            .map(|&neighbor| degrees[neighbor] - 1)
            .filter(|&capacity| capacity > 0)
            .collect();

        capacities.sort_unstable_by(|a, b| b.cmp(a));

        for (i, &y) in capacities.iter().enumerate() {
            let x = i + 1;
            let remaining = 1 + x * (y + 1);
            max_remaining = max_remaining.max(remaining);
        }
    }

    let answer = n - max_remaining;
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
