fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut buildings = Vec::with_capacity(n);

    for _ in 0..n {
        let x: i128 = it.next().unwrap().parse::<i64>().unwrap() as i128;
        let h: i128 = it.next().unwrap().parse::<i64>().unwrap() as i128;
        buildings.push((x, h));
    }

    let mut best: Option<(i128, i128)> = None;

    for i in 0..n.saturating_sub(1) {
        let (x1, h1) = buildings[i];
        let (x2, h2) = buildings[i + 1];

        let numerator = x2 * h1 - x1 * h2;
        let denominator = x2 - x1;

        match best {
            None => best = Some((numerator, denominator)),
            Some((best_num, best_den)) => {
                if numerator * best_den > best_num * denominator {
                    best = Some((numerator, denominator));
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    match best {
        None => writeln!(out, "-1").unwrap(),
        Some((num, den)) if num < 0 => writeln!(out, "-1").unwrap(),
        Some((num, den)) => {
            let answer = num as f64 / den as f64;
            writeln!(out, "{:.18}", answer).unwrap();
        }
    }
