use std::io::{self, Read, Write};

fn primitive_root_len(s: &[u8]) -> usize {
    let n = s.len();
    let mut pi = vec![0usize; n];

    for i in 1..n {
        let mut j = pi[i - 1];
        while j > 0 && s[i] != s[j] {
            j = pi[j - 1];
        }
        if s[i] == s[j] {
            j += 1;
        }
        pi[i] = j;
    }

    let period = n - pi[n - 1];
    if n % period == 0 {
        period
    } else {
        n
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

