    for _ in 0..t {
        let s = iter.next().unwrap().as_bytes();
        let x = iter.next().unwrap().as_bytes();
        let y = iter.next().unwrap().as_bytes();

        let possible = if x == y {
            true
        } else {
            let ones_x = x.iter().filter(|&&c| c == b'1').count() as i64;
            let ones_y = y.iter().filter(|&&c| c == b'1').count() as i64;
            let zeros_x = x.len() as i64 - ones_x;
            let zeros_y = y.len() as i64 - ones_y;

            let delta_zeros = zeros_x - zeros_y;
            let delta_ones = ones_x - ones_y;
            let s_len = s.len() as i64;

            if delta_ones == 0 {
                delta_zeros == 0
            } else {
                let numerator = -delta_zeros * s_len;

                if numerator % delta_ones != 0 {
                    false
                } else {
                    let t_len = numerator / delta_ones;
                    if t_len < 0 {
                        false
                    } else if t_len == 0 {
                        true
                    } else {
                        let root_len = primitive_root_len(s) as i64;
                        t_len % root_len == 0
                    }
                }
            }
        };

        output.push_str(if possible { "Yes\n" } else { "No\n" });
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
