use std::io::{self, Read, Write};

fn build_lifted(values: &[i64], m: i64) -> Vec<i64> {
    let n = values.len();
    let mut lifted = Vec::with_capacity(n);
    lifted.push(values[0]);

    for i in 1..n {
        let diff = (values[i] - values[i - 1]).rem_euclid(m);
        lifted.push(lifted[i - 1] + diff);
    }

    lifted
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: i64 = it.next().unwrap().parse().unwrap();

    let a: Vec<i64> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let b: Vec<i64> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();

    let answer = if m == 2 {
        if a == b { 0 } else { -1 }
    } else {
        let x = build_lifted(&a, m);
        let y = build_lifted(&b, m);

        let mut differences: Vec<i64> = (0..n).map(|i| x[i] - y[i]).collect();
        differences.sort_unstable();

        let median = differences[n / 2];
        let base = median.div_euclid(m);

        let mut best = i64::MAX;
        for k in (base - 1)..=(base + 1) {
            let shift = k * m;
            let cost: i64 = differences.iter().map(|&d| (d - shift).abs()).sum();
            best = best.min(cost);
        }
        best
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
