use std::io::{self, Read, Write};

fn gcd(mut a: i128, mut b: i128) -> i128 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn floor_sum(mut n: i128, mut m: i128, mut a: i128, mut b: i128) -> i128 {
    let mut ans = 0i128;

    loop {
        if a >= m {
            ans += n * (n - 1) / 2 * (a / m);
            a %= m;
        }
        if b >= m {
            ans += n * (b / m);
            b %= m;
        }

        let y_max = a * n + b;
        if y_max < m {
            break;
        }

        n = y_max / m;
        b = y_max % m;
        std::mem::swap(&mut m, &mut a);
    }

    ans
}

fn calculate(terms: i128, m: i128, c: i128, points: &[i128]) -> i128 {
    if terms == 0 {
        return 0;
    }

    let base_floor_sum = floor_sum(terms, m, c, 0);
    let residue_sum = c * terms * (terms - 1) / 2 - m * base_floor_sum;

    let count_less = |x: i128| -> i128 {
        if x == 0 {
            0
        } else if x == m {
            terms
        } else {
            terms - floor_sum(terms, m, c, m - x) + base_floor_sum
        }
    };

    let mut prefix_counts = Vec::with_capacity(points.len());
    for &point in points {
        prefix_counts.push(count_less(point));
    }

    let last = points[points.len() - 1];
    let mut predecessor_sum =
        prefix_counts[0] * (last - m);

    for i in 0..points.len() {
        let left_count = prefix_counts[i];
        let right_count = if i + 1 < points.len() {
            prefix_counts[i + 1]
        } else {
            terms
        };
        predecessor_sum += points[i] * (right_count - left_count);
    }

    residue_sum - predecessor_sum
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: i128 = it.next().unwrap().parse().unwrap();
    let c: i128 = it.next().unwrap().parse().unwrap();
    let k: i128 = it.next().unwrap().parse().unwrap();

    let mut points = Vec::with_capacity(n);
    for _ in 0..n {
        let a: i128 = it.next().unwrap().parse().unwrap();
        points.push((m - a) % m);
    }

    points.sort_unstable();
    points.dedup();

    let period = m / gcd(c, m);
    let full_periods = k / period;
    let remaining = k % period;

    let period_sum = calculate(period, m, c, &points);
    let remaining_sum = calculate(remaining, m, c, &points);
    let answer = full_periods * period_sum + remaining_sum;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
