use std::io::{self, Read, Write};

fn build_csr(n: usize, from: &[usize], to: &[usize]) -> (Vec<usize>, Vec<usize>) {
    let mut start = vec![0usize; n + 1];
    for &u in from {
        start[u + 1] += 1;
    }
    for i in 1..=n {
        start[i] += start[i - 1];
    }

    let mut next = start[..n].to_vec();
    let mut edges = vec![0usize; from.len()];
    for (&u, &v) in from.iter().zip(to.iter()) {
        edges[next[u]] = v;
        next[u] += 1;
    }
    (start, edges)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let t: usize = it.next().unwrap().parse().unwrap();
    let mut answer = String::new();

    for _ in 0..t {
        let n: usize = it.next().unwrap().parse().unwrap();
        let k: usize = it.next().unwrap().parse().unwrap();

        let mut a = vec![0usize; n];
        let mut b = vec![0usize; n];

        for x in &mut a {
            *x = it.next().unwrap().parse().unwrap();
        }
        for x in &mut b {
            *x = it.next().unwrap().parse().unwrap();
        }

        let mut records = Vec::with_capacity(2 * n);
        for i in 0..n {
            records.push(((a[i] as u64) << 32) | ((i as u64) << 1));
            records.push(((b[i] as u64) << 32) | ((i as u64) << 1) | 1);
        }
        records.sort_unstable();

        let mut comp_a = vec![0usize; n];
        let mut comp_b = vec![0usize; n];

        let mut components = 0usize;
        let mut previous_value = usize::MAX;
        let mut previous_position = 0usize;

        for key in records {
            let value = (key >> 32) as usize;
            let position = ((key >> 1) & 0x7fff_ffff) as usize;
            let kind = (key & 1) as usize;

            if value != previous_value || position > previous_position + k {
                components += 1;
            }
            let component = components - 1;

            if kind == 0 {
                comp_a[position] = component;
            } else {
                comp_b[position] = component;
            }

            previous_value = value;
            previous_position = position;
        }

        let mut b_count = vec![0usize; components];
        for &c in &comp_b {
            b_count[c] += 1;
        }

        let from = comp_b.clone();
        let to = comp_a.clone();

        let (start, edges) = build_csr(components, &from, &to);
        let (rev_start, rev_edges) = build_csr(components, &to, &from);

        let mut visited = vec![false; components];
        let mut order = Vec::with_capacity(components);
        let mut stack: Vec<(usize, usize)> = Vec::new();

        for root in 0..components {
            if visited[root] {
                continue;
            }
            visited[root] = true;
            stack.push((root, start[root]));

            while let Some((u, edge_index)) = stack.pop() {
                if edge_index < start[u + 1] {
                    stack.push((u, edge_index + 1));
                    let v = edges[edge_index];
                    if !visited[v] {
                        visited[v] = true;
                        stack.push((v, start[v]));
                    }
                } else {
                    order.push(u);
                }
            }
        }

        let mut scc = vec![usize::MAX; components];
        let mut scc_count = 0usize;
        let mut node_stack = Vec::new();

        for &root in order.iter().rev() {
            if scc[root] != usize::MAX {
                continue;
            }

            scc[root] = scc_count;
            node_stack.push(root);

            while let Some(u) = node_stack.pop() {
                for ei in rev_start[u]..rev_start[u + 1] {
                    let v = rev_edges[ei];
                    if scc[v] == usize::MAX {
                        scc[v] = scc_count;
                        node_stack.push(v);
                    }
                }
            }

            scc_count += 1;
        }

        let mut indegree = vec![0usize; scc_count];
        let mut has_b = vec![false; scc_count];
        let mut can_start = vec![false; scc_count];

        for node in 0..components {
            if b_count[node] > 0 {
                has_b[scc[node]] = true;
            }
        }

        for i in 0..n {
            let u = comp_b[i];
            let v = comp_a[i];
            let su = scc[u];
            let sv = scc[v];

            if su != sv {
                indegree[sv] += 1;
            } else if b_count[u] >= 2 {
                can_start[su] = true;
            }

            if a[i] == b[i] {
                can_start[su] = true;
            }
        }

        let mut possible = true;
        for c in 0..scc_count {
            if has_b[c] && indegree[c] == 0 && !can_start[c] {
                possible = false;
                break;
            }
        }

        if possible {
            answer.push_str("Yes\n");
        } else {
            answer.push_str("No\n");
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    out.write_all(answer.as_bytes()).unwrap();
}
