const MOD: u64 = 998_244_353;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let inf = n + 1;
    let mut min_r = vec![vec![inf; n + 2]; n + 2];

    for _ in 0..m {
        let l: usize = it.next().unwrap().parse().unwrap();
        let r: usize = it.next().unwrap().parse().unwrap();
        let x: usize = it.next().unwrap().parse().unwrap();
        min_r[x][l] = min_r[x][l].min(r);
    }

    // min_r[x][l] is the minimum R among conditions with X = x and L >= l.
    for x in 1..=n {
        let mut current = inf;
        for l in (1..=x).rev() {
            current = current.min(min_r[x][l]);
            min_r[x][l] = current;
        }
    }

    let mut inv = vec![0u64; n + 1];
    inv[1] = 1;
    for i in 2..=n {
        let iu = i as u64;
        inv[i] = MOD - (MOD / iu) * inv[(MOD % iu) as usize] % MOD;
    }

    // dp[l][r] is the number of valid relative orders on [l, r],
    // divided by (r-l+1)!.
    let mut dp = vec![vec![0u64; n + 2]; n + 2];

    for len in 1..=n {
        for l in 1..=n - len + 1 {
            let r = l + len - 1;
            let mut sum = 0u64;

            for x in l..=r {
                // Choosing x as the maximum is forbidden if some condition
                // with X=x is wholly contained in [l,r].
                if min_r[x][l] <= r {
                    continue;
                }

                let left = if x == l { 1 } else { dp[l][x - 1] };
                let right = if x == r { 1 } else { dp[x + 1][r] };
                let term = left * right % MOD;

                sum += term;
                if sum >= MOD {
                    sum -= MOD;
                }
            }

            dp[l][r] = sum * inv[len] % MOD;
        }
    }

    let mut factorial = 1u64;
    for i in 1..=n {
        factorial = factorial * i as u64 % MOD;
    }

    let answer = dp[1][n] * factorial % MOD;
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
