    for _ in 0..n - 1 {
        let a: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    // Find a centroid.
    let mut parent = vec![n; n];
    let mut order = Vec::with_capacity(n);
    parent[0] = 0;
    let mut stack = vec![0usize];

    while let Some(v) = stack.pop() {
        order.push(v);
        for &to in &graph[v] {
            if to != parent[v] {
                parent[to] = v;
                stack.push(to);
            }
        }
    }

    let mut size = vec![1usize; n];
    for &v in order.iter().rev() {
        if v != 0 {
            size[parent[v]] += size[v];
        }
    }

    let mut centroid = 0usize;
    for v in 0..n {
        let mut mx = n - size[v];
        for &to in &graph[v] {
            if parent[to] == v {
                mx = mx.max(size[to]);
            }
        }
        if mx * 2 <= n {
            centroid = v;
            break;
        }
    }

    // Root the tree at the centroid and obtain a postorder.
    let mut par = vec![n; n];
    let mut rooted_order = Vec::with_capacity(n);
    par[centroid] = centroid;
    let mut st = vec![centroid];

    while let Some(v) = st.pop() {
        rooted_order.push(v);
        for &to in &graph[v] {
            if to != par[v] {
                par[to] = v;
                st.push(to);
            }
        }
    }

    let mut postorder = rooted_order;
    postorder.reverse();

    // Build the standard maximum-distance pairing by cyclically shifting
    // the centroid-rooted postorder by N/2.
    let half = n / 2;
    let mut mate = vec![n; n];
    for i in 0..half {
        let a = postorder[i];
        let b = postorder[i + half];
        mate[a] = b;
        mate[b] = a;
    }

    // Dependencies between pair operations: a vertex can be removed only
    // after all of its children have been removed.
    let mut pair_id = vec![usize::MAX; n];
    let mut pairs = Vec::with_capacity(half);
    for v in 0..n {
        if pair_id[v] == usize::MAX {
            let u = mate[v];
            let id = pairs.len();
            pair_id[v] = id;
            pair_id[u] = id;
            pairs.push((v, u));
        }
    }

    let mut dependents = vec![Vec::<usize>::new(); half];
    let mut indeg = vec![0usize; half];

    for v in 0..n {
        if v == centroid {
            continue;
        }
        let child_pair = pair_id[v];
        let parent_pair = pair_id[par[v]];
        if child_pair != parent_pair {
            dependents[child_pair].push(parent_pair);
            indeg[parent_pair] += 1;
        }
    }

    // Remove duplicate dependency edges.
    for v in 0..half {
        dependents[v].sort_unstable();
        dependents[v].dedup();
    }
    indeg.fill(0);
    for v in 0..half {
        for &to in &dependents[v] {
            indeg[to] += 1;
        }
    }

    let mut ready = Vec::new();
    for i in 0..half {
        if indeg[i] == 0 {
            ready.push(i);
        }
    }

    let mut answer = Vec::with_capacity(half);
    while let Some(id) = ready.pop() {
        answer.push(pairs[id]);
        for &to in &dependents[id] {
            indeg[to] -= 1;
            if indeg[to] == 0 {
