    // Fallback ordering; this branch is not reached for the constructed
    // centroid pairing.
    if answer.len() != half {
        answer.clear();
        for i in 0..half {
            answer.push((postorder[i], postorder[i + half]));
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for (x, y) in answer {
        writeln!(out, "{} {}", x + 1, y + 1).unwrap();
    }
}
