impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut v = x;
        while self.parent[v] != v {
            v = self.parent[v];
        }
        let root = v;

        let mut v = x;
        while self.parent[v] != v {
            let next = self.parent[v];
            self.parent[v] = root;
            v = next;
        }
        root
