use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn rectangle_has_no_isolated(
    permutation: &[usize],
    left_x: usize,
    upper_y: usize,
    right_x: usize,
    lower_y: usize,
) -> bool {
    let mut values = Vec::new();

    for x in (left_x + 1)..right_x {
        let y = permutation[x];
        if lower_y < y && y < upper_y {
            values.push(y);
        }
    }

    let m = values.len();
    if m == 0 {
        return true;
    }

    let mut suffix_max = vec![0usize; m + 1];
    for i in (0..m).rev() {
        suffix_max[i] = suffix_max[i + 1].max(values[i]);
    }

    let mut prefix_min = usize::MAX;
    for i in 0..m {
        let has_left_neighbor = prefix_min < values[i];
        let has_right_neighbor = suffix_max[i + 1] > values[i];

        if !has_left_neighbor && !has_right_neighbor {
            return false;
        }

        prefix_min = prefix_min.min(values[i]);
    }

    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut permutation = vec![0usize; n + 2];

    for _ in 0..n {
        let x: usize = iter.next().unwrap().parse().unwrap();
        let y: usize = iter.next().unwrap().parse().unwrap();
        permutation[x] = y;
    }

    let vertex_count = n + 2;
    let mut y_coord = vec![0usize; vertex_count];
    y_coord[0] = n + 1;
    y_coord[1..=n].copy_from_slice(&permutation[1..=n]);
    y_coord[n + 1] = 0;

    let mut valid = vec![vec![false; vertex_count]; vertex_count];

    for left in 0..=n {
        for right in (left + 1)..=n + 1 {
            if y_coord[left] > y_coord[right] {
                valid[left][right] = rectangle_has_no_isolated(
                    &permutation,
                    left,
                    y_coord[left],
                    right,
                    y_coord[right],
                );
            }
        }
    }

    let mut dp = vec![0u64; vertex_count];
    dp[0] = 1;

    for right in 1..vertex_count {
        let mut ways = 0u64;
        for left in 0..right {
            if valid[left][right] {
                ways += dp[left];
                if ways >= MOD {
                    ways -= MOD;
                }
            }
        }
        dp[right] = ways;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[n + 1]).unwrap();
}
