        let r = total % n as i64;
        let low_count = n as i64 - r;

        let mut prefix = 0i64;
        let mut possible = true;

        for k in 1..n {
            prefix += a[k - 1];

            // The maximum possible sum of the first k elements among
            // non-decreasing integer sequences with the given total.
            let k64 = k as i64;
            let target_prefix = q * k64 + (k64 - low_count).max(0);

            if prefix > target_prefix {
                possible = false;
            }
        }

        output.push_str(if possible { "Yes\n" } else { "No\n" });
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
