    let mut len = 2usize;
    while len <= n {
        let w_len = mod_pow(root, (MOD - 1) / len as u64);

        for start in (0..n).step_by(len) {
            let mut w = 1u64;
            let half = len / 2;

            for offset in 0..half {
                let u = a[start + offset];
                let v = a[start + offset + half] * w % MOD;

                let sum = u + v;
                a[start + offset] = if sum >= MOD { sum - MOD } else { sum };
                a[start + offset + half] = if u >= v {
                    u - v
                } else {
                    u + MOD - v
                };

                w = w * w_len % MOD;
            }
        }

        len <<= 1;
    }

    if invert {
        let inv_n = mod_pow(n as u64, MOD - 2);
        for value in a {
            *value = *value * inv_n % MOD;
        }
    }
}

fn enough_counts(a: usize, b: usize, c: usize, count: &[u8]) -> bool {
    if a == b && b == c {
        count[a] >= 3
    } else if a == b {
        count[a] >= 2 && count[c] >= 1
    } else if a == c {
        count[a] >= 2 && count[b] >= 1
    } else if b == c {
        count[b] >= 2 && count[a] >= 1
    } else {
        count[a] >= 1 && count[b] >= 1 && count[c] >= 1
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let x: usize = iter.next().unwrap().parse().unwrap();

    let mut values = Vec::with_capacity(n);
    let mut count = vec![0u8; x + 1];

    for _ in 0..n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        values.push(value);
        if count[value] < 3 {
            count[value] += 1;
        }
    }

    let mut size = 1usize;
    while size <= 2 * x {
        size <<= 1;
    }

    let mut polynomial = vec![0u64; size];
    for value in 1..=x {
        if count[value] > 0 {
            polynomial[value] = 1;
        }
    }

    ntt(&mut polynomial, false);
    for value in &mut polynomial {
        *value = *value * *value % MOD;
    }
    ntt(&mut polynomial, true);

    let mut selected_c = None;

    for c in 1..=x {
        if count[c] == 0 {
            continue;
        }

        let sum = x - c;
        if sum < 2 {
            continue;
        }

        let mut valid_pairs = polynomial[sum] as i64;

        if sum % 2 == 0 {
            let d = sum / 2;
            if d <= x && count[d] > 0 {
                let required = if d == c { 3 } else { 2 };
                if count[d] < required {
                    valid_pairs -= 1;
                }
            }
        }

        if count[c] < 2 && sum > c {
            let other = sum - c;
            if other <= x && other != c && count[other] > 0 {
                valid_pairs -= 2;
            }
        }

        if valid_pairs > 0 {
            selected_c = Some(c);
            break;
        }
    }

    let mut answer_values = None;

    if let Some(c) = selected_c {
        let sum = x - c;
        for a in 1..sum {
            let b = sum - a;
            if a <= x
                && b <= x
                && count[a] > 0
                && count[b] > 0
                && enough_counts(a, b, c, &count)
            {
                answer_values = Some((a, b, c));
                break;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if let Some((a, b, c)) = answer_values {
        let targets = [a, b, c];
        let mut unique: Vec<(usize, usize)> = Vec::with_capacity(3);

        for target in targets {
            if let Some(entry) = unique.iter_mut().find(|entry| entry.0 == target) {
                entry.1 += 1;
            } else {
                unique.push((target, 1));
            }
        }

        let mut indices = Vec::with_capacity(3);

        for (index, &value) in values.iter().enumerate() {
            for entry in &mut unique {
                if entry.0 == value && entry.1 > 0 {
                    indices.push(index + 1);
                    entry.1 -= 1;
                    break;
                }
            }
            if indices.len() == 3 {
                break;
            }
        }

        indices.sort_unstable();
        writeln!(out, "{} {} {}", indices[0], indices[1], indices[2]).unwrap();
    } else {
        writeln!(out, "-1").unwrap();
    }
}
