use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;
const ROOT: u64 = 3;
const ROOT_INV: u64 = 332_748_118;

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn ntt(a: &mut [u32], invert: bool) {
    let n = a.len();

    let mut j = 0usize;
    for i in 1..n {
        let mut bit = n >> 1;
        while j & bit != 0 {
            j ^= bit;
            bit >>= 1;
        }
        j ^= bit;
        if i < j {
            a.swap(i, j);
        }
    }

    let root = if invert { ROOT_INV } else { ROOT };
    let mut len = 2usize;

    loop {
        let w_len = mod_pow(root, (MOD - 1) / len as u64);
        let half = len / 2;

        for start in (0..n).step_by(len) {
            let mut w = 1u64;
            for offset in 0..half {
                let u = a[start + offset] as u64;
                let v = (a[start + offset + half] as u64) * w % MOD;

                let sum = u + v;
                a[start + offset] = if sum >= MOD {
                    (sum - MOD) as u32
                } else {
                    sum as u32
                };

                a[start + offset + half] = if u >= v {
                    (u - v) as u32
                } else {
                    (u + MOD - v) as u32
                };

                w = w * w_len % MOD;
            }
        }

        if len == n {
            break;
        }
        len <<= 1;
    }

    if invert {
        let inv_n = mod_pow(n as u64, MOD - 2);
        for value in a.iter_mut() {
            *value = (*value as u64 * inv_n % MOD) as u32;
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let x: usize = iter.next().unwrap().parse().unwrap();

    let mut counts = vec![0u32; x + 1];
    let mut positions = vec![[0u32; 3]; x + 1];

    for index in 1..=n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        let count = counts[value] as usize;
        if count < 3 {
            positions[value][count] = index as u32;
        }
        counts[value] += 1;
    }

    drop(iter);
    drop(input);

    let required_length = 2 * x + 1;
    let mut ntt_length = 1usize;
    while ntt_length < required_length {
        ntt_length <<= 1;
    }

    let mut convolution = vec![0u32; ntt_length];
    for value in 1..=x {
        if counts[value] > 0 {
            convolution[value] = 1;
        }
    }

    ntt(&mut convolution, false);
    for value in convolution.iter_mut() {
        *value = (*value as u64 * *value as u64 % MOD) as u32;
    }
    ntt(&mut convolution, true);

    let mut answer: Option<[u32; 3]> = None;

    for c in 1..=x {
        if counts[c] == 0 {
            continue;
        }

        let pair_sum = x - c;
        let mut valid_pairs = convolution[pair_sum] as i64;

        if pair_sum % 2 == 0 {
            let t = pair_sum / 2;
            if counts[t] > 0 {
                let required = if t == c { 3 } else { 2 };
                if counts[t] < required {
                    valid_pairs -= 1;
                }
            }
        }

        if counts[c] < 2 && 2 * c <= x {
            let other = x - 2 * c;
            if other != c && counts[other] > 0 {
                valid_pairs -= 2;
            }
        }

        if valid_pairs <= 0 {
            continue;
        }

        for a in 1..pair_sum {
            let b = pair_sum - a;
            if counts[a] == 0 || counts[b] == 0 {
                continue;
            }

            let need_a = 1 + (b == a) as u32 + (c == a) as u32;
            let need_b = 1 + (a == b) as u32 + (c == b) as u32;
            let need_c = 1 + (a == c) as u32 + (b == c) as u32;

            if counts[a] < need_a || counts[b] < need_b || counts[c] < need_c {
                continue;
            }

            let values = [a, b, c];
            let mut indices = [0u32; 3];

            for q in 0..3 {
                let mut occurrence = 0usize;
                for previous in 0..q {
                    if values[previous] == values[q] {
                        occurrence += 1;
                    }
                }
                indices[q] = positions[values[q]][occurrence];
            }

            indices.sort();
            answer = Some(indices);
            break;
        }

        if answer.is_some() {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if let Some([i, j, k]) = answer {
        writeln!(out, "{} {} {}", i, j, k).unwrap();
    } else {
        writeln!(out, "-1").unwrap();
    }
}
