fn main() {
    const MOD: u64 = 998_244_353;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let max_a = *a.iter().max().unwrap();

    // Euler's totient function for every value up to max_a.
    let mut phi: Vec<u64> = (0..=max_a).map(|x| x as u64).collect();
    for p in 2..=max_a {
        if phi[p] == p as u64 {
            for multiple in (p..=max_a).step_by(p) {
                phi[multiple] -= phi[multiple] / p as u64;
            }
        }
    }

    // Precompute all divisors of every possible A_i.
    let mut divisors = vec![Vec::<usize>::new(); max_a + 1];
    for d in 1..=max_a {
        for multiple in (d..=max_a).step_by(d) {
            divisors[multiple].push(d);
        }
    }

    // weighted_multiples[d] is the sum of 2^(i-1) over processed
    // positions i such that d divides A_i.
    let mut weighted_multiples = vec![0u64; max_a + 1];

    let mut answer = 0u64;
    let mut position_weight = 1u64;
    let mut output = String::new();

    for &x in &a {
        let mut added = 0u64;

        for &d in &divisors[x] {
            added += phi[d] * weighted_multiples[d];

            let value = weighted_multiples[d] + position_weight;
            weighted_multiples[d] = if value >= MOD { value - MOD } else { value };
        }

        added %= MOD;
        answer = (2 * answer + added) % MOD;
        output.push_str(&format!("{}\n", answer));

        position_weight *= 2;
        if position_weight >= MOD {
            position_weight -= MOD;
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
