use std::collections::HashMap;
use std::io::{self, Read, Write};

const MOD: u32 = 998_244_353;

fn mod_pow(mut base: u32, mut exp: usize) -> u32 {
    let mut result = 1u64;
    let mut b = base as u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * b % MOD as u64;
        }
        b = b * b % MOD as u64;
        exp >>= 1;
    }
    result as u32
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    if k == 0 {
        let question_count = s.iter().filter(|&&c| c == b'?').count();
        let answer = mod_pow(3, question_count);
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        writeln!(out, "{answer}").unwrap();
        return;
    }

    let base = n + 2;

    // The key stores (count[0], count[1], count[2], current_state).
    // count[3] is determined by the total number of visited prefix states.
    let pack = |c0: usize, c1: usize, c2: usize, state: usize| -> usize {
        (((c0 * base + c1) * base + c2) << 2) | state
    };

    let mut dp: HashMap<usize, u32> = HashMap::new();
    dp.insert(pack(1, 0, 0, 0), 1);

    for &ch in s {
        let allowed = match ch {
            b'A' => 1usize << 1,
            b'B' => 1usize << 2,
            b'C' => 1usize << 3,
            b'?' => (1usize << 1) | (1usize << 2) | (1usize << 3),
            _ => unreachable!(),
        };

        let multiplier = if ch == b'?' { 3 } else { 1 };
        let mut next = HashMap::with_capacity(dp.len() * multiplier);

        for (&key, &ways) in &dp {
            let state = key & 3;
            let mut encoded = key >> 2;

            let c2 = encoded % base;
            encoded /= base;
            let c1 = encoded % base;
            let c0 = encoded / base;

            for delta in 1..=3 {
                if allowed & (1usize << delta) == 0 {
                    continue;
                }

                let next_state = state ^ delta;
                let (mut nc0, mut nc1, mut nc2) = (c0, c1, c2);

                match next_state {
                    0 => nc0 += 1,
                    1 => nc1 += 1,
                    2 => nc2 += 1,
                    3 => {}
                    _ => unreachable!(),
                }

                let next_key = pack(nc0, nc1, nc2, next_state);
                let entry = next.entry(next_key).or_insert(0);
                let sum = *entry + ways;
                *entry = if sum >= MOD { sum - MOD } else { sum };
            }
        }

        dp = next;
    }

    let mut answer = 0u32;
    let total_prefixes = n + 1;

    for (&key, &ways) in &dp {
        let mut encoded = key >> 2;

        let c2 = encoded % base;
        encoded /= base;
        let c1 = encoded % base;
        let c0 = encoded / base;
        let c3 = total_prefixes - c0 - c1 - c2;

        let counts = [c0, c1, c2, c3];
        let good_substrings: usize =
            counts.iter().map(|&c| c * (c - 1) / 2).sum();

        if good_substrings >= k {
            let sum = answer + ways;
            answer = if sum >= MOD { sum - MOD } else { sum };
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
