use std::io::{self, Read, Write};

const MOD: u32 = 998_244_353;

#[inline]
fn add_mod(dst: &mut u32, value: u32) {
    let sum = *dst + value;
    *dst = if sum >= MOD { sum - MOD } else { sum };
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    // Prefix parity vectors are considered modulo (1,1,1), yielding four states.
    // A, B, and C correspond to XOR masks 1, 2, and 3 respectively.
    let d = n + 2;
    let size = d * d * d * 4;
    let mut dp = vec![0u32; size];
    let mut next = vec![0u32; size];

    // Initially, state 0 has been visited once.
    let initial_index = ((d * d) * 4);
    dp[initial_index] = 1;

    let index = |c0: usize, c1: usize, c2: usize, state: usize| -> usize {
        (((c0 * d + c1) * d + c2) * 4) + state
    };

    for (pos, &ch) in s.iter().enumerate() {
        next.fill(0);
        let visits = pos + 1;

        let (masks, mask_count): ([usize; 3], usize) = match ch {
            b'A' => ([1, 0, 0], 1),
            b'B' => ([2, 0, 0], 1),
            b'C' => ([3, 0, 0], 1),
            b'?' => ([1, 2, 3], 3),
            _ => unreachable!(),
        };

        for c0 in 0..=visits {
            for c1 in 0..=visits - c0 {
                for c2 in 0..=visits - c0 - c1 {
                    let c3 = visits - c0 - c1 - c2;

                    for state in 0..4 {
                        let value = dp[index(c0, c1, c2, state)];
                        if value == 0 {
                            continue;
                        }

                        for &mask in &masks[..mask_count] {
                            let new_state = state ^ mask;
                            let (nc0, nc1, nc2) = match new_state {
                                0 => (c0 + 1, c1, c2),
                                1 => (c0, c1 + 1, c2),
                                2 => (c0, c1, c2 + 1),
                                3 => {
                                    let _ = c3;
                                    (c0, c1, c2)
                                }
                                _ => unreachable!(),
                            };

                            let next_index = index(nc0, nc1, nc2, new_state);
                            add_mod(&mut next[next_index], value);
                        }
                    }
                }
            }
        }

        std::mem::swap(&mut dp, &mut next);
    }

    let total_visits = n + 1;
    let mut answer = 0u32;

    for c0 in 0..=total_visits {
        for c1 in 0..=total_visits - c0 {
            for c2 in 0..=total_visits - c0 - c1 {
                let c3 = total_visits - c0 - c1 - c2;
                let good_substrings =
                    c0 * (c0 - 1) / 2
                    + c1 * (c1 - 1) / 2
                    + c2 * (c2 - 1) / 2
                    + c3 * (c3 - 1) / 2;

                if good_substrings >= k {
                    for state in 0..4 {
                        add_mod(&mut answer, dp[index(c0, c1, c2, state)]);
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
