use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::<(usize, u8)>::new(); n];
    let mut first_target = vec![usize::MAX; n];
    let mut first_claim = vec![0u8; n];

    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: u8 = iter.next().unwrap().parse().unwrap();

        if first_target[a] == usize::MAX {
            first_target[a] = b;
            first_claim[a] = c;
        } else {
            let other = first_target[a];
            let parity = first_claim[a] ^ c;
            graph[other].push((b, parity));
            graph[b].push((other, parity));
        }
    }

    // liar[i] is 1 if villager i is assigned as a liar, 0 if honest.
    let mut liar = vec![-1i8; n];
    let mut stack = Vec::new();

    for start in 0..n {
        if liar[start] != -1 {
            continue;
        }

        liar[start] = 0;
        stack.push(start);

        while let Some(v) = stack.pop() {
            let current = liar[v] as u8;

            for &(to, parity) in &graph[v] {
                let required = current ^ parity;
                if liar[to] == -1 {
                    liar[to] = required as i8;
                    stack.push(to);
                } else if liar[to] as u8 != required {
                    let mut out = io::BufWriter::new(io::stdout().lock());
                    writeln!(out, "-1").unwrap();
                    return;
                }
            }
        }
    }

    let mut answer = String::with_capacity(n);
    for a in 0..n {
        let confused = if first_target[a] == usize::MAX {
            0
        } else {
            first_claim[a] ^ (liar[first_target[a]] as u8) ^ (liar[a] as u8)
        };
        answer.push(if confused == 1 { '1' } else { '0' });
    }

    let mut out = io::BufWriter::new(io::stdout().lock());
    writeln!(out, "{answer}").unwrap();
}
