use std::io::{self, Read, Write};

struct ParityDsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    parity: Vec<u8>, // value[node] XOR value[parent[node]]
}

impl ParityDsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            parity: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> (usize, u8) {
        if self.parent[x] == x {
            return (x, 0);
        }
        let parent = self.parent[x];
        let (root, parent_parity) = self.find(parent);
        self.parity[x] ^= parent_parity;
        self.parent[x] = root;
        (root, self.parity[x])
    }

    // Enforces value[a] XOR value[b] = required.
    fn unite(&mut self, a: usize, b: usize, required: u8) -> bool {
        let (ra, pa) = self.find(a);
        let (rb, pb) = self.find(b);

        if ra == rb {
            return (pa ^ pb) == required;
        }

        let root_parity = pa ^ pb ^ required;
        if self.size[ra] < self.size[rb] {
            self.parent[ra] = rb;
            self.parity[ra] = root_parity;
            self.size[rb] += self.size[ra];
        } else {
            self.parent[rb] = ra;
            self.parity[rb] = root_parity;
            self.size[ra] += self.size[rb];
        }
        true
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut dsu = ParityDsu::new(n);
    let mut representative_b = vec![usize::MAX; n];
    let mut representative_c = vec![0u8; n];
    let mut possible = true;

    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: u8 = iter.next().unwrap().parse().unwrap();

        if representative_b[a] == usize::MAX {
            representative_b[a] = b;
            representative_c[a] = c;
        } else {
            let first_b = representative_b[a];
            let required = representative_c[a] ^ c;
            if !dsu.unite(first_b, b, required) {
                possible = false;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if !possible {
        writeln!(out, "-1").unwrap();
        return;
    }

    let mut status = vec![0u8; n];
    for i in 0..n {
        let (_, parity) = dsu.find(i);
        status[i] = parity;
    }

    let mut answer = vec![b'0'; n];
    for a in 0..n {
        if representative_b[a] != usize::MAX {
            let b = representative_b[a];
            let confused = representative_c[a] ^ status[a] ^ status[b];
            answer[a] = b'0' + confused;
        }
    }

    writeln!(out, "{}", String::from_utf8(answer).unwrap()).unwrap();
}
