use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let max_ops = n / 2;
    let mut fact = vec![1u64; max_ops + 1];
    for i in 1..=max_ops {
        fact[i] = fact[i - 1] * i as u64 % MOD;
    }

    let mut inv_fact = vec![1u64; max_ops + 1];
    if max_ops > 0 {
        inv_fact[max_ops] = mod_pow(fact[max_ops], MOD - 2);
        for i in (1..=max_ops).rev() {
            inv_fact[i - 1] = inv_fact[i] * i as u64 % MOD;
        }
    }

    let mut double_fact = vec![1u64; max_ops + 1];
    for q in 1..=max_ops {
        double_fact[q] = double_fact[q - 1] * (2 * q - 1) as u64 % MOD;
    }

    let mut blocks = Vec::new();
    let mut left = 0usize;
    let mut valid = true;

    while left < n {
        let mut right = left + 1;
        while right < n && a[right] == a[left] {
            right += 1;
        }

        let len = right - left;
        let initial_value = (left + 1) % 2;

        if len % 2 == 0 || a[left] != initial_value {
            valid = false;
            break;
        }

        blocks.push((len - 1) / 2);
        left = right;
    }

    let answer = if !valid {
        0
    } else {
        let total_ops: usize = blocks.iter().sum();
        let mut ans = fact[total_ops];

        for q in blocks {
            ans = ans * inv_fact[q] % MOD;
            ans = ans * double_fact[q] % MOD;
        }

        ans
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
