    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut segment_operations = Vec::new();
    let mut start = 0;

    while start < n {
        let mut end = start + 1;
        while end < n && a[end] == a[start] {
            end += 1;
        }

        let len = end - start;
        let initial_value = (start + 1) % 2;

        if len % 2 == 0 || a[start] != initial_value {
            let stdout = io::stdout();
            let mut out = io::BufWriter::new(stdout.lock());
            writeln!(out, "0").unwrap();
            return;
        }

        segment_operations.push((len - 1) / 2);
        start = end;
    }

    let total_operations: usize = segment_operations.iter().sum();

    let mut factorial = vec![1_i64; total_operations + 1];
    for i in 1..=total_operations {
        factorial[i] = factorial[i - 1] * i as i64 % MOD;
    }

    let mut inv_factorial = vec![1_i64; total_operations + 1];
    inv_factorial[total_operations] =
        mod_pow(factorial[total_operations], MOD - 2);
    for i in (1..=total_operations).rev() {
        inv_factorial[i - 1] = inv_factorial[i] * i as i64 % MOD;
    }

    let max_k = segment_operations.iter().copied().max().unwrap_or(0);
    let mut odd_double_factorial = vec![1_i64; max_k + 1];
    for k in 1..=max_k {
        odd_double_factorial[k] =
            odd_double_factorial[k - 1] * (2 * k - 1) as i64 % MOD;
    }

    let mut answer = factorial[total_operations];
    for k in segment_operations {
        answer = answer * odd_double_factorial[k] % MOD;
        answer = answer * inv_factorial[k] % MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
