use std::io::{self, Read, Write};

fn find(parent: &mut [usize], x: usize) -> usize {
    let mut root = x;
    while parent[root] != root {
        root = parent[root];
    }

    let mut cur = x;
    while parent[cur] != cur {
        let next = parent[cur];
        parent[cur] = root;
        cur = next;
    }
    root
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a = vec![0i64; n + 1];
    let mut prefix = vec![0i64; n + 1];

    for i in 1..=n {
        a[i] = it.next().unwrap().parse().unwrap();
        prefix[i] = prefix[i - 1] + a[i];
    }

    // For expansion to the right:
    // position j is a blocker for left endpoint l iff
    // A[j] >= sum(l..j-1), equivalently
    // D[j] = prefix[j-1] - A[j] <= prefix[l-1].
    let mut d = vec![0i64; n + 1];

    // For expansion to the left:
    // position j is a blocker for right endpoint r iff
    // A[j] >= sum(j+1..r), equivalently
    // E[j] = A[j] + prefix[j] >= prefix[r].
    let mut e = vec![0i64; n + 1];

    for i in 1..=n {
        d[i] = prefix[i - 1] - a[i];
        e[i] = a[i] + prefix[i];
    }

    let mut order_d: Vec<usize> = (1..=n).collect();
    order_d.sort_unstable_by(|&x, &y| d[y].cmp(&d[x]));

    let mut order_e: Vec<usize> = (1..=n).collect();
    order_e.sort_unstable_by(|&x, &y| e[x].cmp(&e[y]));

    let mut left: Vec<usize> = (0..=n).collect();
    let mut right: Vec<usize> = (0..=n).collect();

    let none = usize::MAX;
    let mut head = vec![none; n + 1];
    let mut next = vec![none; n + 1];
    let mut parent = vec![0usize; n + 2];

    loop {
        let mut changed = false;

        // Expand every interval to the right.
        head.fill(none);
        for k in 1..=n {
            let key = left[k];
            next[k] = head[key];
            head[key] = k;
        }

        for i in 0..=n + 1 {
            parent[i] = i;
        }

        let mut ptr = 0usize;
        for l in (1..=n).rev() {
            let threshold = prefix[l - 1];

            while ptr < n && d[order_d[ptr]] > threshold {
                let pos = order_d[ptr];
                let successor = find(&mut parent, pos + 1);
                parent[pos] = successor;
                ptr += 1;
            }

            let mut k = head[l];
            while k != none {
                let blocker = find(&mut parent, right[k] + 1);
                let new_right = if blocker == n + 1 { n } else { blocker - 1 };

                if new_right > right[k] {
                    right[k] = new_right;
                    changed = true;
                }
                k = next[k];
            }
        }

        // Expand every interval to the left.
        head.fill(none);
        for k in 1..=n {
            let key = right[k];
            next[k] = head[key];
            head[key] = k;
        }

        for i in 0..=n + 1 {
            parent[i] = i;
        }

        ptr = 0;
        for r in 1..=n {
            let threshold = prefix[r];

            while ptr < n && e[order_e[ptr]] < threshold {
                let pos = order_e[ptr];
                let predecessor = find(&mut parent, pos - 1);
                parent[pos] = predecessor;
                ptr += 1;
            }

            let mut k = head[r];
            while k != none {
                let blocker = find(&mut parent, left[k] - 1);
                let new_left = blocker + 1;

                if new_left < left[k] {
                    left[k] = new_left;
                    changed = true;
                }
                k = next[k];
            }
        }

        if !changed {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for k in 1..=n {
        if k > 1 {
            write!(out, " ").unwrap();
        }
        let answer = prefix[right[k]] - prefix[left[k] - 1];
        write!(out, "{answer}").unwrap();
    }
    writeln!(out).unwrap();
}
